// ── PERSISTENCIA DE SESIÓN Y ROUTING SPA ──
const _SESS_KEY='gyc_sess_v1';
function _saveSessState(){
  try{
    const st={sesion:sesion,pag:pag,platSK:window._currentPlatSK||null,platId:window._currentPlatId||null,gestorSesion:gestorSesion,gestorEnPlataforma:gestorEnPlataforma};
    sessionStorage.setItem(_SESS_KEY,JSON.stringify(st));
  }catch(e){}
}
function _clearSessState(){try{sessionStorage.removeItem(_SESS_KEY);}catch(e){}}
function _restoreSessState(){
  try{
    const raw=sessionStorage.getItem(_SESS_KEY);
    if(!raw) return false;
    const st=JSON.parse(raw);
    if(!st||!st.sesion) return false;
    sesion=st.sesion;
    if(st.pag) pag=st.pag;
    if(st.platSK) window._currentPlatSK=st.platSK;
    if(st.platId) window._currentPlatId=st.platId;
    if(st.gestorSesion) gestorSesion=st.gestorSesion;
    if(st.gestorEnPlataforma) gestorEnPlataforma=st.gestorEnPlataforma;
    return true;
  }catch(e){return false;}
}
function _routeKeyForSess(){
  if(!sesion) return '';
  const r=sesion.r||'docente';
  const pid=window._currentPlatId||'';
  if(gestorSesion) return 'gestor-admin';
  if(r==='admin') return 'gestor-admin';
  if(r==='docente') return pid?('inst-'+pid+'-doc'):'docente';
  if(r==='padre') return pid?('inst-'+pid+'-padre'):'padre';
  if(r==='estudiante') return pid?('inst-'+pid+'-est'):'estudiante';
  if(r==='elecciones') return pid?('inst-'+pid+'-elecc'):'elecciones';
  return r;
}
function _updateUrlRoute(){
  const key=_routeKeyForSess();
  if(!key) return;
  const url=new URL(window.location.href);
  url.searchParams.set('_x',key);
  window.history.replaceState({pag:pag,key:key},'',url.toString());
}
function _pushHistoryState(){
  const key=_routeKeyForSess();
  if(!key) return;
  const url=new URL(window.location.href);
  url.searchParams.set('_x',key);
  window.history.pushState({pag:pag,key:key},'',url.toString());
}
window.addEventListener('popstate',function(ev){
  try{
    const st=ev.state;
    if(st&&st.pag){
      pag=st.pag;
      render();
    } else {
      render();
    }
  }catch(e){render();}
});
