// ── ZOOM DE FOTO DE ESTUDIANTE ──
function abrirZoomFoto(src,nombre,ev){
  if(ev){ev.preventDefault();ev.stopPropagation();}
  let ov=document.getElementById('_photoZoomOv');
  if(!ov){
    ov=document.createElement('div');
    ov.id='_photoZoomOv';
    ov.className='photo-zoom-ov';
    ov.innerHTML='<button class="pz-close" onclick="cerrarZoomFoto()" title="Cerrar">✕</button><img id="_photoZoomImg" src="" alt=""><div class="pz-name" id="_photoZoomName"></div>';
    ov.addEventListener('click',function(e){if(e.target===ov)cerrarZoomFoto();});
    document.body.appendChild(ov);
  }
  document.getElementById('_photoZoomImg').src=src;
  document.getElementById('_photoZoomName').textContent=nombre||'';
  ov.classList.add('open');
  document.body.style.overflow='hidden';
}
function cerrarZoomFoto(){
  const ov=document.getElementById('_photoZoomOv');
  if(ov)ov.classList.remove('open');
  document.body.style.overflow='';
}

// ============================================================
// S02 · ESQUEMA DE BASE DE DATOS Y MIGRACIÓN AUTOMÁTICA
// Garantiza que datos viejos se actualicen sin conflictos.
// Al agregar nuevos campos a DDB/BLANK_INST_DB, los respaldos
// anteriores los reciben automáticamente con su valor por defecto.
// CÓMO AGREGAR NUEVOS CAMPOS AL SISTEMA:
//   1. Agregar el campo con su valor por defecto en DDB y BLANK_INST_DB
//   2. Incrementar SCHEMA_VERSION en 1
//   3. Registrar los nuevos campos en SCHEMA_NEW_FIELDS[nueva_versión]
//   4. La migración es automática — no se requiere más código
// ============================================================
// VERSIÓN ACTUAL DEL ESQUEMA — incrementar cuando se agreguen nuevos campos
const SCHEMA_VERSION = 9;
// Lista de campos nuevos por versión (para notificar al usuario qué diligenciar)
const SCHEMA_NEW_FIELDS = {
  2: ['actas','actasPdf','planesArea','planeaciones','materialEstudiantes','observadores','elecciones','historiales','asistencia','centrosInteres','preMatriculas'],
  3: ['cronograma','config','periodosActivos'],
  4: ['modalidad','linkClase','pension','actividadesInteractivas','actividades','actEntregas','evaluaciones','evalRespuestas','evalDocente'],
  5: ['depto','resolucion','firmaRectora','escudoColombia','autoPromocion','configHorario','pesosArea','pesosAsig'],
  6: ['Acceso Eval. Desempeño por docente (driveEvalAcceso)','Decreto docente (decreto)','Modalidad decreto 1278 (modalidadDecre)','Nivel formación académica (nivelFormacion)'],
  7: ['Tipo pregrado (tipoPregrado: Licenciado / Profesional No Licenciado)','Nivel posgrado (nivelPosgrado)','Título posgrado (tituloPosgrado)'],
  8: ['Planeaciones generadas por Adán IA (planeacionesIA)'],
  9: ['Traslado de estudiantes entre grados con conservación de notas (función habilitada)','Edición de nombre de grado vía modal','encabezado y piePagina en documentos']
};

function _getNewFields(oldVersion){
  const newFields=[];
  for(let v=((oldVersion||0)+1);v<=SCHEMA_VERSION;v++){
    if(SCHEMA_NEW_FIELDS[v]) newFields.push(...SCHEMA_NEW_FIELDS[v]);
  }
  return [...new Set(newFields)];
}

// ─── Fusión profunda recursiva ────────────────────────────────────────────────
// Para cada clave de `defaults`:
//   • Si no existe en `src` o es null/undefined → usa el valor por defecto
//   • Si ambos son objetos planos → fusión recursiva (agrega subclaves nuevas)
//   • Si ambos son arrays o tipos primitivos → preserva el valor de `src`
// Esto garantiza que cualquier campo nuevo agregado en versiones futuras
// (incluyendo campos anidados dentro de objetos) se añada automáticamente
// a respaldos anteriores sin sobreescribir los datos existentes del usuario.
function _deepMergeWithDefaults(defaults, src){
  if(!src||typeof src!=='object'||Array.isArray(src)) return src;
  const result=Object.assign({},src);
  Object.keys(defaults).forEach(function(k){
    const defVal=defaults[k];
    const srcVal=result[k];
    if(srcVal===null||srcVal===undefined){
      // Campo completamente ausente: usar copia del valor por defecto
      result[k]=defVal&&typeof defVal==='object'?JSON.parse(JSON.stringify(defVal)):defVal;
    } else if(defVal&&typeof defVal==='object'&&!Array.isArray(defVal)&&
              srcVal&&typeof srcVal==='object'&&!Array.isArray(srcVal)){
      // Ambos son objetos planos: fusión recursiva
      result[k]=_deepMergeWithDefaults(defVal,srcVal);
    }
    // Arrays y primitivos: ya está en result desde Object.assign({}, src)
  });
  return result;
}

function _migrateDB(data){
  if(!data||typeof data!=='object') return JSON.parse(JSON.stringify(DDB));
  const oldVersion=data._schemaVersion||0;
  // Fusión profunda: todos los campos de DDB que falten en data se añaden con
  // sus valores por defecto. Los datos existentes del respaldo se preservan.
  const migrated=_deepMergeWithDefaults(DDB,Object.assign({},DDB,data));
  // Arrays: cualquier clave de DDB que sea array y no sea array en data → []
  Object.keys(DDB).forEach(function(k){
    if(Array.isArray(DDB[k])&&!Array.isArray(migrated[k])) migrated[k]=[];
  });
  // Objetos planos: cualquier clave de DDB que sea objeto simple y falte → defecto
  Object.keys(DDB).forEach(function(k){
    if(DDB[k]&&typeof DDB[k]==='object'&&!Array.isArray(DDB[k])&&(!migrated[k]||typeof migrated[k]!=='object')){
      migrated[k]=JSON.parse(JSON.stringify(DDB[k]));
    }
  });
  // Config — fusión profunda (preservar valores + agregar nuevas subclaves)
  migrated.config=_deepMergeWithDefaults(DDB.config||{},Object.assign({},DDB.config||{},data.config||{}));
  if(!migrated.config.pesosArea||typeof migrated.config.pesosArea!=='object') migrated.config.pesosArea={};
  if(!migrated.config.pesosAsig||typeof migrated.config.pesosAsig!=='object') migrated.config.pesosAsig={};
  // configHorario — fusión profunda
  if(data.configHorario&&typeof data.configHorario==='object'){
    migrated.configHorario=_deepMergeWithDefaults(DDB.configHorario||{},data.configHorario);
  } else if(!migrated.configHorario||typeof migrated.configHorario!=='object'){
    migrated.configHorario={};
  }
  // Cronograma — fusión profunda
  if(data.cronograma&&typeof data.cronograma==='object'){
    migrated.cronograma=_deepMergeWithDefaults(DDB.cronograma||{},Object.assign({},DDB.cronograma||{},data.cronograma));
  } else if(!migrated.cronograma||typeof migrated.cronograma!=='object'){
    migrated.cronograma=JSON.parse(JSON.stringify(DDB.cronograma||{}));
  }
  // Migración de estudiantes: IDs siempre como string + nombre estructurado 4 campos
  if(Array.isArray(migrated.ests)){
    migrated.ests=migrated.ests.map(function(e){
      // Normalizar ID a string para evitar errores de comparación
      if(e.id!==undefined) e.id=String(e.id);
      // Si ya tiene los 4 campos de nombre, no tocar
      if(e.apellido1||e.nombre1){
        // Pero si viene de pre-matrícula con apellidos/nombres en formato invertido, parsear
        if(!e.apellido1&&e.apellidos){
          const aps=(e.apellidos||'').trim().toUpperCase().split(/\s+/);
          e.apellido1=aps[0]||'';
          e.apellido2=aps.slice(1).join(' ')||'';
        }
        if(!e.nombre1&&e.nombres){
          const nms=(e.nombres||'').trim().toUpperCase().split(/\s+/);
          e.nombre1=nms[0]||'';
          e.nombre2=nms.slice(1).join(' ')||'';
        }
        return e;
      }
      // Primero intentar parsear desde campos apellidos/nombres (pre-matrícula)
      if(e.apellidos||e.nombres){
        const aps=(e.apellidos||'').trim().toUpperCase().split(/\s+/);
        const nms=(e.nombres||'').trim().toUpperCase().split(/\s+/);
        e.apellido1=aps[0]||'';
        e.apellido2=aps.slice(1).join(' ')||'';
        e.nombre1=nms[0]||'';
        e.nombre2=nms.slice(1).join(' ')||'';
        // Reconstruir nombre completo en formato correcto
        e.n=[e.apellido1,e.apellido2,e.nombre1,e.nombre2].filter(Boolean).join(' ');
        return e;
      }
      // Parsear nombre completo: "APELLIDO1 APELLIDO2 NOMBRE1 NOMBRE2"
      const partes=(e.n||'').trim().toUpperCase().split(/\s+/);
      if(partes.length>=2){
        e.apellido1=partes[0]||'';
        e.apellido2=partes.length>=4?partes[1]:(partes.length===3?partes[1]:'');
        e.nombre1=partes.length>=4?partes[2]:(partes.length===3?partes[2]:partes[1])||'';
        e.nombre2=partes.length>=4?partes.slice(3).join(' '):'';
      } else {
        e.apellido1=partes[0]||'';e.apellido2='';e.nombre1='';e.nombre2='';
      }
      return e;
    });
  }
  // Limpiar nombre de institución: eliminar " BOLÍVAR" al final si existe
  if(migrated.nombre && /\s+BOL[IÍ]VAR\s*$/i.test(migrated.nombre)){
    migrated.nombre=migrated.nombre.replace(/\s+BOL[IÍ]VAR\s*$/i,'').trim();
  }
  migrated._schemaVersion=SCHEMA_VERSION;
  // Guardar versión anterior para notificación
  migrated._prevSchemaVersion=oldVersion;
  return migrated;
}

// Muestra banner si el respaldo cargado tenía una versión de esquema anterior
function _checkSchemaMigrationBanner(){
  // Solo mostrar si el respaldo tenía una versión explícita anterior (no instalación nueva).
  // _prevSchemaVersion es undefined cuando no se migró ningún respaldo (nuevo o ya actualizado).
  if(db._prevSchemaVersion===undefined||db._prevSchemaVersion===null) return;
  const prev=db._prevSchemaVersion;
  if(prev>=SCHEMA_VERSION) return;
  const newFields=_getNewFields(prev);
  // Mostrar banner solo una vez por sesión
  const bannerKey='_schemaBannerShown_v'+SCHEMA_VERSION+'_from'+prev;
  if(sessionStorage.getItem(bannerKey)) return;
  sessionStorage.setItem(bannerKey,'1');
  // Modal de notificación de migración
  setTimeout(function(){
    if(document.getElementById('_schemaMigModal')) return;
    const overlay=document.createElement('div');
    overlay.id='_schemaMigModal';
    overlay.style.cssText='position:fixed;inset:0;z-index:999999;background:rgba(0,0,0,0.65);display:flex;align-items:center;justify-content:center;padding:16px';
    const camposHtml=newFields.length
      ?'<ul style="margin:8px 0 12px 0;padding-left:20px;font-size:0.85rem;max-height:160px;overflow-y:auto">'+newFields.map(function(f){return '<li style="margin-bottom:4px;color:#e8f0fe">'+f+'</li>';}).join('')+'</ul>'
      :'<p style="font-size:0.85rem;color:#e8f0fe;margin-bottom:12px">La estructura fue actualizada a la versión más reciente sin campos nuevos pendientes.</p>';
    overlay.innerHTML='<div style="background:#1a3a5c;color:#fff;border-radius:16px;padding:28px 28px 22px;max-width:540px;width:100%;box-shadow:0 8px 40px rgba(0,0,0,0.5);border:1px solid rgba(241,196,15,0.3)">'
      +'<div style="display:flex;align-items:center;gap:12px;margin-bottom:14px">'
      +'<span style="font-size:2rem">🔄</span>'
      +'<div><div style="font-size:1.05rem;font-weight:700;color:#f1c40f">Respaldo migrado exitosamente</div>'
      +'<div style="font-size:0.78rem;color:#b0c4de;margin-top:2px">Versión anterior: v'+prev+' → Versión actual: v'+SCHEMA_VERSION+'</div></div></div>'
      +(newFields.length
        ?'<p style="font-size:0.88rem;color:#b0c4de;margin-bottom:6px">Los siguientes <b>campos nuevos</b> fueron agregados con valores vacíos. Diligéncielos en Configuración cuando lo desee — sus datos anteriores <b>no fueron alterados</b>:</p>'+camposHtml
        :camposHtml)
      +'<div style="background:rgba(241,196,15,0.1);border:1px solid rgba(241,196,15,0.3);border-radius:8px;padding:10px 14px;font-size:0.82rem;color:#f1c40f;margin-bottom:16px">✅ Todos sus datos anteriores han sido conservados íntegramente.</div>'
      +'<button onclick="document.getElementById(\'_schemaMigModal\').remove()" style="background:#f1c40f;color:#001428;border:none;border-radius:8px;padding:10px 28px;font-size:0.9rem;font-weight:700;cursor:pointer;width:100%">✔ Entendido — Continuar al sistema</button>'
      +'</div>';
    document.body.appendChild(overlay);
  },800);
}

function loadDB(sk){
  sk=sk||SK;
  try{const s=localStorage.getItem(sk);if(s){const p=JSON.parse(s);return _migrateDB(p);}}catch(e){}
  let _d=JSON.parse(JSON.stringify(DDB));
  if(typeof _seedDBIfEmpty==='function') _d=_seedDBIfEmpty(_d);
  return _d;
}
let _saveTimer=null;
function saveDB(){
  const _sk=window._currentPlatSK||SK;
  try{localStorage.setItem(_sk,JSON.stringify(db));}catch(e){}
  if(_saveTimer) clearTimeout(_saveTimer);
  // Background auto-save: swallow errors silently (fire-and-forget)
  _saveTimer=setTimeout(function(){_pushDB().catch(function(){});},350);
}
function _pushDB(){
  // Returns a Promise that REJECTS on network failure OR non-OK HTTP status.
  // Callers are responsible for handling errors — no internal .catch() here.
  const _sk=window._currentPlatSK||SK;
  return fetch(API_BASE+'/api/inetis/db',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sk:_sk,data:db})})
    .then(function(r){
      if(!r.ok) throw new Error('HTTP '+r.status+' '+r.statusText);
      return r;
    });
}
async function _pullDB(){
  try{
    const _sk=window._currentPlatSK||SK||GESTOR_SK;
    const r=await fetch(API_BASE+'/api/inetis/db?sk='+encodeURIComponent(_sk));
    if(r.ok){const j=await r.json();if(j&&j.data){
      const _serverData=_migrateDB(j.data);
      const _localTS=db._localTS||0;
      const _serverTS=_serverData._localTS||0;
      if(_serverTS>=_localTS){
        db=_serverData;
        try{localStorage.setItem(_sk,JSON.stringify(db));}catch(e){}
      } else {
        // Local is newer — push to server instead of overwriting
        try{await fetch(API_BASE+'/api/inetis/db',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sk:_sk,data:db})});}catch(e){}
      }
      return true;
    }}
  }catch(e){}return false;
}
function updDB(fn){ db=fn(JSON.parse(JSON.stringify(db))); db._localTS=Date.now(); saveDB(); }

