window._gestorIAmsgList=[];
window._gestorIAstreaming=false;
window._gestorIAVozRec=null;
function gestorIAsugerencia(txt){const ta=document.getElementById('gestorIAinput');if(ta){ta.value=txt;gestorIAenviar();}}
function gestorIAVoz(){
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){alert('Use Chrome o Edge para voz.');return;}
  const btn=document.getElementById('gestorIAVozBtn');
  if(window._gestorIAVozRec){try{window._gestorIAVozRec.stop();}catch(e){}window._gestorIAVozRec=null;if(btn){btn.textContent='🎙️ Voz';btn.style.background='#6c3483';}return;}
  const rec=new SR();rec.lang='es-CO';rec.continuous=false;rec.interimResults=false;
  window._gestorIAVozRec=rec;if(btn){btn.textContent='⏹ Detener';btn.style.background='#c0392b';}
  rec.onresult=function(ev){const txt=(ev.results[0]&&ev.results[0][0]&&ev.results[0][0].transcript)||'';const ta=document.getElementById('gestorIAinput');if(ta&&txt){ta.value=txt;gestorIAenviar();}window._gestorIAVozRec=null;if(btn){btn.textContent='🎙️ Voz';btn.style.background='#6c3483';}};
  rec.onerror=function(){window._gestorIAVozRec=null;if(btn){btn.textContent='🎙️ Voz';btn.style.background='#6c3483';}};
  try{rec.start();}catch(e){window._gestorIAVozRec=null;}
}
async function gestorIAenviar(){
  if(window._gestorIAstreaming) return;
  const ta=document.getElementById('gestorIAinput');const txt=(ta?ta.value.trim():'');if(!txt) return;
  ta.value='';
  if(!window._gestorIAmsgList) window._gestorIAmsgList=[];
  window._gestorIAmsgList.push({role:'user',content:txt});
  window._gestorIAstreaming=true;gestorIArenderMsgs();
  const ctx={institucion:'Gestor Académico YC',modulo:'admin-general',usuario:(gestorDB&&gestorDB.superAdmin&&gestorDB.superAdmin.nombre)||'Admin',rol:'admin-gestor',anio:new Date().getFullYear().toString(),gestorMode:true};
  window._gestorIAmsgList.push({role:'assistant',content:'',loading:true});gestorIArenderMsgs();
  try{
    const r=await fetch(API_BASE+'/api/inetis/ai/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:window._gestorIAmsgList.filter(m=>!m.loading).slice(-20),context:ctx})});
    if(!r.ok) throw new Error('HTTP '+r.status);
    let resp='';
    if(r.body){
      const reader=r.body.getReader();const dec=new TextDecoder();let buf='';
      while(true){const {done,value}=await reader.read();if(done) break;
        buf+=dec.decode(value,{stream:true});const parts=buf.split('\n\n');buf=parts.pop()||'';
        for(const part of parts){if(!part.startsWith('data:')) continue;
          try{const d=JSON.parse(part.slice(5).trim());
            if(d.done){break;}
            if(d.error){resp='❌ '+d.error;break;}
            if(d.content){resp+=d.content;window._gestorIAmsgList[window._gestorIAmsgList.length-1]={role:'assistant',content:resp,loading:false};gestorIArenderMsgs();}}catch(e){}}}
    } else {
      const txt2=await r.text();
      const lines=txt2.split('\n');
      for(const line of lines){if(!line.startsWith('data:')) continue;
        try{const d=JSON.parse(line.slice(5).trim());if(d.content) resp+=d.content;}catch(e){}}
    }
    window._gestorIAmsgList[window._gestorIAmsgList.length-1]={role:'assistant',content:resp||'(sin respuesta)',loading:false};
    _iaSpeakText(resp||'');
  }catch(e){
    const _lastQG=((window._gestorIAmsgList.filter(m=>m.role==='user').pop()||{}).content||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    let _fbG='';
    if(/plataforma|institucion|crear|nueva/.test(_lastQG)) _fbG='🏫 **Crear institución**: Panel Gestor → sección "Plataformas" → botón **➕ Nueva**. Ingrese nombre, municipio, tipo (pública/privada) y datos del admin rector.';
    else if(/modulo|configurar|activar/.test(_lastQG)) _fbG='🧩 **Módulos**: Panel Gestor → "Plataformas" → botón **🧩 Módulos** en la plataforma. Active o desactive cada módulo con el toggle. Los cambios aplican de inmediato.';
    else if(/usuario|contrasena|clave|acceso/.test(_lastQG)) _fbG='🔑 **Usuarios**: Cada institución gestiona sus usuarios desde "Configuración" → "Usuarios". El rector puede resetear contraseñas. Los docentes acceden con usuario y clave asignados.';
    else if(/sk|clave.*plataforma|llave/.test(_lastQG)) _fbG='🔑 **Clave de plataforma (sk)**: Es el identificador único de cada institución. Se genera automáticamente al crear la plataforma y puede verse en "Configuración" → pestaña "General".';
    else if(/hola|buenos|buenas|saludos|ayuda/.test(_lastQG)) _fbG='¡Hola! Soy **Adán**, el asistente del Gestor Académico YC. Puedo orientarle sobre administración de plataformas, módulos, usuarios, configuraciones y más. ¿En qué le ayudo?';
    else if(/1290|decreto|evaluacion|escala/.test(_lastQG)) _fbG='📋 El **Decreto 1290 de 2009** regula la evaluación en Colombia. Cada institución define su escala con mínimo 4 niveles (Superior, Alto, Básico, Bajo). El Gestor soporta escala numérica 1-5, escala descriptiva y emojis para grados iniciales.';
    else if(/quillbot|quilbot/.test(_lastQG)) _fbG='✍️ **QuillBot**: Haga clic en el botón **✍️ QuillBot** para abrir el parafrasador y corrector gramatical en línea.';
    else if(/backup|respaldo|exportar/.test(_lastQG)) _fbG='💾 **Respaldo**: Los datos se sincronizan automáticamente a la nube con cada cambio. También puede descargar el portal HTML desde el Gestor → "Descargar Portal" para tener una copia offline.';
    else if(/plan|area|planeacion|curricul/.test(_lastQG)) _fbG='📚 **Planes de Área**: Módulo "Documentos/Actas" → pestaña "Planes de Área". Suba PDFs, Word o Excel con su malla curricular y planeaciones. Quedan disponibles para toda la institución.';
    else _fbG='¡Hola! Soy **Adán**, asistente del Gestor Académico YC. Puedo orientarle sobre: gestión de plataformas, módulos, usuarios, configuración institucional, Decreto 1290, boletines, y cualquier función del sistema. ¿Cuál es su consulta?';
    window._gestorIAmsgList[window._gestorIAmsgList.length-1]={role:'assistant',content:_fbG,loading:false};
  }
  window._gestorIAstreaming=false;gestorIArenderMsgs();
}
function gestorIArenderMsgs(){
  const c=document.getElementById('gestorIAmsgs');if(!c) return;
  if(!window._gestorIAmsgList||!window._gestorIAmsgList.length){c.innerHTML='<div style="color:#888;font-style:italic;text-align:center;padding:16px 0">El asistente está listo.</div>';return;}
  c.innerHTML=window._gestorIAmsgList.map(function(m){
    const bg=m.role==='user'?'#e8f4fd':'#f0e6fa';const align=m.role==='user'?'right':'left';
    const prefix=m.role==='user'?'👤 Tú':'🤖 Agente';
    const content=(m.loading?'⏳ Pensando...':(m.content||'')).replace(/\*\*(.*?)\*\*/g,'<b>$1</b>').replace(/\*(.*?)\*/g,'<i>$1</i>').replace(/\n/g,'<br>');
    return '<div style="background:'+bg+';padding:9px 12px;border-radius:8px;margin-bottom:7px"><b style="font-size:0.74rem;color:#7f8c8d">'+prefix+'</b><div>'+content+'</div></div>';
  }).join('');c.scrollTop=c.scrollHeight;
}

function htmlGestorPlataformas(){
  if(!gestorDB.platforms.length) return `<div class="card"><p class="empty" style="padding:40px">No hay plataformas. Haga clic en <b>➕ Nueva</b> para crear la primera.</p></div>`;
  const cards=gestorDB.platforms.map(plat=>{
    const platDB=loadPlatformDB(plat.sk);
    const nEsts=platDB.ests?platDB.ests.length:0;
    const nDocs=platDB.users?platDB.users.filter(u=>u.r==='docente').length:0;
    const nMods=plat.modulosActivos?plat.modulosActivos.length:0;
    const adminU=platDB.users&&platDB.users.find(x=>x.r==='admin');
    return `<div class="plat-card">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:6px">
        <div style="flex:1;padding-right:10px">
          <div class="plat-nombre">🏫 ${plat.nombre}</div>
          <div class="plat-info">📍 ${plat.municipio||'—'}${plat.depto?' - '+plat.depto:''} &nbsp;|&nbsp; 📅 ${plat.fechaCreacion||'—'}</div>
          <div style="margin-top:4px"><span style="font-size:0.68rem;background:${(plat.tipo||'publica')==='privada'?'#8e44ad':'#1a5276'};color:#fff;border-radius:8px;padding:2px 9px;font-weight:bold">${(plat.tipo||'publica')==='privada'?'🏢 PRIVADA':'🏛️ PÚBLICA'}</span></div>
        </div>
        <span class="${plat.activa?'plat-badge-on':'plat-badge-off'}">${plat.activa?'ACTIVA':'INACTIVA'}</span>
      </div>
      <div style="display:flex;gap:14px;font-size:0.8rem;color:#555;margin-bottom:12px;flex-wrap:wrap;background:#f8f9fa;padding:7px 10px;border-radius:7px">
        <span>👥 <b>${nEsts}</b> estudiantes</span>
        <span>👨‍🏫 <b>${nDocs}</b> docentes</span>
        <span>🧩 <b>${nMods}/${TODOS_MODULOS.length}</b> módulos</span>
        ${adminU?`<span>🔑 Admin: <b>${adminU.u}</b></span>`:''}
        <span title="Años disponibles: ${(plat.aniosDisponibles||[]).join(', ')}">📅 <b>${plat.anioActivo||platDB.anio||'—'}</b>${(plat.aniosDisponibles||[]).length>1?` <small style="color:#888">(${(plat.aniosDisponibles||[]).length} años)</small>`:''}</span>
      </div>
      <div class="flex-gap">
        <button class="btn btn-navy" style="font-size:0.82rem;padding:7px 13px" onclick="entrarPlataforma('${plat.id}')">🚀 Entrar</button>
        <button class="btn btn-blue" style="font-size:0.82rem;padding:7px 13px" onclick="abrirModulosModal('${plat.id}')">🧩 Módulos</button>
        <button class="btn btn-orange" style="font-size:0.82rem;padding:7px 13px" onclick="abrirEditarPlat('${plat.id}')">✎ Editar</button>
        <button class="btn" style="background:${plat.activa?'#7f8c8d':'#27ae60'};font-size:0.82rem;padding:7px 13px" onclick="toggleActivarPlat('${plat.id}')">${plat.activa?'⏸ Suspender':'▶ Activar'}</button>
        <button class="btn" style="background:${plat.bloqueada?'#e74c3c':'#8e44ad'};font-size:0.82rem;padding:7px 13px" onclick="toggleBloquearPlat('${plat.id}')">${plat.bloqueada?'🔓 Desbloquear':'🔒 Bloquear acceso'}</button>
        <button class="btn btn-red" style="font-size:0.82rem;padding:7px 13px" onclick="eliminarPlataforma('${plat.id}')">🗑</button>
          <button class="btn btn-blue" style="font-size:0.82rem;padding:7px 13px" onclick="descargarHTMLInstitucion('${plat.id}')" title="Descargar portal HTML de esta institución">⬇ HTML</button>
      </div>
    </div>`;
  }).join('');
  return `<h3 style="color:#003366;margin-bottom:16px">🏫 Plataformas Registradas (${gestorDB.platforms.length})</h3>
  <div style="margin-bottom:14px;text-align:right"><button class="btn btn-blue" style="font-size:0.85rem;padding:8px 18px" onclick="descargarGestorCompleto()" title="Descarga el sistema completo con todos los datos">⬇ Descargar Sistema Completo GESTOR ACADÉMICO YC</button></div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:16px">${cards}</div>`;
}
function htmlGestorNueva(){
  const platEdit=_gestorEditPlatId?gestorDB.platforms.find(x=>x.id===_gestorEditPlatId):null;
  const platDB=platEdit?loadPlatformDB(platEdit.sk):{};
  const au=platEdit&&platDB.users&&platDB.users.find(x=>x.r==='admin');
  const titulo=platEdit?`✎ Editar: ${platEdit.nombre}`:'➕ Crear Nueva Plataforma';
  const accion=platEdit?'guardarEditarPlat()':'crearNuevaPlataforma()';
  return `<h3 style="color:#003366;margin-bottom:16px">${titulo}</h3>
  <div class="card">
    <div class="grid2" style="margin-bottom:12px">
      <div><label class="lbl">Nombre de la Institución *</label><input id="nPNombre" value="${platEdit?platEdit.nombre:''}" placeholder="I.E. Técnica de..."></div>
      <div><label class="lbl">Municipio / Corregimiento</label><input id="nPMunicipio" value="${platEdit?platEdit.municipio||'':platDB.municipio||''}" placeholder="Montería"></div>
      <div><label class="lbl">Departamento</label><input id="nPDepto" value="${platEdit?platEdit.depto||'':platDB.depto||''}" placeholder="Ej: Córdoba"></div>
      <div><label class="lbl">Tipo de Institución *</label>
        <select id="nPTipo" style="width:100%;padding:9px 12px;border:1px solid #ccc;border-radius:5px;font-size:0.88rem" onchange="(function(v){const blk=document.getElementById('nPPrivadaOps');if(blk)blk.style.display=v==='privada'?'block':'none';})(this.value)">
          <option value="publica"${(platEdit?platEdit.tipo||'publica':'publica')==='publica'?' selected':''}>🏛️ Pública (sin cobro de pensiones)</option>
          <option value="privada"${(platEdit?platEdit.tipo:null)==='privada'?' selected':''}>🏢 Privada (con pensiones y bloqueo de boletín)</option>
        </select>
      </div>
      <div id="nPPrivadaOps" style="display:${(platEdit?platEdit.tipo:null)==='privada'?'block':'none'}">
        <label class="lbl">💰 Valor mensualidad/pensión</label><input id="nPPension" value="${platDB.valorPension||''}" placeholder="Ej: 150000" type="number">
      </div>
      <div><label class="lbl">Rector(a)</label><input id="nPRectora" value="${platDB.rectora||''}" placeholder="Nombre completo del/la rector(a)"></div>
      <div><label class="lbl">Año Lectivo</label><input id="nPAnio" value="${platDB.anio||'2026'}" placeholder="2026"></div>
      <div><label class="lbl">DANE</label><input id="nPDane" value="${platDB.dane||''}" placeholder="Código DANE"></div>
      <div><label class="lbl">NIT</label><input id="nPNit" value="${platDB.nit||''}" placeholder="NIT institucional"></div>
      <div><label class="lbl">Teléfono institucional</label><input id="nPTel" value="${platDB.telInst||''}" placeholder="Teléfono"></div>
      <div><label class="lbl">Email institucional</label><input id="nPEmail" value="${platDB.emailInst||''}" placeholder="correo@sede.edu.co"></div>
      <div><label class="lbl">Usuario Admin (rector(a)/admin)</label><input id="nPAdminU" value="${au?au.u:'admin'}" placeholder="admin"></div>
      <div><label class="lbl">Contraseña Admin</label><input id="nPAdminP" value="${au?au.p:'1234'}" placeholder="1234"></div>
    </div>
    <div style="margin:14px 0">
        <label class="lbl">Escudo / Logo de la Institución</label>
        <div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-top:8px">
          <div id="nPEscudoPreview" style="width:70px;height:70px;border:2px dashed #aac;border-radius:10px;display:flex;align-items:center;justify-content:center;overflow:hidden;background:#f0f4ff">
            ${platEdit&&platEdit.escudo?'<img src="'+platEdit.escudo+'" style="max-width:100%;max-height:100%;object-fit:contain">':'<span style="font-size:0.7rem;color:#aaa;text-align:center">Sin escudo</span>'}
          </div>
          <div style="flex:1;min-width:200px">
            <input type="file" id="nPEscudoFile" accept="image/*" style="display:none" onchange="previewLogoGestor('nPEscudoFile','nPEscudoPreview','nPEscudoData')">
            <button class="btn btn-gray" style="font-size:0.82rem;padding:7px 14px" onclick="document.getElementById('nPEscudoFile').click()">📁 Seleccionar imagen</button>
            <div style="font-size:0.72rem;color:#888;margin-top:4px">PNG, JPG o SVG. Se guardará como escudo de la institución.</div>
          </div>
          <input type="hidden" id="nPEscudoData" value="${platEdit&&platEdit.escudo?platEdit.escudo:''}">
        </div>
      </div>
      <div style="margin:16px 0">
      <label class="lbl">Módulos activos para esta plataforma</label>
      <div style="display:flex;gap:8px;margin:8px 0;flex-wrap:wrap">
        <button type="button" class="btn btn-blue" style="font-size:0.76rem;padding:4px 12px" onclick="TODOS_MODULOS.forEach(m=>{const el=document.getElementById('mChk_'+m.id);if(el)el.checked=true;})">✓ Activar todos</button>
        <button type="button" class="btn btn-gray" style="font-size:0.76rem;padding:4px 12px" onclick="TODOS_MODULOS.filter(m=>!m.core).forEach(m=>{const el=document.getElementById('mChk_'+m.id);if(el)el.checked=false;})">○ Solo CORE</button>
      </div>
      ${[
        {titulo:'🏛️ Administración Core',ids:['tablero','adm-base','adm-carga','adm-est','ver-credenciales','cronograma-notas','estado-notas']},
        {titulo:'📚 Académicos',ids:['planilla','descriptores','horarios','asistencia','observador','adm-rep','actas']},
        {titulo:'📝 Adicionales',ids:['actividades-docente','quizzes-docente','menciones-honor','ausentismo','aviso-docente','obs-aula']},
        {titulo:'🏫 Gestión',ids:['alerta-temprana','comunicado-general','contacto','centros-interes','elecciones-admin','pre-matricula','recepcion-permisos','control-permisos','seguimiento-observador','historico-anios']},
        {titulo:'⭐ Evaluación',ids:['eval-docente-admin','seguimiento-eval-docente']},
        {titulo:'🔧 Herramientas',ids:['asistente-ia','nav-voz','manual-usuario']},
      ].map(g=>{
        const modsDel=TODOS_MODULOS.filter(m=>g.ids.includes(m.id));
        if(!modsDel.length) return '';
        return `<div style="margin-bottom:10px"><div style="font-size:0.74rem;font-weight:700;color:#003366;background:#e8f0fe;border-radius:4px;padding:4px 8px;margin-bottom:5px">${g.titulo}</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:5px">`
          +modsDel.map(m=>{const activo=!platEdit||(platEdit.modulosActivos||[]).includes(m.id);return `<label class="modulo-toggle" style="margin:0;padding:4px 7px"><label class="toggle-sw"><input type="checkbox" id="mChk_${m.id}" ${activo?'checked':''}><span class="slider"></span></label><span style="font-size:0.8rem">${m.label}${m.core?'<span style="background:#e74c3c;color:#fff;font-size:0.6rem;border-radius:3px;padding:1px 4px;margin-left:4px">CORE</span>':''}</span></label>`;}).join('')
          +'</div></div>';
      }).join('')}
    </div>
    <div class="flex-gap">
      <button class="btn btn-green" onclick="${accion}">💾 ${platEdit?'Guardar Cambios':'Crear Plataforma'}</button>
      <button class="btn btn-gray" onclick="_gestorEditPlatId=null;_gestorPag='plataformas';renderGestorAdmin()">✕ Cancelar</button>
    </div>
  </div>`;
}
