// S04 · AUTENTICACIÓN — LOGIN, ROLES Y SESIÓN
// Comprende las funciones de acceso institucional, login del
// Gestor YC, login biométrico y recuperación de contraseña.
// IMPORTANTE: las validaciones de sesion.r (admin/rector/
// docente/padre/estudiante) NO deben modificarse — son el
// núcleo del control de acceso multi-tenant.
// ============================================================

// ── Nota: Las funciones de autenticación están definidas en
// orden de flujo en S03 (entrarPlataforma, doLoginGestor,
// doLoginInstitucional, renderBienvenidaInstitucion) y en S10
// (loginBiometrico, mostrarRecuperarPassword, etc.).
// Esta sección actúa como marcador de referencia.

// ============================================================
// S06 · CÁLCULO DE NOTAS Y CALIFICACIONES
// Fórmulas de promedio por componentes (SER/SABER/HACER),
// escala cualitativa, definitivAs y estado de promoción.
// Estas funciones son puras — no tienen efectos secundarios.
// ============================================================
function _getNumPer(){ return (db&&db.config&&db.config.numPeriodos)||4; }
function calcNota(nts,cId,per){
  const n=(nts[cId]||{})[per]||{s:0,sb:0,h:0,rec:0,niv:0};
  const cfg=db.config||{};
  const base=_baseNota(n,cfg);
  return (base<3.0&&(n.rec||0)>0)?n.rec:base;
}
function _baseNota(n,cfg){
  const colsBase=(cfg&&cfg.columnasBase);
  if(colsBase&&colsBase.length){
    let sum=0,totalPct=0;
    colsBase.forEach(c=>{const p=parseFloat(c.pct)||0;sum+=(n[c.key]||0)*p;totalPct+=p;});
    return parseFloat((totalPct>0?sum/totalPct:0).toFixed(2));
  }
  // Compat backward (sin columnasBase)
  const cols=(cfg&&cfg.columnasExtra)||[];
  const totalExtraPct=cols.reduce((s,c)=>(s+(parseFloat(c.pct)||0)/100),0);
  const scale=Math.max(0,1-totalExtraPct);
  const pS=(cfg&&cfg.pctSer!=null?cfg.pctSer:0.25)*scale;
  const pSb=(cfg&&cfg.pctSaber!=null?cfg.pctSaber:0.35)*scale;
  const pH=(cfg&&cfg.pctHacer!=null?cfg.pctHacer:0.40)*scale;
  let extraSum=0;
  cols.forEach((col,i)=>{extraSum+=(n['ex'+i]||0)*(parseFloat(col.pct)||0)/100;});
  return parseFloat((n.s*pS+n.sb*pSb+n.h*pH+extraSum).toFixed(2));
}
function calcNotaDef(nts,cId,per){
  if(!nts) return 0;
  const n=(nts[cId]||{})[per]||{s:0,sb:0,h:0,rec:0,niv:0};
  const cfg=db.config||{};
  const base=_baseNota(n,cfg);
  const rec=n.rec||0;
  const def=(base<3.0&&rec>0)?rec:base;
  if(per==_getNumPer()&&(n.niv||0)>0) return n.niv;
  return def;
}
function calcPromedioMat(estId,cId){
  const e=db.ests.find(x=>x.id===estId);if(!e) return 0;
  const _np=_getNumPer();
  let s=0,cnt=0;for(let p=1;p<=_np;p++){const n=calcNotaDef(e.nts,cId,p);if(n>0){s+=n;cnt++;}}
  return cnt?parseFloat((s/cnt).toFixed(2)):0;
}
function _areasPorGrado(grado){
  const areas={};
  db.carga.filter(c=>c.g===grado).forEach(m=>{const a=m.a||m.m;if(!areas[a])areas[a]=[];areas[a].push(m);});
  return areas;
}
function _calcAreaNotaAnual(estId,area,asigs){
  const sp=(db.config?.pesosAsig||{})[area]||{};
  // Solo incluir asignaturas que tengan al menos una nota en algún período
  const asigConNotas=asigs.filter(m=>calcPromedioMat(estId,m.id)>0);
  if(!asigConNotas.length) return 0;
  let tw=0,sw=0;
  asigConNotas.forEach(m=>{const w=sp[m.m]||0;tw+=w;sw+=calcPromedioMat(estId,m.id)*w;});
  if(tw>0) return sw/tw;
  let s=0;asigConNotas.forEach(m=>s+=calcPromedioMat(estId,m.id));return s/asigConNotas.length;
}
function _calcAreaNotaPer(estId,area,asigs,per){
  const sp=(db.config?.pesosAsig||{})[area]||{};
  const e=db.ests.find(x=>x.id===estId);
  let tw=0,sw=0;
  asigs.forEach(m=>{const w=sp[m.m]||0;tw+=w;sw+=calcNotaDef(e?.nts,m.id,per)*w;});
  if(tw>0) return sw/tw;
  let s=0;asigs.forEach(m=>s+=calcNotaDef(e?.nts,m.id,per));return s/asigs.length;
}
function calcPromedioEst(estId,grado){
  const mats=db.carga.filter(c=>c.g===grado);if(!mats.length) return 0;
  const e=db.ests.find(x=>x.id===estId);if(!e) return 0;
  const pesosA=db.config?.pesosArea||{};
  const areas=_areasPorGrado(grado);const aKeys=Object.keys(areas);
  let totalW=0,sumaW=0;
  aKeys.forEach(area=>{
    // Solo incluir áreas que tengan al menos una nota en cualquier período
    const tieneNota=areas[area].some(m=>calcPromedioMat(estId,m.id)>0);
    if(!tieneNota) return;
    const nota=_calcAreaNotaAnual(estId,area,areas[area]);
    const w=pesosA[area]||0;totalW+=w;sumaW+=nota*w;
  });
  if(totalW===0){
    let s=0,cnt=0;mats.forEach(c=>{const pm=calcPromedioMat(estId,c.id);if(pm>0){s+=pm;cnt++;}});
    return cnt?parseFloat((s/cnt).toFixed(2)):0;
  }
  return parseFloat((sumaW/totalW).toFixed(2));
}
function calcPromedioEstPer(estId,grado,per){
  const mats=db.carga.filter(c=>c.g===grado);if(!mats.length) return 0;
  const e=db.ests.find(x=>x.id===estId);if(!e) return 0;
  const pesosA=db.config?.pesosArea||{};
  const areas=_areasPorGrado(grado);const aKeys=Object.keys(areas);
  let totalW=0,sumaW=0;
  aKeys.forEach(area=>{
    // Solo incluir áreas que tengan al menos una nota en este período
    const tieneNota=areas[area].some(m=>calcNotaDef(e.nts,m.id,per)>0);
    if(!tieneNota) return;
    const nota=_calcAreaNotaPer(estId,area,areas[area],per);
    const w=pesosA[area]||0;totalW+=w;sumaW+=nota*w;
  });
  if(totalW===0){
    let s=0,cnt=0;
    mats.forEach(c=>{const nd=calcNotaDef(e.nts,c.id,per);if(nd>0){s+=nd;cnt++;}});
    return cnt?parseFloat((s/cnt).toFixed(2)):0;
  }
  return parseFloat((sumaW/totalW).toFixed(2));
}
function getAreasPerdidas(estId,grado){
  const e=db.ests.find(x=>x.id===estId);if(!e) return [];
  const areas=_areasPorGrado(grado);
  return Object.keys(areas).filter(area=>{
    return _calcAreaNotaAnual(estId,area,areas[area])<3.0;
  });
}
function getAreasPerdidasPeriodo(estId,grado,per){
  const e=db.ests.find(x=>x.id===estId);if(!e) return [];
  const areas=_areasPorGrado(grado);
  return Object.keys(areas).filter(area=>{
    // Solo contar área como perdida si tiene al menos una nota en el período
    const tieneNota=areas[area].some(m=>calcNotaDef(e.nts,m.id,per)>0);
    if(!tieneNota) return false;
    return _calcAreaNotaPer(estId,area,areas[area],per)<3.0;
  });
}
function calcAreasPerd(estId,grado){return getAreasPerdidas(estId,grado).length;}
function calcAreasPerdPeriodo(estId,grado,per){return getAreasPerdidasPeriodo(estId,grado,Number(per)).length;}
function puestoEst(estId,grado){
  const list=db.ests.filter(e=>e.g===grado).map(e=>({id:e.id,p:calcPromedioEst(e.id,grado)})).sort((a,b)=>b.p-a.p);
  return list.findIndex(e=>e.id===estId)+1;
}
function esc(v){const c=db.config||{};const es=c.escalaS||4.7,ea=c.escalaA||4.0,eb=c.escalaB||3.0;return v>=es?'SUPERIOR':v>=ea?'ALTO':v>=eb?'BÁSICO':'BAJO';}
function escEmoji(v){const n=esc(v);return n==='SUPERIOR'?'😄':n==='ALTO'?'😊':n==='BÁSICO'?'😐':'😢';}
function escBadge(v,grande){const n=esc(v);const e=escEmoji(v);const c=n==='SUPERIOR'?'#1a7531':n==='ALTO'?'#1a5276':n==='BÁSICO'?'#e67e22':'#c0392b';if(grande) return `<span style="display:inline-flex;flex-direction:column;align-items:center;gap:1px"><span style="font-size:2rem;line-height:1">${e}</span><span style="background:${c};color:#fff;border-radius:8px;padding:1px 8px;font-size:0.72rem;font-weight:bold">${n}</span></span>`;return `<span style="background:${c};color:#fff;border-radius:10px;padding:1px 7px;font-size:0.85rem;font-weight:bold;white-space:nowrap">${e} ${n}</span>`;}
function escNorm(v){const c=db.config||{};const es=c.escalaS||4.7,ea=c.escalaA||4.0,eb=c.escalaB||3.0;return v>=es?'superior':v>=ea?'alto':v>=eb?'basico':'bajo';}
function colorNota(v){return v<3?'#c0392b':v>=4.7?'#1a7531':v>=4.0?'#1a5276':'#333';}

function esDirectorDeGrupo(u){
  const user=db.users.find(x=>x.u===u);if(!user) return false;
  return db.grados.some(g=>g.d&&user.n&&g.d.toUpperCase()===user.n.toUpperCase());
}
function gradosDelDocente(u){
  return [...new Set(db.carga.filter(c=>c.d===u).map(c=>c.g))];
}

// ============================================================
// S07 · SINCRONIZACIÓN, SSE Y UTILIDADES GLOBALES
// _pullDB, _pushDB, SSE multi-dispositivo, toasts y helpers
// de uso transversal en toda la aplicación.
// ============================================================
function iaRemoveWidget(){const w=document.getElementById('iaWidget');if(w)w.remove();}
function render(){
  if(window._adminPortalMode){iaRemoveWidget();renderAdminPortal();return;}
  if(gestorSesion){
    if(gestorEnPlataforma){renderApp();return;}
    iaRemoveWidget();renderGestorAdmin();return;
  }
  if(pag==='pre-matricula-publica'){iaRemoveWidget();renderPreMatriculaPublica();return;}
  if(sesion){renderApp();return;}
  iaRemoveWidget();renderGestorLanding();
}
// Sincronizar con servidor al cargar la página
(async()=>{
  // Restaurar sesión persistida antes de renderizar
  const _hadSess=_restoreSessState();
  try{
    const ok=await _pullDB();
    // Si había sesión guardada, re-cargar la DB de la institución correcta
    if(_hadSess&&window._currentPlatSK){
      try{
        const _r=await fetch(API_BASE+'/api/inetis/db?sk='+encodeURIComponent(window._currentPlatSK));
        if(_r.ok){const _j=await _r.json();if(_j&&_j.data){db=_migrateDB(_j.data);try{localStorage.setItem(window._currentPlatSK,JSON.stringify(db));}catch(e){}}}
      }catch(e){}
    }
    if(ok||_hadSess){
      if(sesion){renderApp();}
      else if(window._adminPortalMode)renderAdminPortal();
      else if(gestorSesion){renderGestorAdmin();}
      else{iaRemoveWidget();renderGestorLanding();}
    } else if(window._adminPortalMode)renderAdminPortal();
    else{iaRemoveWidget();renderGestorLanding();}
  }catch(e){
    if(_hadSess&&sesion){renderApp();}
    else if(window._adminPortalMode)renderAdminPortal();
    else{iaRemoveWidget();renderGestorLanding();}
  }
})().catch(function(){});

// ============================================================
// SINCRONIZACIÓN AUTOMÁTICA MULTI-DISPOSITIVO
// ============================================================
async function _pullGestorDB(){
  try{
    const _r=await fetch('/api/inetis/gestordb');
    if(!_r.ok) return false;
    const _j=await _r.json();
    if(!_j||!_j.data) return false;
    const _prev=JSON.stringify(gestorDB);
    // Usar _migrateGestorDB para garantizar que todos los módulos nuevos
    // se agreguen automáticamente a plataformas existentes sin conflictos
    gestorDB=_migrateGestorDB(_j.data);
    try{localStorage.setItem(GESTOR_SK,JSON.stringify(gestorDB));}catch(e){}
    return JSON.stringify(gestorDB)!==_prev;
  }catch(e){}return false;
}

async function _syncAll(force){
  if(_syncInProgress) return;
  _syncInProgress=true;
  _updateSyncChip('syncing');
  try{
    // Sincronizar gestorDB
    const _gChanged=await _pullGestorDB();
    // Sincronizar db de la institución activa (solo si hay una activa)
    let _dChanged=false;
    const _sk=window._currentPlatSK||(sesion&&SK)||null;
    if(_sk){
      try{
        const _localTS=db._localTS||0;
        const _r2=await fetch(API_BASE+'/api/inetis/db?sk='+encodeURIComponent(_sk));
        if(_r2.ok){
          const _j2=await _r2.json();
          if(_j2&&_j2.data){
            const _serverData=_migrateDB(_j2.data);
            const _serverTS=_serverData._localTS||0;
            if(_serverTS>_localTS){
              const _prev2=JSON.stringify(db);
              db=_serverData;
              try{localStorage.setItem(_sk,JSON.stringify(db));}catch(e){}
              _dChanged=JSON.stringify(db)!==_prev2;
            } else if(_localTS>_serverTS){
              // Local is newer (e.g., after JSON import) — push to server
              try{await fetch(API_BASE+'/api/inetis/db',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sk:_sk,data:db})});}catch(e){}
            }
          }
        }
      }catch(e){}
    }
    _lastSyncTs=Date.now();
    _updateSyncChip('ok');
    // Re-renderizar si algo cambió
    if(_gChanged||_dChanged||force){
      if(_gChanged||_dChanged) _showSyncToast('🔄 Datos actualizados desde la nube');
      if(gestorSesion){
        if(gestorEnPlataforma){renderApp();_reaplicarPendientes();}else{renderGestorAdmin();}
      } else if(sesion){
        const _rol=sesion.r;
        if(_rol==='estudiante'||_rol==='padre'){
          // Para estudiantes y padres: solo re-renderizar cuando hay cambios reales,
          // y preservar la posición de scroll para no interrumpir la navegación.
          if(_dChanged||_gChanged){
            const _sy=window.scrollY;
            renderApp();
            _reaplicarPendientes();
            if(_sy>10) requestAnimationFrame(()=>window.scrollTo(0,_sy));
          }
        } else {
          renderApp();_reaplicarPendientes();
        }
      }
    }
  }catch(e){_updateSyncChip('error');}
  finally{_syncInProgress=false;}
}

// ---- Sync status tracking ----
let _lastSyncTs=0;
let _syncInProgress=false;
function _fmtSyncTime(ts){
  if(!ts) return 'nunca';
  const diff=Math.round((Date.now()-ts)/1000);
  if(diff<60) return 'hace '+diff+'s';
  if(diff<3600) return 'hace '+Math.round(diff/60)+'min';
  return 'hace '+Math.round(diff/3600)+'h';
}
function _updateSyncChip(state){
  const chip=document.getElementById('_syncChip');
  if(!chip) return;
  if(state==='syncing') chip.innerHTML='🔄 Sincronizando...';
  else if(state==='ok') chip.innerHTML='☁️ '+_fmtSyncTime(_lastSyncTs);
  else chip.innerHTML='⚠️ Sin conexión';
}
function _showToast(msg,tipo,ms){
  // Toast de notificación no bloqueante con colores por tipo
  const colors={success:'#27ae60',error:'#c0392b',warning:'#f39c12',info:'#1a3a5c'};
  const bg=colors[tipo]||colors.info;
  let t=document.getElementById('_appToast');
  if(!t){t=document.createElement('div');t.id='_appToast';t.style.cssText='position:fixed;bottom:72px;right:16px;color:#fff;padding:11px 18px;border-radius:10px;font-size:0.84rem;z-index:9999;box-shadow:0 4px 18px rgba(0,0,0,.4);transition:opacity .4s,transform .3s;pointer-events:none;max-width:320px;line-height:1.4';document.body.appendChild(t);}
  t.style.background=bg;t.style.opacity='1';t.style.transform='translateY(0)';t.textContent=msg;
  clearTimeout(t._timer);t._timer=setTimeout(function(){t.style.opacity='0';t.style.transform='translateY(8px)';},ms||2600);
}
function _showSyncToast(msg){
  let t=document.getElementById('_syncToast');
  if(!t){t=document.createElement('div');t.id='_syncToast';t.style.cssText='position:fixed;bottom:72px;right:16px;background:#1a3a5c;color:#fff;padding:10px 16px;border-radius:10px;font-size:0.82rem;z-index:9999;box-shadow:0 4px 18px rgba(0,0,0,.4);transition:opacity .4s;pointer-events:none';document.body.appendChild(t);}
  t.textContent=msg;t.style.opacity='1';
  clearTimeout(t._to);t._to=setTimeout(()=>{t.style.opacity='0';},4000);
}

// Polling cada 20 segundos (reducido de 45s para mayor frecuencia)
let _syncInterval=setInterval(function(){
  if(document.visibilityState!=='hidden') _syncAll(false);
},20000);

// Actualizar chip de tiempo cada 30s (sin llamar API)
setInterval(function(){_updateSyncChip('ok');},30000);

// Sincronización inmediata al volver al tab
document.addEventListener('visibilitychange',function(){
  if(document.visibilityState==='visible'){
    _updateSyncChip('ok');
    _syncAll(false);
  }
});

// ============================================================
// ── NOTIFICACIONES DEL NAVEGADOR (Push visual) ─────────────────────────────
// Muestra una notificación nativa del navegador si el usuario dio permiso.
// Solicita permiso la primera vez de forma no intrusiva.
function _solicitarYMostrarNotifNavegador(titulo, cuerpo){
  if(!('Notification' in window)) return;
  const _mostrar=function(){
    try{
      new Notification(titulo,{body:cuerpo,icon:'/favicon.svg',tag:'gestor-academico-notif'});
    }catch(ex){}
  };
  if(Notification.permission==='granted'){
    _mostrar();
  } else if(Notification.permission!=='denied'){
    Notification.requestPermission().then(function(perm){
      if(perm==='granted') _mostrar();
    }).catch(function(){});
  }
}

// SINCRONIZACIÓN EN TIEMPO REAL — Server-Sent Events (SSE)
// Se mantienen DOS conexiones independientes y persistentes:
//   • _ssePlatConn  → canal de la institución/plataforma activa
//   • _sseGestorConn → canal del gestor global (siempre activo)
// Ambas llaman a _syncAll(true) al recibir un cambio, garantizando
// que cualquier dispositivo conectado vea los datos en tiempo real.
// ============================================================
// Crea y gestiona UNA conexión SSE para el sk dado.
// connObj = objeto {conn, recon, sk} pasado por referencia (array de un elemento).
function _makeSseChannel(sk, connHolder, reconHolder, skHolder){
  if(!sk) return;
  // Si ya hay conexión activa para este mismo sk, no hacer nada
  if(connHolder[0]&&skHolder[0]===sk&&connHolder[0].readyState!==EventSource.CLOSED) return;
  // Cerrar conexión anterior si existe
  if(connHolder[0]){try{connHolder[0].close();}catch(e){}}
  skHolder[0]=sk;
  let backoff=4000; // milisegundos de espera inicial para reconexión
  function _doConnect(){
    try{
      const conn=new EventSource('/api/inetis/events?sk='+encodeURIComponent(sk));
      connHolder[0]=conn;
      conn.onmessage=function(ev){
        try{
          const msg=JSON.parse(ev.data);
          if(msg.type==='change') _syncAll(true);
        }catch(e){}
      };
      conn.onopen=function(){
        backoff=4000; // resetear backoff al conectar exitosamente
        if(reconHolder[0]){clearTimeout(reconHolder[0]);reconHolder[0]=null;}
      };
      conn.onerror=function(){
        // Reconexión con backoff exponencial (máx 60s)
        if(reconHolder[0]) clearTimeout(reconHolder[0]);
        reconHolder[0]=setTimeout(function(){
          reconHolder[0]=null;
          try{conn.close();}catch(e){}
          backoff=Math.min(backoff*2,60000);
          _doConnect();
        },backoff);
      };
    }catch(e){}
  }
  _doConnect();
}

// Wrapper de canal de plataforma
const _ssePlatConnH=[null], _ssePlatReconH=[null], _ssePlatSkH=[null];
function _connectSSEPlat(sk){
  _makeSseChannel(sk,_ssePlatConnH,_ssePlatReconH,_ssePlatSkH);
}
function _disconnectSSEPlat(){
  if(_ssePlatConnH[0]){try{_ssePlatConnH[0].close();}catch(e){}}
  _ssePlatConnH[0]=null;_ssePlatSkH[0]=null;
  if(_ssePlatReconH[0]){clearTimeout(_ssePlatReconH[0]);_ssePlatReconH[0]=null;}
}

// Wrapper de canal del gestor (siempre activo mientras la app esté abierta)
const _sseGestorConnH=[null], _sseGestorReconH=[null], _sseGestorSkH=[null];
function _connectSSEGestor(){
  _makeSseChannel(GESTOR_SK,_sseGestorConnH,_sseGestorReconH,_sseGestorSkH);
}

// Compatibilidad con llamadas existentes al código antiguo
function _connectSSE(sk){ _connectSSEPlat(sk); }
function _disconnectSSE(){
  _disconnectSSEPlat();
  // El canal del gestor NO se desconecta al salir de una plataforma
}

// Conectar SSE automáticamente al entrar a una institución o al login
function _sseInit(){
  const sk=window._currentPlatSK||SK;
  if(sk) _connectSSEPlat(sk);       // canal de la institución
  _connectSSEGestor();               // canal del gestor (siempre activo)
}

// Iniciar canal del gestor inmediatamente al cargar la app
_connectSSEGestor();

