function cargarFotoDoc(inp){fileToB64(inp.files[0],b64=>{cargaFotoTemp=b64;document.getElementById('fotoPreviewArea').innerHTML=`<img src="${b64}" class="photo-preview">`;});}
function guardarDocente(){
  const n=document.getElementById('dNom').value.trim();const u=document.getElementById('dUsr').value.trim();const p=document.getElementById('dPas').value.trim();
  if(!n||!u||!p){alert('Complete nombre, usuario y contraseña');return;}
  const decreto=document.getElementById('dDecre')?.value||'';
  const modalidadDecre=decreto==='1278'?(document.getElementById('dModDecre')?.value||''):'';
  const nivelFormacion=document.getElementById('dNivForm')?.value.trim()||'';
  const tipoPregrado=document.getElementById('dTipoPre')?.value||'';
  const nivelPosgrado=document.getElementById('dNivPos')?.value||'';
  const tituloPosgrado=nivelPosgrado?(document.getElementById('dTitPos')?.value.trim()||''):'';
  const gradoEscalafon=document.getElementById('dEscala')?.value||'';
  updDB(db=>{
    const nu={u,p,r:'docente',n:n.toUpperCase(),cedula:document.getElementById('dCed').value.trim(),
      telefono:document.getElementById('dTel').value.trim(),correo:document.getElementById('dCorreo').value.trim(),
      areaBase:document.getElementById('dArea').value.trim(),cargo:document.getElementById('dCargo').value,
      decreto,modalidadDecre,tipoPregrado,nivelFormacion,nivelPosgrado,tituloPosgrado,gradoEscalafon,foto:cargaFotoTemp};
    const idx=db.users.findIndex(x=>x.u===u);if(idx!==-1) db.users[idx]=nu; else db.users.push(nu);
    return db;
  });
  cargaFotoTemp='';renderApp();
}
function editarDocente(u){
  const user=db.users.find(x=>x.u===u);if(!user) return;
  const ov=document.createElement('div');
  ov.id='_editDocOv';
  ov.style.cssText='position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.6);z-index:10000;display:flex;align-items:center;justify-content:center;padding:16px';
  ov.innerHTML=`<div style="background:#fff;border-radius:14px;padding:24px;max-width:520px;width:100%;box-shadow:0 8px 40px rgba(0,0,0,.35);max-height:90vh;overflow-y:auto">
    <h3 style="color:#003366;margin-bottom:16px">✎ Editar Docente</h3>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px">
      <div style="grid-column:1/-1"><label class="lbl">Nombre completo *</label><input id="_edNom" value="${user.n||''}" placeholder="Nombre completo" style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px"></div>
      <div><label class="lbl">Usuario *</label><input id="_edUsr" value="${user.u||''}" placeholder="Usuario" style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px"></div>
      <div><label class="lbl">Contraseña</label><input id="_edPas" value="${user.p||''}" placeholder="Contraseña" style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px"></div>
      <div><label class="lbl">Cédula</label><input id="_edCed" value="${user.cedula||''}" placeholder="Número de cédula" style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px"></div>
      <div><label class="lbl">Teléfono</label><input id="_edTel" value="${user.telefono||''}" placeholder="Teléfono" style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px"></div>
      <div><label class="lbl">Correo electrónico</label><input id="_edCorreo" type="email" value="${user.correo||user.email||''}" placeholder="correo@..." style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px"></div>
      <div><label class="lbl">Área base</label><input id="_edArea" value="${user.areaBase||''}" placeholder="Área principal" style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px"></div>
      <div><label class="lbl">Cargo</label><select id="_edCargo" style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px">
        <option value="DOCENTE"${(user.cargo||'DOCENTE')==='DOCENTE'?' selected':''}>Docente</option>
        <option value="RECTOR(A)"${user.cargo==='RECTOR(A)'?' selected':''}>Rector(a)</option>
        <option value="SECRETARIO(A)"${user.cargo==='SECRETARIO(A)'?' selected':''}>Secretario(a)</option>
      </select></div>
      <div><label class="lbl">📜 Decreto que lo rige</label><select id="_edDecre" style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px" onchange="_onDecretoChange(this.value,'_edModDecreCon','_edEscalaCon','_edEscala','${user.gradoEscalafon||''}')">
        <option value="">Seleccione...</option>
        <option value="1278"${user.decreto==='1278'?' selected':''}>Decreto 1278</option>
        <option value="2277"${user.decreto==='2277'?' selected':''}>Decreto 2277</option>
      </select></div>
      <div id="_edModDecreCon" style="${user.decreto==='1278'?'':'display:none'}"><label class="lbl">Modalidad Decreto 1278</label><select id="_edModDecre" style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px">
        <option value="">Seleccione modalidad...</option>
        <option value="Propiedad"${user.modalidadDecre==='Propiedad'?' selected':''}>En Propiedad</option>
        <option value="Periodo de Prueba"${user.modalidadDecre==='Periodo de Prueba'?' selected':''}>Periodo de Prueba</option>
        <option value="Provisional - Vacancia Definitiva"${user.modalidadDecre==='Provisional - Vacancia Definitiva'?' selected':''}>Provisional — Vacancia Definitiva</option>
        <option value="Provisional - Vacancia Temporal"${user.modalidadDecre==='Provisional - Vacancia Temporal'?' selected':''}>Provisional — Vacancia Temporal</option>
      </select></div>
      <div><label class="lbl">🎓 Tipo de Pregrado</label><select id="_edTipoPre" style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px">
        <option value="">Seleccione...</option>
        <option value="Licenciado"${user.tipoPregrado==='Licenciado'?' selected':''}>Licenciado(a)</option>
        <option value="Profesional No Licenciado"${user.tipoPregrado==='Profesional No Licenciado'?' selected':''}>Profesional No Licenciado(a)</option>
      </select></div>
      <div><label class="lbl">📄 Título de Pregrado</label><input id="_edNivForm" value="${user.nivelFormacion||''}" placeholder="Ej: Matemáticas, Ciencias Sociales..." style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px"></div>
      <div><label class="lbl">🏅 Nivel de Posgrado</label><select id="_edNivPos" style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px" onchange="document.getElementById('_edTitPosCon').style.display=this.value?'block':'none'">
        <option value="">Ninguno</option>
        <option value="Especialización"${user.nivelPosgrado==='Especialización'?' selected':''}>Especialización</option>
        <option value="Maestría"${user.nivelPosgrado==='Maestría'?' selected':''}>Maestría</option>
        <option value="Doctorado"${user.nivelPosgrado==='Doctorado'?' selected':''}>Doctorado</option>
      </select></div>
      <div id="_edTitPosCon" style="${user.nivelPosgrado?'':'display:none'}"><label class="lbl">📋 Título de Posgrado</label><input id="_edTitPos" value="${user.tituloPosgrado||''}" placeholder="Ej: Gestión Educativa, TIC en Educación..." style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px"></div>
      <div id="_edEscalaCon" style="${user.decreto?'':'display:none'}"><label class="lbl">🏛️ Grado Escalafón</label><select id="_edEscala" style="width:100%;padding:9px;border:1px solid #ccc;border-radius:5px">${_escalafonOpts(user.decreto,user.gradoEscalafon||'')}</select></div>
    </div>
    <div style="margin-bottom:14px">
      <label class="lbl">Foto (opcional)</label>
      <div style="display:flex;align-items:center;gap:10px;margin-top:6px">
        <div id="_edFotoPreview" style="width:60px;height:60px;border:2px dashed #aac;border-radius:8px;overflow:hidden;display:flex;align-items:center;justify-content:center;background:#f0f4ff;flex-shrink:0">
          ${user.foto?`<img src="${user.foto}" style="width:100%;height:100%;object-fit:cover">`:'<span style="font-size:1.5rem">📷</span>'}
        </div>
        <div>
          <input type="file" id="_edFotoFile" accept="image/*" style="display:none" onchange="(function(inp){fileToB64(inp.files[0],b64=>{window._editDocFoto=b64;document.getElementById('_edFotoPreview').innerHTML='<img src=\\''+b64+'\\' style=\\'width:100%;height:100%;object-fit:cover\\'>';});})(this)">
          <button onclick="document.getElementById('_edFotoFile').click()" style="background:#7f8c8d;color:#fff;border:none;border-radius:5px;padding:7px 12px;cursor:pointer;font-size:0.82rem">📷 Cambiar foto</button>
        </div>
      </div>
    </div>
    <div style="display:flex;gap:8px">
      <button onclick="(function(){
        const n=document.getElementById('_edNom').value.trim();
        const usr=document.getElementById('_edUsr').value.trim();
        if(!n||!usr){alert('Nombre y usuario son obligatorios');return;}
        updDB(function(d){
          const idx=d.users.findIndex(x=>x.u==='${u}');
          const _edDecreVal=document.getElementById('_edDecre')?.value||d.users[idx].decreto||'';
          const _edModDecreVal=_edDecreVal==='1278'?(document.getElementById('_edModDecre')?.value||d.users[idx].modalidadDecre||''):'';
          if(idx!==-1) d.users[idx]={...d.users[idx],
            n:n.toUpperCase(),
            u:usr,
            p:document.getElementById('_edPas').value.trim()||d.users[idx].p,
            cedula:document.getElementById('_edCed').value.trim(),
            telefono:document.getElementById('_edTel').value.trim(),
            correo:document.getElementById('_edCorreo').value.trim(),
            email:document.getElementById('_edCorreo').value.trim(),
            areaBase:document.getElementById('_edArea').value.trim(),
            cargo:document.getElementById('_edCargo').value,
            decreto:_edDecreVal,
            modalidadDecre:_edModDecreVal,
            tipoPregrado:document.getElementById('_edTipoPre')?.value||d.users[idx].tipoPregrado||'',
            nivelFormacion:document.getElementById('_edNivForm')?.value.trim()||d.users[idx].nivelFormacion||'',
            nivelPosgrado:document.getElementById('_edNivPos')?.value||d.users[idx].nivelPosgrado||'',
            tituloPosgrado:document.getElementById('_edNivPos')?.value?(document.getElementById('_edTitPos')?.value.trim()||d.users[idx].tituloPosgrado||''):'',
            gradoEscalafon:document.getElementById('_edEscala')?.value||d.users[idx].gradoEscalafon||'',
            foto:window._editDocFoto!==undefined?window._editDocFoto:d.users[idx].foto
          };
          return d;
        });
        window._editDocFoto=undefined;
        document.getElementById('_editDocOv').remove();
        renderApp();
      })()" style="flex:1;background:#27ae60;color:#fff;border:none;padding:11px;border-radius:7px;cursor:pointer;font-weight:bold">💾 Guardar Cambios</button>
      <button onclick="window._editDocFoto=undefined;document.getElementById('_editDocOv').remove()" style="flex:1;background:#eee;border:none;padding:11px;border-radius:7px;cursor:pointer">Cancelar</button>
    </div>
  </div>`;
  window._editDocFoto=undefined;
  document.body.appendChild(ov);
}
function eliminarDocente(u){if(!confirm('¿Eliminar?')) return;updDB(db=>{db.users=db.users.filter(x=>x.u!==u);return db;});renderApp();}
function guardarCarga(){
  const d=document.getElementById('cDoc')?.value;const g=document.getElementById('cGra')?.value;
  const m=document.getElementById('cMat')?.value.trim();const a=document.getElementById('cArea')?.value.trim();
  const ih=parseFloat(document.getElementById('cIH')?.value)||0;
  if(!d||!g||!m){alert('Complete campos requeridos');return;}
  const dn=db.users.find(x=>x.u===d)?.n||'';
  updDB(db=>{db.carga.push({id:Date.now(),d,dn,g,m,a:a||'',ih});return db;});renderApp();
}
function editarCarga(id){
  const c=db.carga.find(x=>x.id===id);if(!c) return;
  const docentes=db.users.filter(u=>u.r==='docente');
  const docsOpts=docentes.map(u=>`<option value="${u.u}"${u.u===c.d?' selected':''}>${u.n}</option>`).join('');
  const gradOpts=db.grados.map(g=>`<option value="${g.n}"${g.n===c.g?' selected':''}>${g.n}</option>`).join('');
  let ov=document.getElementById('_editCargaOv');
  if(!ov){ov=document.createElement('div');ov.id='_editCargaOv';document.body.appendChild(ov);}
  ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:99990;display:flex;align-items:center;justify-content:center';
  ov.innerHTML=`<div style="background:#fff;border-radius:14px;padding:28px 30px;width:100%;max-width:480px;box-shadow:0 12px 40px rgba(0,0,0,0.35);border-top:4px solid #e67e22">
    <h3 style="margin:0 0 18px;color:#003366;font-size:1.05rem">✎ Editar Carga Académica</h3>
    <div style="margin-bottom:10px"><label class="lbl">Docente</label><select id="_ecDoc" style="width:100%;padding:9px;border:1px solid #c8d4e8;border-radius:7px">${docsOpts}</select></div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
      <div><label class="lbl">Grado</label><select id="_ecGra" style="width:100%;padding:9px;border:1px solid #c8d4e8;border-radius:7px">${gradOpts}</select></div>
      <div><label class="lbl">I.H. Semanal</label><input id="_ecIH" type="number" min="1" max="10" value="${c.ih||1}" style="width:100%;padding:9px;border:1px solid #c8d4e8;border-radius:7px"></div>
      <div><label class="lbl">Asignatura</label><input id="_ecMat" value="${c.m||''}" style="width:100%;padding:9px;border:1px solid #c8d4e8;border-radius:7px"></div>
      <div><label class="lbl">Área</label><input id="_ecArea" value="${c.a||''}" style="width:100%;padding:9px;border:1px solid #c8d4e8;border-radius:7px"></div>
    </div>
    <div style="background:#fff3cd;border-left:3px solid #f39c12;border-radius:4px;padding:8px 10px;font-size:0.79rem;margin-bottom:14px">⚠️ Las notas de los estudiantes <b>no se verán afectadas</b> al modificar estos datos.</div>
    <div style="display:flex;gap:10px">
      <button onclick="document.getElementById('_editCargaOv').style.display='none'" style="flex:1;background:#7f8c8d;color:#fff;border:none;border-radius:8px;padding:11px;font-size:0.9rem;font-weight:700;cursor:pointer">✕ Cancelar</button>
      <button onclick="_guardarEditCarga(${id})" style="flex:2;background:#e67e22;color:#fff;border:none;border-radius:8px;padding:11px;font-size:0.9rem;font-weight:700;cursor:pointer">💾 Guardar Cambios</button>
    </div>
  </div>`;
}
function _guardarEditCarga(id){
  const docU=document.getElementById('_ecDoc')?.value||'';
  const gra=document.getElementById('_ecGra')?.value||'';
  const mat=document.getElementById('_ecMat')?.value.trim()||'';
  const area=document.getElementById('_ecArea')?.value.trim()||'';
  const ih=parseFloat(document.getElementById('_ecIH')?.value)||0;
  if(!docU||!gra||!mat){alert('Docente, grado y asignatura son obligatorios');return;}
  const dn=db.users.find(x=>x.u===docU)?.n||docU;
  updDB(d=>{
    const idx=d.carga.findIndex(x=>x.id===id);
    if(idx!==-1) d.carga[idx]={...d.carga[idx],d:docU,dn,g:gra,m:mat,a:area,ih};
    return d;
  });
  document.getElementById('_editCargaOv').style.display='none';
  renderApp();
}
function eliminarCarga(id){if(!confirm('¿Eliminar?')) return;updDB(db=>{db.carga=db.carga.filter(x=>x.id!==id);return db;});renderApp();}

