// PLANILLA
// ============================================================
let planPer='1',planCId='';
function htmlPlanilla(){
  const _numPer=_getNumPer();
  const mats=db.carga.filter(x=>sesion.r==='admin'||x.d===sesion.u);
  if(!planCId&&mats.length) planCId=String(mats[0].id);
  const matsOpts=mats.map(c=>`<option value="${c.id}"${planCId==c.id?' selected':''}>${c.m} (${c.g})</option>`).join('');
  const carga=planCId?db.carga.find(x=>x.id===Number(planCId)):null;
  const ests=carga?db.ests.filter(x=>x.g===carga.g).sort((a,b)=>a.n.localeCompare(b.n)):[];
  let tabla='';
  if(!carga) tabla=`<p class="empty">Seleccione una asignatura.</p>`;
  else if(!ests.length) tabla=`<p class="empty">No hay estudiantes en este grado.</p>`;
  else {
    const eHead=planPer===String(_numPer)?`<th style="background:#6c3483;color:#fff;border:1px solid #ddd;padding:8px;font-size:0.78rem">NIVELACIÓN</th>`:'';
    const p3Head=(_numPer>1&&Number(planPer)===_numPer-1)?`<th style="background:#d35400;color:#fff;border:1px solid #ddd;padding:8px;font-size:0.75rem">NECESITA<br>PARA GANAR</th>`:'';
    const _cfgP=db.config||{};
    const _colsAllP=_cfgP.columnasBase&&_cfgP.columnasBase.length?_cfgP.columnasBase:(()=>{const ex=(_cfgP.columnasExtra||[]).map((c,i)=>({key:'ex'+i,...c}));return [{key:'s'},{key:'sb'},{key:'h'},...ex];})();
    const _perActTabla=(db.periodosActivos||Array(_numPer).fill(true))[Number(planPer)-1]!==false;
    const _isAdminTabla=sesion&&(sesion.r==='admin'||(gestorSesion&&gestorEnPlataforma));
    const rows=ests.map(e=>{
      const nts=e.nts||{};const np=Number(planPer);const nc=Number(planCId);
      const nd=(nts[nc]||{})[np]||{s:0,sb:0,h:0,rec:0,niv:0};
      const rec=nd.rec||0,niv=nd.niv||0;
      const base=_baseNota(nd,_cfgP);
      const def=(base<3&&rec>0)?rec:base;const defFinal=(np===_numPer&&niv>0)?niv:def;
      const areasP=calcAreasPerd(e.id,carga.g);const elegible=np===_numPer&&areasP>=1&&areasP<=2;
      const _esInicialG=esGradoInicial(carga.g);
      const mkBtn=(val,campo,bg)=>{
        const _q=_esInicialG?notaACualitativo(val):null;
        // Periodo cerrado y NO es admin: solo lectura, sin botón ni eventos táctiles
        if(!_perActTabla&&!_isAdminTabla){
          return `<td style="background:${bg||'#f7f7f7'};border:1px solid #ddd;padding:3px 4px;text-align:center"><span title="Periodo cerrado" style="background:${colorNota(val)};color:#fff;font-weight:bold;font-size:0.85rem;border-radius:4px;padding:6px 8px;display:inline-flex;align-items:center;justify-content:center;flex-direction:column;min-width:44px;min-height:36px;opacity:0.75;cursor:default;user-select:none">${val.toFixed(1)}${_esInicialG&&_q?`<span style="font-size:0.55rem;display:block;margin-top:1px;font-weight:bold;opacity:0.92">${_q.letra}</span>`:''}</span></td>`;
        }
        return `<td style="background:${bg||'#fff'};border:1px solid #ddd;padding:3px 4px;text-align:center"><button id="nota-btn-${e.id}-${campo}" class="nota-btn" style="background:${colorNota(val)};color:#fff;font-weight:bold;font-size:0.85rem;border:none;border-radius:4px;padding:6px 8px;cursor:pointer;min-width:44px;min-height:36px;touch-action:manipulation;-webkit-tap-highlight-color:transparent" onpointerdown="event.preventDefault();abrirPopupNota('${e.id}','${campo}',this)">${val.toFixed(1)}${_esInicialG&&_q?`<span style="font-size:0.55rem;display:block;margin-top:1px;font-weight:bold;opacity:0.92">${_q.letra}</span>`:''}</button></td>`;
      };
      const nivCell=np===_numPer?(elegible?mkBtn(niv,'niv','#f3e5f5'):`<td style="background:#f5f5f5;border:1px solid #ddd;padding:5px 6px"><span style="color:#aaa;font-size:0.74rem">N/A</span></td>`):'';
      let p3Cell='';
      if(_numPer>1&&np===_numPer-1){
        const defP1=calcNotaDef(e.nts,nc,1);
        const defP2=calcNotaDef(e.nts,nc,2);
        const neededLast=parseFloat((12.0-defP1-defP2-defFinal).toFixed(2));
        const p3cid='p3cell-'+e.id+'-'+nc;
        if(neededLast<=0){
          p3Cell='<td id="'+p3cid+'" style="background:#eafaf1;color:#27ae60;font-weight:bold;border:1px solid #ddd;padding:5px;text-align:center;font-size:0.75rem">✅ Ya aprobó<br><small style="font-weight:normal;color:#888">P1:'+defP1.toFixed(1)+' P2:'+defP2.toFixed(1)+'</small></td>';
        } else if(neededLast>5.0){
          p3Cell='<td id="'+p3cid+'" style="background:#fdecea;border:1px solid #ddd;padding:4px;text-align:center;font-size:0.75rem"><span style="color:#c0392b;font-weight:bold">❌ Imposible</span><br><small style="color:#888">Necesita '+neededLast.toFixed(1)+' en P'+_numPer+'</small></td>';
        } else {
          const colLast=neededLast>=4.5?'#c0392b':neededLast>=3.5?'#e67e22':'#d35400';
          p3Cell='<td id="'+p3cid+'" style="background:#fef9e7;border:1px solid #ddd;padding:4px;text-align:center;font-size:0.75rem"><span style="color:'+colLast+';font-weight:bold;font-size:0.95rem">'+neededLast.toFixed(1)+'</span><br><small style="color:#7f8c8d">necesita en P'+_numPer+'</small></td>';
        }
      }
      const baseCells=_colsAllP.map(col=>mkBtn(nd[col.key]||0,col.key)).join('');
      return `<tr>
        <td style="background:#f7f9fb;border:1px solid #ddd;padding:4px 5px;text-align:center;font-size:0.7rem;color:#5d6d7e;font-weight:bold;min-width:52px;vertical-align:middle;user-select:all" title="ID interno del estudiante">${e.id}</td>
        <td style="text-align:left;font-weight:500;border:1px solid #ddd;padding:4px 6px;font-size:0.82rem">
          <div style="display:flex;align-items:center;gap:7px">
            ${e.foto?`<img src="${e.foto}" onclick="abrirZoomFoto('${e.foto}','${e.n.replace(/'/g,"\\'")}',event)" style="width:46px;height:52px;border-radius:6px;object-fit:cover;border:2px solid #003366;flex-shrink:0;cursor:pointer;box-shadow:0 1px 5px rgba(0,0,0,.18);transition:transform .15s" onmouseover="this.style.transform='scale(1.12)'" onmouseout="this.style.transform='scale(1)'" title="Toca para ampliar foto">`:`<span style="width:46px;height:52px;border-radius:6px;background:#c5d8f0;display:inline-flex;align-items:center;justify-content:center;font-size:1.3rem;flex-shrink:0;border:2px solid #aaa">👤</span>`}
            <span>${e.n}</span>
          </div>
        </td>
        ${baseCells}
        <td style="color:${base<3?'#c0392b':'#333'};font-weight:bold;border:1px solid #ddd;padding:5px 6px;text-align:center" id="base-${e.id}">${base.toFixed(1)}</td>
        ${mkBtn(rec,'rec','#fffde7')}
        <td style="font-weight:bold;font-size:1rem;color:${colorNota(defFinal)};border:1px solid #ddd;padding:5px 6px;text-align:center" id="def-${e.id}">${defFinal.toFixed(1)}${_esInicialG?`<br><span style="font-size:2rem;line-height:1;display:block">${escEmoji(defFinal)}</span><span style="font-size:0.72rem;font-weight:bold;background:${notaACualitativo(defFinal).color};color:#fff;border-radius:4px;padding:1px 6px;display:inline-block;margin-top:1px">${notaACualitativo(defFinal).letra}</span>`:''}</td>
        ${nivCell}
        ${p3Cell}
      </tr>`;
    }).join('');
    const repBtn=(campo,col)=>`<br><button onclick="replicarColumna('${campo}')" title="Aplicar la misma nota a todos los estudiantes en esta columna" style="margin-top:4px;background:rgba(255,255,255,0.92);color:${col};border:1px solid rgba(255,255,255,0.6);border-radius:4px;font-size:0.65rem;font-weight:bold;padding:3px 6px;cursor:pointer;line-height:1">📋 Replicar a todos</button><br><button onclick="replicarColumnaSeleccionados('${campo}')" title="Aplicar la misma nota a estudiantes seleccionados" style="margin-top:3px;background:rgba(255,255,255,0.92);color:${col};border:1px solid rgba(255,255,255,0.6);border-radius:4px;font-size:0.65rem;font-weight:bold;padding:3px 6px;cursor:pointer;line-height:1">👥 Seleccionados</button>`;
    const eHeadFull=planPer===String(_numPer)?`<th style="background:#6c3483;color:#fff;border:1px solid #ddd;padding:8px;font-size:0.78rem">NIVELACIÓN${repBtn('niv','#6c3483')}</th>`:'';
    const _allColsHead=(()=>{
      if(_cfgP.columnasBase&&_cfgP.columnasBase.length) return _cfgP.columnasBase;
      const _cp2=_cfgP.columnasExtra||[];const _tex=_cp2.reduce((s,c)=>(s+(parseFloat(c.pct)||0)/100),0);const _sc2=Math.max(0,1-_tex);
      return [{key:'s',nom:_cfgP.nomSer||'SER',pct:Math.round((_cfgP.pctSer||0.25)*_sc2*100)},{key:'sb',nom:_cfgP.nomSaber||'SABER',pct:Math.round((_cfgP.pctSaber||0.35)*_sc2*100)},{key:'h',nom:_cfgP.nomHacer||'HACER',pct:Math.round((_cfgP.pctHacer||0.40)*_sc2*100)},..._cp2.map((c,i)=>({key:'ex'+i,nom:c.nom||('Extra '+(i+1)),pct:parseFloat(c.pct)||0}))];
    })();
    const allHeaders=_allColsHead.map(col=>`<th style="font-size:0.78rem">${col.nom}<br><small>${col.pct}%</small>${repBtn(col.key,'#003366')}</th>`).join('');
    tabla=`<div class="over"><table><thead><tr>
      <th style="background:#f0f4f8;color:#5d6d7e;font-size:0.7rem;min-width:52px;border:1px solid #ddd;padding:5px 4px;text-align:center">ID</th>
      <th style="text-align:left;min-width:200px;font-size:0.78rem">Estudiante</th>
      ${allHeaders}
      <th style="background:#1a5276;font-size:0.78rem">NOTA</th>
      <th style="background:#7d6608;font-size:0.78rem">RECUP.${repBtn('rec','#7d6608')}</th>
      <th style="background:#1a5276;font-size:0.78rem">DEFINITIVA</th>
      ${eHeadFull}
      ${p3Head}
    </tr></thead><tbody>${rows}</tbody></table></div>`;
  }
  let planChart='';
  if(carga&&ests.length){
    const npC=Number(planPer),ncC=Number(planCId);
    const notasC=ests.map(e=>{
      const ndc=((e.nts||{})[ncC]||{})[npC]||{s:0,sb:0,h:0,rec:0,niv:0};
      const bc=_baseNota(ndc,db.config||{});
      const rc=ndc.rec||0,nc2=ndc.niv||0;
      const dv=(bc<3&&rc>0)?rc:bc;return (npC===_numPer&&nc2>0)?nc2:dv;
    });
    const cBajo=notasC.filter(n=>n<3).length;
    const cBas=notasC.filter(n=>n>=3&&n<4).length;
    const cAlto=notasC.filter(n=>n>=4&&n<4.7).length;
    const cSup=notasC.filter(n=>n>=4.7).length;
    const cTot=notasC.length||1;
    const barC=(n,col,lbl)=>'<div style="display:flex;align-items:center;gap:6px;margin-bottom:5px">'+
      '<span style="width:64px;font-size:0.73rem;color:#555;text-align:right">'+lbl+'</span>'+
      '<div style="flex:1;background:#eee;border-radius:4px;height:17px">'+
      '<div style="width:'+(n/cTot*100).toFixed(0)+'%;background:'+col+';height:100%;border-radius:4px;min-width:'+(n>0?'16px':'0')+';transition:width 0.5s"></div></div>'+
      '<span style="width:70px;font-size:0.73rem;font-weight:bold;color:'+col+'">'+n+' ('+( n/cTot*100).toFixed(0)+'%)</span>'+
    '</div>';
    planChart='<div style="background:#f8f9fa;border-radius:8px;padding:12px 16px;margin-top:10px;border:1px solid #e0e0e0">'+
      '<b style="font-size:0.85rem;color:#003366">📊 Estadística del Periodo '+npC+' — '+carga.m+'</b>'+
      '<div style="margin-top:8px">'+barC(cBajo,'#c0392b','BAJO')+barC(cBas,'#e67e22','BÁSICO')+barC(cAlto,'#1a5276','ALTO')+barC(cSup,'#1a7531','SUPERIOR')+'</div>'+
      '<div style="font-size:0.76rem;color:#888;margin-top:4px">Total: '+cTot+' | ✅ Aprob: '+(cBas+cAlto+cSup)+' | ❌ Repob: '+cBajo+'</div></div>';
  }
  const _isAdmin=sesion&&(sesion.r==='admin'||(gestorSesion&&gestorEnPlataforma));
  const _perAct=db.periodosActivos||(()=>{const a=[];for(let i=0;i<_numPer;i++)a.push(true);return a;})();
  // Asegurar que planPer no exceda _numPer
  if(Number(planPer)>_numPer) planPer=String(_numPer);
  const _perActual=_perAct[Number(planPer)-1]!==false;
  const _panelPeriodos=_isAdmin?`<div style="background:#eaf4fb;border:1px solid #aed6f1;border-radius:8px;padding:10px 14px;margin-bottom:12px">
    <b style="font-size:0.82rem;color:#1a5276">🔐 Control de Periodos (solo administrador) — ${_numPer} periodos configurados</b>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px">
      ${Array.from({length:_numPer},(_,i)=>i+1).map(n=>{const abierto=_perAct[n-1]!==false;return `<button onclick="togglePeriodo(${n})" style="padding:6px 14px;border-radius:6px;border:none;cursor:pointer;font-size:0.82rem;font-weight:bold;background:${abierto?'#27ae60':'#c0392b'};color:#fff">${abierto?'🔓':'🔒'} P${n}</button>`;}).join('')}
    </div>
    <div style="font-size:0.74rem;color:#555;margin-top:6px">🔓 Abierto = docentes pueden registrar notas &nbsp;|&nbsp; 🔒 Cerrado = solo lectura</div>
  </div>`:'';
  const _perCerradoAlert=(!_perActual&&!_isAdmin)?`<div style="background:#fdecea;border:1px solid #e74c3c;border-radius:7px;padding:8px 12px;margin-bottom:10px;color:#922b21;font-size:0.84rem;font-weight:bold">🔒 El Periodo ${planPer} está CERRADO. Contacte al administrador para abrirlo.</div>`:'';
  const _perCerradoAdminAlert=(!_perActual&&_isAdmin)?`<div style="background:#fff3cd;border:1px solid #f1c40f;border-radius:7px;padding:6px 12px;margin-bottom:8px;color:#7d6608;font-size:0.82rem">⚠️ El Periodo ${planPer} está cerrado. Haga clic en 🔒 P${planPer} para abrirlo.</div>`:'';
  return `<h3 class="sec-title">Planilla de Calificaciones</h3>
  <div class="card">
    ${_panelPeriodos}
    ${_perCerradoAlert}
    ${_perCerradoAdminAlert}
    <div class="grid2" style="margin-bottom:15px">
      <div><label class="lbl">Periodo</label><select id="planPer" onchange="cambiarPlanPer(this.value)">
        ${Array.from({length:_numPer},(_,i)=>i+1).map(n=>`<option value="${n}"${planPer===String(n)?' selected':''}>Periodo ${n} ${(_perAct[n-1]!==false)?'🔓':'🔒'}</option>`).join('')}
      </select></div>
      <div><label class="lbl">Asignatura</label><select id="planCId" onchange="cambiarPlanCId(this.value)">${matsOpts}</select></div>
    </div>
    ${carga?`<div class="info-box"><b>Grado:</b> ${carga.g} | <b>Área:</b> ${carga.a} | <b>Docente:</b> ${carga.dn}</div>`:''}
    ${planPer===String(_numPer)?`<div class="warn-box">ℹ️ <b>Nivelación (P${_numPer}):</b> Solo para estudiantes que perdieron entre 1 y 2 áreas.</div>`:''}
    <div style="background:#f0f7ff;border:1px solid #b8d4f0;border-radius:10px;padding:10px 12px;margin-bottom:10px">
      <div style="font-size:0.8rem;font-weight:bold;color:#003366;margin-bottom:8px">📊 Gestión de Planilla Excel</div>
      <div class="flex-gap" style="flex-wrap:wrap;gap:8px;margin-bottom:8px">
        <button class="btn btn-blue" onclick="descargarPlanillaXLSX()" style="font-size:0.82rem;min-width:160px">📥 Descargar Excel (con notas)</button>
        <button class="btn" onclick="descargarPlanillaXLSX(true)" style="font-size:0.82rem;background:#7f8c8d;color:#fff;border:none;border-radius:6px;padding:8px 14px;cursor:pointer;font-weight:bold;min-width:160px">📄 Descargar Excel (en blanco)</button>
        <button class="btn btn-teal" onclick="pdfPlanillaGrado()" style="font-size:0.82rem">📄 PDF Planilla</button>
        <div id="_xlsxDropZone" ondragover="event.preventDefault();this.style.borderColor='#003366'" ondragleave="this.style.borderColor='#90b8e0'" ondrop="event.preventDefault();const f=event.dataTransfer.files[0];if(f){const inp=document.getElementById('filePlanillaExcel');const dt=new DataTransfer();dt.items.add(f);inp.files=dt.files;cargarPlanillaExcel(inp);}" style="border:2px dashed #90b8e0;border-radius:8px;padding:6px 14px;cursor:pointer;font-size:0.8rem;color:#1a5276;background:#e8f4ff;display:flex;align-items:center;gap:6px;min-width:200px;transition:border-color 0.2s" onclick="document.getElementById('filePlanillaExcel').click()">
          <span style="font-size:1.2rem">📤</span>
          <span><b>Cargar Excel diligenciado</b><br><span style="font-size:0.72rem;color:#5d8aa8">Clic aquí o arrastre el archivo .xlsx</span></span>
        </div>
        <input type="file" id="filePlanillaExcel" accept=".xlsx,.xls,.csv" style="display:none" onchange="cargarPlanillaExcel(this)">
      </div>
      <div id="_xlsxMsg" style="display:none;padding:6px 10px;border-radius:6px;font-size:0.82rem;font-weight:bold;margin-top:4px"></div>
      <div style="font-size:0.73rem;color:#5d8aa8;margin-top:2px">① Descargue → ② Complete notas (SER/SABER/HACER 0.0–5.0) → ③ Cargue de vuelta. <b>No modifique la columna ID ni Nombre.</b></div>
    </div>
    ${tabla}
    ${planChart}
    <div style="margin-top:12px;display:flex;align-items:center;gap:12px;flex-wrap:wrap">
      <div id="_wrapGuardarManual" style="display:${(()=>{_cargarAutoGuardar();return _autoGuardar?'none':'flex'})()};align-items:center;gap:10px;flex-wrap:wrap">
        <button class="btn btn-green" onclick="guardarPlanilla()">💾 GUARDAR CAMBIOS</button>
        <span id="__pendInd" style="display:none;background:#f1c40f;color:#333;font-weight:bold;font-size:0.8rem;padding:5px 12px;border-radius:20px;border:2px solid #d4ac0d">⚠️ 0 nota(s) sin guardar</span>
      </div>
      <button id="_btnAutoGuardar" onclick="_toggleAutoGuardar()" title="${_autoGuardar?'Las notas se guardan al instante — haga clic para cambiar a modo manual':'Las notas esperan GUARDAR CAMBIOS — haga clic para activar guardado automático'}" style="background:${_autoGuardar?'#27ae60':'#7f8c8d'};color:#fff;border:none;border-radius:6px;padding:9px 14px;font-size:0.82rem;cursor:pointer;font-weight:bold;min-height:38px">
        ${_autoGuardar?'⚡ Auto-guardar: ON':'🕹 Auto-guardar: OFF'}
      </button>
    </div>
  </div>`;
}
function cambiarPlanPer(v){planPer=v;renderApp();}
function togglePeriodo(n){
  updDB(d=>{
    const np=(d.config&&d.config.numPeriodos)||4;
    if(!d.periodosActivos||d.periodosActivos.length!==np){
      const prev=d.periodosActivos||[];
      d.periodosActivos=Array.from({length:np},(_,i)=>prev[i]!==false);
    }
    d.periodosActivos[n-1]=!d.periodosActivos[n-1];
    const estado=d.periodosActivos[n-1]?'ABIERTO':'CERRADO';
    setTimeout(()=>alert('✅ Periodo '+n+' ahora está '+estado+'.'),100);
    return d;
  });
  renderApp();
}
function cambiarPlanCId(v){planCId=v;renderApp();}

// Toast no-bloqueante para la planilla (evita alert() en handlers de touch)
function _toastPlan(msg,bg){
  const t=document.createElement('div');
  t.style.cssText='position:fixed;bottom:80px;left:50%;transform:translateX(-50%) translateY(0);background:'+(bg||'#1a3a5c')+';color:#fff;padding:12px 22px;border-radius:24px;font-size:0.88rem;font-weight:bold;z-index:100000;box-shadow:0 4px 20px rgba(0,0,0,.4);pointer-events:none;text-align:center;max-width:88vw;transition:opacity .4s';
  t.textContent=msg;
  document.body.appendChild(t);
  setTimeout(()=>{t.style.opacity='0';setTimeout(()=>{try{t.remove();}catch(e){}},400);},3000);
}

// ===== POPUP SELECTOR DE NOTAS — VERSIÓN MEJORADA =====
// Apertura instantánea al tocar, cierre inmediato tras seleccionar, sigue scroll
let _popupActive=false;
// ── Detectar grados iniciales (Transición/Preescolar) ──
function esGradoInicial(g){
  const gn=(g||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  return /transici|preescol|jardin|kinder|pre.jar|nivel.0|grado.0|prejardin|prejardi|inicial|maternal|parvul/.test(gn);
}
// ── Convertir nota a cualitativo ──
function notaACualitativo(val){
  const c=db.config||{};const es=c.escalaS||4.7,ea=c.escalaA||4.0,eb=c.escalaB||3.0;
  if(val>=es) return {lbl:'S — Superior',color:'#1a5276',letra:'S'};
  if(val>=ea) return {lbl:'A — Alto',color:'#27ae60',letra:'A'};
  if(val>=eb) return {lbl:'B — Básico',color:'#e67e22',letra:'B'};
  return {lbl:'D — Bajo',color:'#c0392b',letra:'D'};
}

function abrirPopupNota(estId,campo,btnEl){
  // Verificar si el periodo está abierto
  const _perN=Number(planPer);
  const _npPopup=(db.config&&db.config.numPeriodos)||4;
  const _perAct=(db.periodosActivos||Array(_npPopup).fill(true));
  const _estaAbierto=_perAct[_perN-1]!==false;
  const _esAdminCheck=sesion&&(sesion.r==='admin'||(gestorSesion&&gestorEnPlataforma));
  if(!_estaAbierto&&!_esAdminCheck){
    setTimeout(()=>_toastPlan('🔒 Periodo '+planPer+' cerrado. Contacte al administrador para abrirlo.','#c0392b'),0);
    return;
  }
  const old=document.getElementById('popupNota');if(old)old.remove();
  _popupActive=true;
  const popup=document.createElement('div');
  popup.id='popupNota';
  popup.style.cssText='position:fixed;z-index:99999;background:#fff;border:2px solid #003366;border-radius:10px;box-shadow:0 8px 32px rgba(0,0,0,0.4);padding:12px;width:340px;max-height:92vh;overflow-y:auto;touch-action:none;';

  // Detectar si es grado inicial
  const _cargaAct=planCId?db.carga.find(function(x){return x.id===Number(planCId);}):null;
  const _gradoAct=_cargaAct?_cargaAct.g:'';
  const _esInicial=esGradoInicial(_gradoAct);

  const rangos=[[0.0,0.9],[1.0,1.9],[2.0,2.9],[3.0,3.9],[4.0,4.9],[5.0,5.0]];
  const cols={'0':'#c0392b','1':'#c0392b','2':'#c0392b','3':'#e67e22','4':'#27ae60','5':'#1a5276'};
  const labels={'0':'BAJO','1':'BAJO','2':'BAJO','3':'BÁSICO','4':'ALTO','5':'SUPERIOR'};
  let html='<div style="font-size:0.85rem;font-weight:bold;color:#003366;margin-bottom:10px;text-align:center;border-bottom:2px solid #003366;padding-bottom:6px">🎯 Seleccione la nota</div>';

  // ── BLOQUE CUALITATIVO (solo para transición/preescolar) ──
  if(_esInicial){
    html+='<div style="background:#f0f4ff;border:1px solid #c0d0f0;border-radius:8px;padding:10px;margin-bottom:10px">';
    html+='<div style="font-size:0.75rem;font-weight:bold;color:#003366;margin-bottom:7px;text-align:center">🌟 Escala Cualitativa (Transición/Preescolar)</div>';
    const cualOpts=[
      {lbl:'S — SUPERIOR',val:4.8,color:'#1a5276',desc:'4.7 – 5.0'},
      {lbl:'A — ALTO',val:4.2,color:'#27ae60',desc:'4.0 – 4.6'},
      {lbl:'B — BÁSICO',val:3.4,color:'#e67e22',desc:'3.0 – 3.9'},
      {lbl:'D — BAJO',val:1.5,color:'#c0392b',desc:'0.0 – 2.9'}
    ];
    html+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">';
    cualOpts.forEach(function(o){
      html+='<button onpointerdown="event.preventDefault();event.stopPropagation();seleccionarNotaRapido(\''+estId+'\',\''+campo+'\','+o.val+')" style="padding:8px 4px;font-size:0.78rem;font-weight:bold;background:'+o.color+';color:#fff;border:none;border-radius:6px;cursor:pointer;min-height:38px;touch-action:manipulation;line-height:1.3">'+o.lbl+'<br><span style="font-size:0.62rem;opacity:0.85">'+o.desc+'</span></button>';
    });
    html+='</div></div>';
    html+='<div style="font-size:0.73rem;text-align:center;color:#7f8c8d;margin-bottom:8px">— o ingrese nota exacta —</div>';
  }

  rangos.forEach(([min,max])=>{
    const piso=String(Math.floor(min));
    const col=cols[piso]||'#333';
    const lbl=labels[piso]||'';
    html+='<div style="display:flex;gap:3px;margin-bottom:5px;align-items:center">';
    html+='<span style="font-size:0.65rem;font-weight:bold;color:'+col+';min-width:44px;text-align:right;padding-right:4px">'+lbl+'</span>';
    let v=min;
    while(v<=max+0.001){
      const vf=parseFloat(v.toFixed(1));
      html+='<button onpointerdown="event.preventDefault();event.stopPropagation();seleccionarNotaRapido(\''+estId+'\',\''+campo+'\','+vf+')" style="flex:1;padding:8px 1px;font-size:0.82rem;font-weight:bold;background:'+col+';color:#fff;border:none;border-radius:5px;cursor:pointer;min-width:28px;min-height:38px;touch-action:manipulation;-webkit-tap-highlight-color:transparent">'+vf.toFixed(1)+'</button>';
      v=parseFloat((v+0.1).toFixed(1));
    }
    html+='</div>';
  });
  html+='<div style="margin-top:10px;border-top:1px solid #eee;padding-top:10px;text-align:center"><button id="vozNotaBtn" onpointerdown="event.preventDefault();iniciarVozNota(\''+estId+'\',\''+campo+'\')" style="background:#8e44ad;color:#fff;border:none;border-radius:6px;padding:8px 16px;font-size:0.82rem;cursor:pointer;min-height:36px;touch-action:manipulation">🎙️ Dictar por Voz</button><div id="vozNotaStatus" style="font-size:0.7rem;color:#888;margin-top:3px"></div></div>';
  html+='<div style="text-align:center;margin-top:8px"><button onpointerdown="event.preventDefault();cerrarPopupNota()" style="font-size:0.82rem;padding:8px 22px;background:#7f8c8d;color:#fff;border:none;border-radius:6px;cursor:pointer;min-height:38px;touch-action:manipulation">✕ Cerrar</button></div>';
  popup.innerHTML=html;
  popup.addEventListener('pointerdown',ev=>ev.stopPropagation());
  document.body.appendChild(popup);

  function posicionarPopup(){
    const p=document.getElementById('popupNota');if(!p) return;
    const r=btnEl.getBoundingClientRect();
    const pw=p.offsetWidth||340;const ph=p.offsetHeight||300;
    const vw=window.innerWidth;const vh=window.innerHeight;
    let top=r.bottom+8;let left=r.left;
    if(top+ph>vh-10) top=Math.max(10,r.top-ph-8);
    if(left+pw>vw-10) left=Math.max(10,vw-pw-10);
    if(left<5) left=5;
    p.style.top=top+'px';p.style.left=left+'px';
  }
  posicionarPopup();

  const _repos=()=>{if(document.getElementById('popupNota')) posicionarPopup(); else{window.removeEventListener('scroll',_repos,true);window.removeEventListener('resize',_repos);}};
  window.addEventListener('scroll',_repos,{passive:true,capture:true});
  window.addEventListener('resize',_repos,{passive:true});

  const p2=document.getElementById('popupNota');
  if(p2){
    p2._cleanRepos=()=>{window.removeEventListener('scroll',_repos,true);window.removeEventListener('resize',_repos);};
    // El popup NO se cierra al hacer clic afuera. Solo se cierra con el botón Cerrar o al seleccionar nota.
  }
}


// ============================================================
// VOZ PARA ENTRADA DE NOTAS EN PLANILLA
// ============================================================
let _vozNotaRec=null;

function iniciarVozNota(estId,campo){
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){alert('Use Chrome o Edge para dictado por voz.');return;}
  const statusEl=document.getElementById('vozNotaStatus');
  const btn=document.getElementById('vozNotaBtn');
  if(_vozNotaRec){try{_vozNotaRec.stop();}catch(e){}_vozNotaRec=null;
    if(btn){btn.textContent='🎙️ Dictar por Voz';btn.style.background='#8e44ad';}
    if(statusEl)statusEl.textContent='';return;}
  _vozNotaRec=new SR();
  _vozNotaRec.lang='es-CO';_vozNotaRec.continuous=false;_vozNotaRec.interimResults=false;
  if(btn){btn.textContent='⏹ Detener';btn.style.background='#c0392b';}
  if(statusEl)statusEl.textContent='🎙️ Escuchando... diga el número (ej: "cuatro punto cinco", "3.5", "cinco")';
  _vozNotaRec.onresult=function(ev){
    let txt=(ev.results[0]&&ev.results[0][0]&&ev.results[0][0].transcript)||'';
    txt=txt.toLowerCase().trim();
    const mapPal={
      'cero':0,'uno':1,'dos':2,'tres':3,'cuatro':4,'cinco':5,
      'un punto':1,'dos punto':2,'tres punto':3,'cuatro punto':4,
      'uno punto':1,'cero punto':0,
      'un coma':1,'dos coma':2,'tres coma':3,'cuatro coma':4
    };
    let val=null;
    const numMatch=txt.match(/(\d+)[.,\s]*(\d?)/);
    if(numMatch){
      const entero=parseInt(numMatch[1]);const dec=numMatch[2]?parseInt(numMatch[2]):0;
      val=parseFloat((entero+dec/10).toFixed(1));
    }
    if(val===null){
      for(const [k,v] of Object.entries(mapPal)){
        if(txt.startsWith(k)){
          const resto=txt.slice(k.length).trim();
          const dec2=resto.match(/^(\d)/);
          val=dec2?parseFloat(v+parseInt(dec2[1])/10):v;
          break;
        }
      }
    }
    if(val!==null&&val>=0&&val<=5){
      val=Math.round(val*10)/10;
      if(statusEl)statusEl.textContent='✅ Nota: '+val.toFixed(1);
      setTimeout(function(){cerrarPopupNota();seleccionarNotaRapido(estId,campo,val);},400);
    } else {
      if(statusEl)statusEl.textContent='❌ No reconocido ("'+txt+'"). Intente de nuevo.';
      _vozNotaRec=null;if(btn){btn.textContent='🎙️ Dictar por Voz';btn.style.background='#8e44ad';}
    }
    if(_vozNotaRec){_vozNotaRec=null;if(btn){btn.textContent='🎙️ Dictar por Voz';btn.style.background='#8e44ad';}}
  };
  _vozNotaRec.onerror=function(){
    if(statusEl)statusEl.textContent='❌ Error de micrófono.';
    _vozNotaRec=null;if(btn){btn.textContent='🎙️ Dictar por Voz';btn.style.background='#8e44ad';}
  };
  _vozNotaRec.onend=function(){
    if(_vozNotaRec){_vozNotaRec=null;if(btn){btn.textContent='🎙️ Dictar por Voz';btn.style.background='#8e44ad';}}
  };
  try{_vozNotaRec.start();}catch(e){if(statusEl)statusEl.textContent='Error al iniciar micrófono.';_vozNotaRec=null;}
}

function cerrarPopupNota(){
  _popupActive=false;
  const p=document.getElementById('popupNota');
  if(!p) return;
  if(p._cleanRepos) p._cleanRepos();
  p.remove();
}

// ── SISTEMA DE NOTAS PENDIENTES ──────────────────────────────────────────────
// Las notas ingresadas se guardan como "pendientes" (borde amarillo).
// Los cálculos de NOTA BASE y DEFINITIVA SOLO se actualizan al pulsar "GUARDAR CAMBIOS".
// Esto garantiza que el docente pueda revisar antes de confirmar.
let _notasPendientes = {};
// Auto-guardar: cuando está activo, las notas se guardan de inmediato sin pasar por pendientes.
let _autoGuardar = false;
function _cargarAutoGuardar(){ _autoGuardar=!!(db.config&&db.config.autoGuardar); }
function _toggleAutoGuardar(){
  _autoGuardar=!_autoGuardar;
  updDB(d=>{if(!d.config)d.config={};d.config.autoGuardar=_autoGuardar;return d;});
  const btn=document.getElementById('_btnAutoGuardar');
  if(btn){btn.textContent=_autoGuardar?'⚡ Auto-guardar: ON':'🕹 Auto-guardar: OFF';btn.style.background=_autoGuardar?'#27ae60':'#7f8c8d';}
  const manualWrap=document.getElementById('_wrapGuardarManual');
  if(manualWrap)manualWrap.style.display=_autoGuardar?'none':'flex';
  if(_autoGuardar&&Object.keys(_notasPendientes).length){
    _aplicarNotasPendientesEnDB();_actualizarIndicadorPendientes();renderApp();
  }
}

function _actualizarIndicadorPendientes(){
  const n=Object.keys(_notasPendientes).length;
  document.querySelectorAll('[id="__pendInd"]').forEach(function(el){
    if(n>0){el.textContent='⚠️ '+n+' nota(s) sin guardar';el.style.display='inline-block';}
    else{el.style.display='none';}
  });
}

// Restaura el estado visual de notas pendientes después de cualquier re-render.
// Imprescindible cuando la sincronización en tiempo real re-dibuja la planilla
// pero hay notas que el usuario ingresó y aún no guardó.
function _reaplicarPendientes(){
  const keys=Object.keys(_notasPendientes);
  if(!keys.length) return;
  keys.forEach(function(k){
    const p=_notasPendientes[k];
    // Solo re-aplicar si el panel de planilla activo coincide con la asignatura/periodo
    if(String(p.cId)!==String(planCId)||String(p.per)!==String(planPer)) return;
    const notaVal=parseFloat(p.valor);
    const btnNota=document.getElementById('nota-btn-'+p.estId+'-'+p.campo);
    if(btnNota){
      btnNota.textContent=isNaN(notaVal)?'0.0':notaVal.toFixed(1);
      btnNota.style.background=colorNota(isNaN(notaVal)?0:notaVal);
      btnNota.style.outline='3px solid #f1c40f';
      btnNota.title='Nota pendiente de guardar — pulse GUARDAR CAMBIOS para confirmar';
    }
  });
  _actualizarIndicadorPendientes();
}

function _aplicarNotasPendientesEnDB(){
  const keys=Object.keys(_notasPendientes);
  if(!keys.length) return;
  const pending=JSON.parse(JSON.stringify(_notasPendientes));
  _notasPendientes={};
  updDB(function(d){
    keys.forEach(function(k){
      const p=pending[k];
      // Comparación con String() para evitar problemas de tipo número vs string en los IDs
      const idx=d.ests.findIndex(function(x){return String(x.id)===String(p.estId);});
      if(idx===-1) return;
      const e=d.ests[idx];
      // Inicializar nts si no existe (estudiantes nuevos de pre-matrícula u otros módulos)
      const nts=JSON.parse(JSON.stringify(e.nts||{}));
      const cId=Number(p.cId);const per=Number(p.per);
      const numVal=Math.min(5,Math.max(0,parseFloat(p.valor)||0));
      if(!nts[cId]) nts[cId]={};
      if(!nts[cId][per]) nts[cId][per]={s:0,sb:0,h:0,rec:0,niv:0};
      nts[cId][per][p.campo]=numVal;
      d.ests[idx]=Object.assign({},e,{nts});
    });
    return d;
  });
}

function seleccionarNotaRapido(estId,campo,valor){
  cerrarPopupNota();
  const notaVal=parseFloat(valor);
  const btnNota=document.getElementById('nota-btn-'+estId+'-'+campo);
  if(_autoGuardar){
    // Auto-guardar: guardar inmediatamente en DB sin pasar por pendientes
    saveNota(estId,campo,valor);
    if(btnNota){btnNota.textContent=notaVal.toFixed(1);btnNota.style.background=colorNota(notaVal);btnNota.style.outline='none';btnNota.title='✅ Guardada automáticamente';}
    return;
  }
  // Modo manual: almacenar como pendiente — borde amarillo hasta GUARDAR CAMBIOS
  const _cId=planCId,_per=planPer;
  const key=estId+'_'+campo+'_'+_cId+'_'+_per;
  _notasPendientes[key]={estId,campo,valor,cId:_cId,per:_per};
  _actualizarIndicadorPendientes();
  if(btnNota){
    btnNota.textContent=notaVal.toFixed(1);
    btnNota.style.background=colorNota(notaVal);
    btnNota.style.outline='3px solid #f1c40f';
    btnNota.title='Nota pendiente de guardar — pulse GUARDAR CAMBIOS';
  }
}

