// ===== REPLICAR LA MISMA NOTA A TODA UNA COLUMNA =====
// Permite al docente seleccionar UNA nota y aplicarla a TODOS los estudiantes
// del grado en la columna indicada (SER, SABER, HACER, RECUP. o NIVELACIÓN).
function replicarColumna(campo){
  const carga=db.carga.find(x=>x.id===Number(planCId));
  if(!carga){alert('Seleccione una asignatura primero.');return;}
  const ests=db.ests.filter(x=>x.g===carga.g);
  if(!ests.length){alert('No hay estudiantes en este grado.');return;}
  const nombreCampo={s:'SER',sb:'SABER',h:'HACER',rec:'RECUPERACIÓN',niv:'NIVELACIÓN'}[campo]||campo.toUpperCase();
  const old=document.getElementById('popupNota');if(old)old.remove();
  _popupActive=true;
  const popup=document.createElement('div');
  popup.id='popupNota';
  popup.style.cssText='position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:99999;background:#fff;border:3px solid #c0392b;border-radius:10px;box-shadow:0 8px 32px rgba(0,0,0,0.5);padding:14px;width:360px;max-width:94vw;max-height:92vh;overflow-y:auto;touch-action:none';
  const rangos=[[0.0,0.9],[1.0,1.9],[2.0,2.9],[3.0,3.9],[4.0,4.9],[5.0,5.0]];
  const cols={'0':'#c0392b','1':'#c0392b','2':'#c0392b','3':'#e67e22','4':'#27ae60','5':'#1a5276'};
  const labels={'0':'BAJO','1':'BAJO','2':'BAJO','3':'BÁSICO','4':'ALTO','5':'SUPERIOR'};
  let html='<div style="font-size:0.92rem;font-weight:bold;color:#c0392b;margin-bottom:6px;text-align:center">📋 REPLICAR NOTA A TODA LA COLUMNA</div>';
  html+='<div style="font-size:0.78rem;color:#555;margin-bottom:8px;text-align:center;line-height:1.35"><b>Columna:</b> '+nombreCampo+'<br><b>Asignatura:</b> '+carga.m+' ('+carga.g+')<br><b>Periodo:</b> '+planPer+' &nbsp;|&nbsp; <b>Estudiantes:</b> '+ests.length+'</div>';
  if(campo==='niv'){
    html+='<div style="background:#fff3cd;border:1px solid #f1c40f;border-radius:5px;padding:6px;font-size:0.72rem;color:#7d6608;margin-bottom:8px;text-align:center">⚠️ Solo se aplicará a estudiantes elegibles (los que perdieron entre 1 y 2 áreas).</div>';
  }
  html+='<div style="border-top:2px solid #c0392b;padding-top:8px;margin-bottom:6px;text-align:center;font-size:0.8rem;font-weight:bold;color:#003366">Seleccione la nota para aplicar a TODOS</div>';
  rangos.forEach(([min,max])=>{
    const piso=String(Math.floor(min));
    const col=cols[piso]||'#333';
    const lbl=labels[piso]||'';
    html+='<div style="display:flex;gap:3px;margin-bottom:5px;align-items:center">';
    html+='<span style="font-size:0.65rem;font-weight:bold;color:'+col+';min-width:44px;text-align:right;padding-right:4px">'+lbl+'</span>';
    let v=min;
    while(v<=max+0.001){
      const vf=parseFloat(v.toFixed(1));
      html+='<button onpointerdown="event.preventDefault();event.stopPropagation();aplicarReplicaColumna(\''+campo+'\','+vf+')" style="flex:1;padding:8px 1px;font-size:0.82rem;font-weight:bold;background:'+col+';color:#fff;border:none;border-radius:5px;cursor:pointer;min-width:28px;min-height:38px;touch-action:manipulation;-webkit-tap-highlight-color:transparent">'+vf.toFixed(1)+'</button>';
      v=parseFloat((v+0.1).toFixed(1));
    }
    html+='</div>';
  });
  html+='<div style="text-align:center;margin-top:10px"><button onpointerdown="event.preventDefault();cerrarPopupNota()" style="font-size:0.82rem;padding:8px 22px;background:#7f8c8d;color:#fff;border:none;border-radius:6px;cursor:pointer;min-height:38px;touch-action:manipulation">✕ Cancelar</button></div>';
  popup.innerHTML=html;
  popup.addEventListener('pointerdown',ev=>ev.stopPropagation());
  document.body.appendChild(popup);
}

function aplicarReplicaColumna(campo,valor){
  const carga=db.carga.find(x=>x.id===Number(planCId));
  if(!carga){cerrarPopupNota();return;}
  const numVal=Math.min(5,Math.max(0,parseFloat(valor)||0));
  const cId=Number(planCId),per=Number(planPer);
  const ests=db.ests.filter(x=>x.g===carga.g);
  let aplicados=0,omitidos=0;
  updDB(d=>{
    d.ests.forEach((e,idx)=>{
      if(e.g!==carga.g) return;
      // Para nivelación, sólo aplicar a estudiantes elegibles (1-2 áreas perdidas)
      if(campo==='niv'){
        const ap=calcAreasPerd(e.id,carga.g);
        if(!(per===_getNumPer() && ap>=1 && ap<=2)){omitidos++;return;}
      }
      const nts=JSON.parse(JSON.stringify(e.nts||{}));
      if(!nts[cId]) nts[cId]={};
      if(!nts[cId][per]) nts[cId][per]={s:0,sb:0,h:0,rec:0,niv:0};
      nts[cId][per][campo]=numVal;
      d.ests[idx]={...e,nts};
      aplicados++;
    });
    return d;
  });
  cerrarPopupNota();
  // Limpiar notas pendientes de este campo/asignatura/periodo para que no sobreescriban la réplica
  const _cIdS=String(cId),_perS=String(per);
  Object.keys(_notasPendientes).forEach(function(k){
    const p=_notasPendientes[k];
    if(String(p.cId)===_cIdS&&String(p.per)===_perS&&p.campo===campo) delete _notasPendientes[k];
  });
  _actualizarIndicadorPendientes();
  let msg='✅ Nota '+numVal.toFixed(1)+' aplicada a '+aplicados+' estudiante(s).';
  if(omitidos>0) msg+='\n⚠️ '+omitidos+' estudiante(s) omitido(s) por no ser elegibles para nivelación.';
  alert(msg);
  renderApp();
}


