function seleccionarNotaReplica(campo,valor){
  const popup=document.getElementById('popupNota');
  if(!popup)return;
  popup.setAttribute('data-nota-replica',String(valor));
  document.querySelectorAll('[id^="rbtn-"]').forEach(b=>{
    b.style.border='2px solid transparent';
    b.style.outline='none';
  });
  const key='rbtn-'+valor.toFixed(1).replace('.','_');
  const btn=document.getElementById(key);
  if(btn){btn.style.border='2px solid #fff';btn.style.outline='3px solid #f39c12';}
  const lbl=document.getElementById('notaSeleccionadaLabel');
  if(lbl)lbl.innerHTML='<b style="color:#1a5276">Nota seleccionada: '+valor.toFixed(1)+'</b>';
}

function actualizarContadorReplica(){
  const cnt=document.querySelectorAll('.replic-est:checked').length;
  const el=document.getElementById('cntReplica');
  if(el)el.textContent=cnt;
}

function aplicarReplicaSeleccionados(campo){
  const popup=document.getElementById('popupNota');
  const valorStr=popup?popup.getAttribute('data-nota-replica'):'';
  if(valorStr===''||valorStr===null){alert('Primero seleccione una nota (paso 1).');return;}
  const valor=parseFloat(valorStr);
  const checks=document.querySelectorAll('.replic-est:checked');
  // IDs como strings para evitar problemas de tipo (e.id puede ser "est_xxx" o número)
  const ids=new Set(Array.from(checks).map(c=>String(c.value)));
  if(!ids.size){alert('Seleccione al menos un estudiante.');return;}
  const carga=db.carga.find(x=>x.id===Number(planCId));
  if(!carga){cerrarPopupNota();return;}
  const numVal=Math.min(5,Math.max(0,valor));
  const cId=Number(planCId),per=Number(planPer);
  let aplicados=0,omitidos=0;
  updDB(d=>{
    d.ests.forEach((e,idx)=>{
      if(!ids.has(String(e.id)))return; // comparar como strings
      if(campo==='niv'){
        const ap=calcAreasPerd(e.id,carga.g);
        if(!(per===_getNumPer()&&ap>=1&&ap<=2)){omitidos++;return;}
      }
      const nts=JSON.parse(JSON.stringify(e.nts||{}));
      if(!nts[cId])nts[cId]={};
      if(!nts[cId][per])nts[cId][per]={s:0,sb:0,h:0,rec:0,niv:0};
      nts[cId][per][campo]=numVal;
      d.ests[idx]={...e,nts};
      aplicados++;
    });
    return d;
  });
  cerrarPopupNota();
  // Limpiar pendientes de los estudiantes seleccionados para este campo/asignatura/periodo
  const _cIdS=String(cId),_perS=String(per);
  Object.keys(_notasPendientes).forEach(function(k){
    const p=_notasPendientes[k];
    if(String(p.cId)===_cIdS&&String(p.per)===_perS&&p.campo===campo&&ids.has(String(p.estId))) delete _notasPendientes[k];
  });
  _actualizarIndicadorPendientes();
  let msg='✅ Nota '+numVal.toFixed(1)+' aplicada a '+aplicados+' estudiante(s) seleccionado(s).';
  if(omitidos>0)msg+='\n⚠️ '+omitidos+' omitido(s) por no ser elegibles para nivelación.';
  alert(msg);
  renderApp();
}

// ===== PLANILLA CSV
// ===== PLANILLA CSV DOWNLOAD/UPLOAD =====
function pdfPlanillaGrado(){
  const carga=db.carga.find(x=>x.id===Number(planCId));
  if(!carga){alert('Seleccione una asignatura');return;}
  // Aplicar notas pendientes antes de generar el PDF para que aparezcan las notas actuales
  if(typeof _aplicarNotasPendientesEnDB==='function'&&Object.keys(_notasPendientes||{}).length)_aplicarNotasPendientesEnDB();
  const ests=db.ests.filter(x=>x.g===carga.g).sort((a,b)=>a.n.localeCompare(b.n));
  if(!ests.length){alert('No hay estudiantes');return;}
  const per=Number(planPer);
  const doc=getPDF('l');
  doc.setFontSize(8);doc.setFont('helvetica','bold');doc.setTextColor(0,51,102);
  doc.text('PLANILLA DE CALIFICACIONES',148,10,{align:'center'});
  doc.setFontSize(7);doc.setFont('helvetica','normal');doc.setTextColor(0);
  var _sh2=doc.splitTextToSize(getROT3()+' | Grado: '+carga.g+' | Asig: '+carga.m+' | P: '+per+' | Año: '+db.anio+' | Doc: '+carga.dn,270);doc.text(_sh2,148,16,{align:'center'});
  const _cfgPdf=db.config||{};const _colsPdf=_cfgPdf.columnasExtra||[];
  const _totalExPdf=_colsPdf.reduce((s,c)=>(s+(parseFloat(c.pct)||0)/100),0);
  const _sclPdf=Math.max(0,1-_totalExPdf);
  const _pSPdf=Math.round((_cfgPdf.pctSer||0.25)*_sclPdf*100);
  const _pSbPdf=Math.round((_cfgPdf.pctSaber||0.35)*_sclPdf*100);
  const _pHPdf=Math.round((_cfgPdf.pctHacer||0.40)*_sclPdf*100);
  const _nSPdf=_cfgPdf.nomSer||'SER';const _nSbPdf=_cfgPdf.nomSaber||'SABER';const _nHPdf=_cfgPdf.nomHacer||'HACER';
  const _exHdPdf=_colsPdf.map((c,i)=>c.nom+' '+(parseFloat(c.pct)||0)+'%');
  const head=[['#','ESTUDIANTE',_nSPdf+' '+_pSPdf+'%',_nSbPdf+' '+_pSbPdf+'%',_nHPdf+' '+_pHPdf+'%',..._exHdPdf,'NOTA BASE','RECUP.','DEFINITIVA']];
  const body=ests.map((e,i)=>{
    const nd=((e.nts||{})[Number(planCId)]||{})[per]||{s:0,sb:0,h:0,rec:0,niv:0};
    const s=nd.s||0,sb=nd.sb||0,h=nd.h||0,rec=nd.rec||0,niv=nd.niv||0;
    const base=_baseNota(nd,_cfgPdf);
    const _npPdf=_getNumPer();
    const defV=(base<3&&rec>0)?rec:base;const defF=(per===_npPdf&&niv>0)?niv:defV;
    const exCols=_colsPdf.map((_,i2)=>(nd['ex'+i2]||0).toFixed(1));
    return[i+1,e.n,s.toFixed(1),sb.toFixed(1),h.toFixed(1),...exCols,base.toFixed(1),rec>0?rec.toFixed(1):'—',defF.toFixed(1)];
  });
  doc.autoTable({head,body,startY:20,styles:{fontSize:7,cellPadding:2,halign:'center'},
    headStyles:{fillColor:[0,51,102],textColor:255,fontStyle:'bold'},
    columnStyles:{1:{halign:'left',cellWidth:70}},
    didParseCell:d=>{if(d.section==='body'&&d.column.index>=2){const v=parseFloat(d.cell.raw);if(!isNaN(v)&&v<3) d.cell.styles.textColor=[192,57,43];}}
  });
  const fy=doc.lastAutoTable.finalY+10;
  doc.setFontSize(7.5);doc.setFont('helvetica','bold');
  doc.line(14,fy,100,fy);doc.line(200,fy,280,fy);
  doc.text(db.rectora||'RECTOR(A)',57,fy+5,{align:'center'});
  doc.text((carga.dn||'DOCENTE').toUpperCase(),240,fy+5,{align:'center'});
  doc.setFont('helvetica','normal');doc.text('RECTOR(A)',57,fy+9,{align:'center'});doc.text('DOCENTE',240,fy+9,{align:'center'});
  doc.save('Planilla_'+carga.m.replace(/ /g,'_')+'_'+carga.g+'_P'+per+'_'+db.anio+'.pdf');
}

function _resolverColumnas(cfg){
  // Devuelve array unificado {key, nom, pct} respetando columnasBase o compat legacy
  const c=cfg||{};
  if(c.columnasBase&&c.columnasBase.length) return c.columnasBase;
  const ex=(c.columnasExtra||[]).map((col,i)=>({key:'ex'+i,nom:col.nom||('Extra '+(i+1)),pct:col.pct||0}));
  const tex=ex.reduce((s,col)=>(s+(parseFloat(col.pct)||0)/100),0);const sc=Math.max(0,1-tex);
  return [
    {key:'s',nom:c.nomSer||'SER',pct:Math.round((c.pctSer||0.25)*sc*100)},
    {key:'sb',nom:c.nomSaber||'SABER',pct:Math.round((c.pctSaber||0.35)*sc*100)},
    {key:'h',nom:c.nomHacer||'HACER',pct:Math.round((c.pctHacer||0.40)*sc*100)},
    ...ex
  ];
}
function _xlsxDescargarBlob(wb,fileName){
  // Genera el archivo como ArrayBuffer y descarga via Blob (máxima compatibilidad: Chrome, Firefox, Safari, móviles)
  const wbout=XLSX.write(wb,{bookType:'xlsx',type:'array'});
  const blob=new Blob([wbout],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download=fileName;a.style.display='none';
  document.body.appendChild(a);
  a.click();
  setTimeout(function(){try{URL.revokeObjectURL(url);document.body.removeChild(a);}catch(e){}},3000);
}
function descargarPlanillaXLSX(enBlanco){
  const _dlMsg=document.getElementById('_xlsxMsg');
  function _showXlsxErr(msg){
    if(_dlMsg){_dlMsg.textContent=msg;_dlMsg.style.display='block';_dlMsg.style.background='#fdecea';_dlMsg.style.color='#922b21';}
    else alert(msg);
    console.error('descargarPlanillaXLSX:',msg);
  }
  // Esperar hasta 3s a que cargue la librería si aún no está disponible
  if(typeof XLSX==='undefined'){
    let _w=0;const _wait=setInterval(function(){
      _w+=200;
      if(typeof XLSX!=='undefined'){clearInterval(_wait);descargarPlanillaXLSX(enBlanco);}
      else if(_w>3000){clearInterval(_wait);_showXlsxErr('❌ Librería Excel no cargada. Verifique conexión a internet y recargue la página.');}
    },200);
    return;
  }
  const carga=db.carga.find(x=>x.id===Number(planCId));
  if(!carga){alert('Seleccione una asignatura primero.');return;}
  if(!enBlanco&&typeof _aplicarNotasPendientesEnDB==='function'&&Object.keys(_notasPendientes||{}).length)_aplicarNotasPendientesEnDB();
  const per=Number(planPer);
  const ests=db.ests.filter(x=>x.g===carga.g).sort((a,b)=>a.n.localeCompare(b.n));
  if(!ests.length){alert('No hay estudiantes registrados en el grado '+carga.g+'.');return;}
  const _cfgXls=db.config||{};
  const _colsXls=_resolverColumnas(_cfgXls);
  // ── Estructura de columnas (izquierda a derecha) ────────────────────────────
  // A: ID_SISTEMA  (oculta — ID interno de BD, usado para import exacto)
  // B: DOCUMENTO   (visible — cédula/TI del estudiante)
  // C: NOMBRE COMPLETO (visible)
  // D+: notas SER / SABER / HACER / extras, RECUPERACIÓN, NIVELACIÓN, NOTA BASE, DEFINITIVA
  const encabezado=[
    'ID_SISTEMA','DOCUMENTO IDENTIDAD','NOMBRE COMPLETO',
    ..._colsXls.map(c=>c.nom+' ('+c.pct+'%)'),
    'RECUPERACIÓN','NIVELACIÓN (P'+per+')','NOTA BASE','DEFINITIVA'
  ];
  // Fila de claves internas (usada por el importador para mapeo exacto de columnas)
  const camposRow=['#ID_SISTEMA','#DOCUMENTO','#NOMBRE',..._colsXls.map(c=>c.key),'rec','niv','#BASE','#DEF'];
  const instRow=['INSTRUCCIONES: Complete solo las columnas de notas ('+_colsXls.map(c=>c.nom).join('/')+') con valores de 0.0 a 5.0. NO modifique las columnas ID_SISTEMA, DOCUMENTO ni NOMBRE. Guarde como .xlsx y cargue de vuelta al sistema.'];
  const infoRow=['Institucion: '+(db.nombre||'')+'  |  Grado: '+carga.g+'  |  Area: '+(carga.a||'')+'  |  Asignatura: '+carga.m+'  |  Docente: '+carga.dn+'  |  Periodo: '+per+'  |  Anio: '+db.anio];
  // Filas de datos de estudiantes — mismo patrón que xlsxConsolidado (que sí funciona)
  const _dataRows=ests.map(function(est){
    const nc=Number(planCId);
    const _ntsObj=est.nts||{};
    const _ndPer=(_ntsObj[nc]||_ntsObj[String(nc)]||{});
    const nd=enBlanco?{}:(_ndPer[per]||_ndPer[String(per)]||{});
    const base=enBlanco?0:_baseNota(nd,_cfgXls);
    const rv=nd.rec||0,nv=nd.niv||0;
    const defV=(base<3&&rv>0)?rv:base;const defF=(nv>0)?nv:defV;
    // Cols A,B,C: texto plano — SheetJS los almacena como string porque son strings JS
    // Cols D+: número plano (0-5) o string vacío si enBlanco
    var fila=[
      String(est.id||''),
      String(est.ti||est.cc||est.doc||''),
      String(est.n||'')
    ];
    _colsXls.forEach(function(c){
      fila.push(enBlanco?'':(nd[c.key]!=null?nd[c.key]:0));
    });
    fila.push(enBlanco?'':rv);
    fila.push(enBlanco?'':nv);
    fila.push(enBlanco?'':parseFloat(base.toFixed(2)));
    fila.push(enBlanco?'':parseFloat(defF.toFixed(2)));
    return fila;
  });
  try{
    // Mismo patrón que xlsxConsolidado y exportarEstudiantesXLSX — sin !freeze
    const ws=XLSX.utils.aoa_to_sheet([instRow,infoRow,[],encabezado,camposRow].concat(_dataRows));
    ws['!cols']=[{wch:8},{wch:18},{wch:40}]
      .concat(_colsXls.map(function(){return {wch:14};}))
      .concat([{wch:14},{wch:16},{wch:13},{wch:13}]);
    const wb=XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb,ws,'Planilla');
    const fileName='Planilla_'+carga.m.replace(/[^a-zA-Z0-9]/g,'_')+'_'+carga.g.replace(/[^a-zA-Z0-9]/g,'_')+'_P'+per+'_'+db.anio+'.xlsx';
    _xlsxDescargarBlob(wb,fileName);
    const _dlInfo='✅ Planilla descargada: '+ests.length+' estudiante(s) | Grado: '+carga.g+' | Asig: '+carga.m+' | P'+per+(enBlanco?' (EN BLANCO)':'');
    if(_dlMsg){_dlMsg.textContent=_dlInfo;_dlMsg.style.display='block';_dlMsg.style.background='#eafaf1';_dlMsg.style.color='#1a5276';}
    else alert(_dlInfo);
    console.log('✅ Excel planilla:',fileName,'|',ests.length,'est.');
  }catch(ex){
    console.error('[XLSX planilla] Error:',ex.stack||ex.message||ex);
    _showXlsxErr('❌ Error al generar el Excel: '+ex.message+'. Intente recargar la página.');
  }
}

function descargarPlanillaCSV(){
  const carga=db.carga.find(x=>x.id===Number(planCId));
  if(!carga){alert('Seleccione una asignatura');return;}
  const ests=db.ests.filter(x=>x.g===carga.g).sort((a,b)=>a.n.localeCompare(b.n));
  if(!ests.length){alert('No hay estudiantes');return;}
  const per=Number(planPer);
  const _cfgCsv=db.config||{};
  const _colsCsv=_resolverColumnas(_cfgCsv);
  const headers=['ID_ESTUDIANTE','NOMBRE',..._colsCsv.map(c=>c.nom),'RECUPERACION','NIVELACION'];
  const rows=ests.map(e=>{
    const nd=((e.nts||{})[Number(planCId)]||{})[per]||{};
    return [e.id,e.n,..._colsCsv.map(c=>nd[c.key]||0),nd.rec||0,nd.niv||0].join(',');
  });
  const csv='sep=,\n'+'# PLANILLA - '+carga.m+' - GRADO '+carga.g+' - PERIODO '+per+'\n'
    +'# Notas de 0.0 a 5.0 en pasos de 0.1\n'+headers.join(',')+' \n'+rows.join('\n');
  const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});
  const link=document.createElement('a');link.href=URL.createObjectURL(blob);
  link.download='Planilla_'+carga.m.replace(/ /g,'_')+'_Grado'+carga.g+'_P'+per+'_'+db.anio+'.csv';
  link.click();
}
function cargarPlanillaCSV(inp){
  const f=inp.files[0];if(!f) return;
  const r=new FileReader();
  r.onload=ev=>{
    try{
      const allLines=ev.target.result.split(/\r?\n/).filter(l=>l.trim()&&!l.startsWith('#')&&!l.startsWith('sep='));
      if(!allLines.length){alert('Archivo vacío o sin datos válidos.');return;}
      // Buscar fila de encabezado (contiene ID o ESTUDIANTE)
      let hdrIdx=-1;
      for(let i=0;i<Math.min(allLines.length,6);i++){
        const lu=allLines[i].toUpperCase();
        if(lu.includes('ID_ESTUDIANTE')||lu.includes('ESTUDIANTE')||lu.includes('NOMBRE')){hdrIdx=i;break;}
      }
      if(hdrIdx===-1){alert('El archivo no tiene el formato correcto. Use el CSV descargado del sistema.');return;}
      const hdrCols=allLines[hdrIdx].split(',').map(c=>c.trim().toUpperCase().replace(/ *\([^)]*\)/g,'').trim());
      const _cfg=db.config||{};const _colsCsv2=_resolverColumnas(_cfg);
      // Construir mapa de columnas por nombre de encabezado
      const colMap={};
      hdrCols.forEach((h,i)=>{
        if(h==='ID_ESTUDIANTE'||h==='ID') colMap['id']=i;
        else if(h==='NOMBRE'||h==='ESTUDIANTE'||h.includes('ESTUDIANTE')||h.includes('NO EDITAR')) colMap['nombre']=i;
        else if(h.startsWith('RECUP')) colMap['rec']=i;
        else if(h.startsWith('NIVEL')) colMap['niv']=i;
        else _colsCsv2.forEach(col=>{const cn=(col.nom||'').toUpperCase();if(cn&&(h===cn||h.startsWith(cn.substring(0,Math.min(6,cn.length))))) colMap[col.key]=i;});
      });
      if(!('id' in colMap)&&!('nombre' in colMap)){alert('El archivo no tiene el formato correcto. Use el CSV descargado del sistema.');return;}
      const carga2=db.carga.find(x=>x.id===Number(planCId));
      if(!carga2){alert('Seleccione una asignatura primero.');return;}
      const per=Number(planPer);const cId=Number(planCId);
      const pv=v=>{const n=parseFloat(String(v||'').replace(',','.'));return isNaN(n)?0:Math.min(5,Math.max(0,n));};
      let importados=0;
      updDB(d=>{
        for(let i=hdrIdx+1;i<allLines.length;i++){
          const cols=allLines[i].split(',');
          if(cols.length<3) continue;
          const estId='id' in colMap?Number(cols[colMap['id']]):0;
          const nombre='nombre' in colMap?String(cols[colMap['nombre']]||'').trim().toUpperCase():'';
          let est=null;
          if(estId) est=d.ests.find(e=>e.id===estId&&e.g===carga2.g);
          if(!est&&nombre) est=d.ests.find(e=>e.g===carga2.g&&(e.n.toUpperCase()===nombre||e.n.toUpperCase().includes(nombre.substring(0,12))||nombre.includes(e.n.toUpperCase().substring(0,12))));
          if(!est) continue;
          if(!est.nts) est.nts={};if(!est.nts[cId]) est.nts[cId]={};if(!est.nts[cId][per]) est.nts[cId][per]={s:0,sb:0,h:0,rec:0,niv:0};
          if('rec' in colMap) est.nts[cId][per].rec=pv(cols[colMap['rec']]);
          if('niv' in colMap) est.nts[cId][per].niv=pv(cols[colMap['niv']]);
          _colsCsv2.forEach(col=>{if(col.key in colMap) est.nts[cId][per][col.key]=pv(cols[colMap[col.key]]);});
          importados++;
        }
        return d;
      });
      alert(importados>0?'✅ Planilla importada: '+importados+' estudiantes actualizados.':'⚠️ No se importó ningún estudiante. Verifique que el archivo corresponde al grado y asignatura seleccionados.');
      inp.value='';renderApp();
    }catch(err){alert('Error al leer el archivo: '+err.message);}
  };r.readAsText(f,'UTF-8');
}

function guardarPlanilla(){
  const numPend=Object.keys(_notasPendientes).length;
  if(numPend===0){alert('ℹ️ No hay notas pendientes por guardar.');return;}
  // 1. Aplicar notas pendientes en la BD local (updDB → saveDB → schedules pushDB)
  _aplicarNotasPendientesEnDB();
  // 2. Limpiar indicador de pendientes
  _actualizarIndicadorPendientes();
  // 3. Re-renderizar la planilla para que NOTA, DEFINITIVA y columnas del administrador reflejen los nuevos valores
  renderApp();
  // 4. Forzar push inmediato a la nube (sin esperar el debounce de 350ms)
  _pushDB();
  alert('✅ '+numPend+' nota(s) guardadas correctamente.\nNOTA, DEFINITIVA y columnas adicionales actualizadas.');
}



function saveNota(estId,campo,valor){
  const numVal=Math.min(5,Math.max(0,parseFloat(valor)||0));
  updDB(d=>{
    const idx=d.ests.findIndex(x=>x.id===estId);if(idx===-1) return d;
    const e={...d.ests[idx]};const nts=JSON.parse(JSON.stringify(e.nts||{}));
    const cId=Number(planCId);const per=Number(planPer);
    if(!nts[cId]) nts[cId]={};if(!nts[cId][per]) nts[cId][per]={s:0,sb:0,h:0,rec:0,niv:0};
    nts[cId][per][campo]=numVal;d.ests[idx]={...e,nts};return d;
  });
  const e=db.ests.find(x=>x.id===estId);
  if(e){
    const cId=Number(planCId),per=Number(planPer);
    const nd=(e.nts[cId]||{})[per]||{s:0,sb:0,h:0,rec:0,niv:0};
    const base=_baseNota(nd,db.config||{});
    const def=(base<3&&(nd.rec||0)>0)?nd.rec:base;const defF=(per===_getNumPer()&&(nd.niv||0)>0)?nd.niv:def;
    const bEl=document.getElementById(`base-${estId}`);const dEl=document.getElementById(`def-${estId}`);
    if(bEl){bEl.textContent=base.toFixed(1);bEl.style.color=base<3?'#c0392b':'#333';}
    if(dEl){dEl.textContent=defF.toFixed(1);dEl.style.color=colorNota(defF);}
  }
}

