function verConsolidadoGeneral(){
  const grado=document.getElementById('infGradoGen')?.value||'';
  const per=Number(document.getElementById('infPerGen')?.value||1);
  const mats=db.carga.filter(x=>x.g===grado);
  const ests=db.ests.filter(x=>x.g===grado).sort((a,b)=>a.n.localeCompare(b.n));
  const wrap=document.getElementById('consolidadoGeneralWrap');
  if(!mats.length||!ests.length){if(wrap) wrap.innerHTML=`<div class="card"><p class="empty">No hay datos para este grado.</p></div>`;return;}
  
  // Group by area
  const areas={};
  mats.forEach(m=>{const a=m.a||m.m;if(!areas[a]) areas[a]=[];areas[a].push(m);});
  
  const filas=ests.map(e=>{
    const notas=mats.map(m=>calcNotaDef(e.nts,m.id,per));
    const prom=notas.length?parseFloat((notas.reduce((a,b)=>a+b,0)/notas.length).toFixed(2)):0;
    const apAreas=mats.filter(m=>calcNotaDef(e.nts,m.id,per)<3).length;
    return{e,notas,prom,apAreas};
  });
  const total=filas.length;
  const aprobados=filas.filter(f=>f.prom>=3).length;
  const promG=total?parseFloat((filas.reduce((a,f)=>a+f.prom,0)/total).toFixed(2)):0;
  
  // Stats per subject
  const matStats=mats.map(m=>{
    const ns=ests.map(e=>calcNotaDef(e.nts,m.id,per));
    const prom=ns.length?(ns.reduce((a,b)=>a+b,0)/ns.length).toFixed(2):'0.00';
    const perd=ns.filter(n=>n<3).length;
    return{m,prom,perd,total:ns.length};
  });
  
  const statsHtml=`<div class="flex-gap" style="margin-bottom:15px">
    <span class="stat-box" style="background:#27ae60">✅ Aprob.: <b>${aprobados}</b></span>
    <span class="stat-box" style="background:#c0392b">❌ Reprob.: <b>${total-aprobados}</b></span>
    <span class="stat-box" style="background:#003366">📊 Prom. Grado: <b>${promG}</b></span>
    <span class="stat-box" style="background:#16a085">📚 Asignaturas: <b>${mats.length}</b></span>
  </div>
  <div style="margin-bottom:12px;padding:8px;background:#f0f4f8;border-radius:6px;font-size:0.78rem">
    <b>Promedios por asignatura (P${per}):</b> ${matStats.map(s=>`<span style="margin:0 4px;color:${parseFloat(s.prom)<3?'#c0392b':'#1a7531'}">${s.m.m}: <b>${s.prom}</b>(${s.perd} perd.)</span>`).join('|')}
  </div>`;
  
  const matHeads=mats.map(m=>`<th title="${m.m} — ${m.dn}" style="font-size:0.68rem">${m.m.substring(0,7)}<br><small style="font-weight:normal;font-size:0.6rem">${(m.a||'').substring(0,6)}</small></th>`).join('');
  const rows=filas.map((f,i)=>{
    const notasCells=f.notas.map(n=>`<td style="color:${n<3?'#c0392b':'#333'};font-size:0.79rem">${n.toFixed(1)}</td>`).join('');
    const pu=puestoEst(f.e.id,grado);
    const promBg=f.prom<3?'#fdecea':'#eafaf1';const promCol=f.prom<3?'#c0392b':'#1a7531';
    return `<tr><td>${i+1}</td><td style="text-align:left;font-size:0.79rem">${f.e.n}</td>${notasCells}
      <td style="font-weight:bold;background:${promBg};color:${promCol}">${f.prom.toFixed(2)}</td>
      <td style="font-weight:bold;color:${f.apAreas>0?'#c0392b':'#27ae60'}">${f.apAreas}</td>
      <td style="font-weight:bold;color:#6c3483">${pu}°</td></tr>`;
  }).join('');
  
  if(wrap) wrap.innerHTML=`<div class="card">
    <h4 class="card-title">Consolidado General — Grado ${grado} — Periodo ${per} — Todas las áreas</h4>
    ${statsHtml}
    <div class="over"><table>
      <thead><tr><th>#</th><th style="text-align:left;min-width:170px">Estudiante</th>${matHeads}<th style="background:#1a5276">PROM</th><th style="background:#c0392b;font-size:0.72rem">PERD.</th><th style="background:#6c3483">PUESTO</th></tr></thead>
      <tbody>${rows}</tbody></table></div>
    <div class="scale-box" style="margin-top:8px;font-size:0.75rem">BAJO (0.0-2.9) | BÁSICO (3.0-3.9) | ALTO (4.0-4.6) | SUPERIOR (4.7-5.0)</div></div>`;
}

function pdfConsolidadoGeneral(){
  const grado=document.getElementById('infGradoGen')?.value||'';
  const per=Number(document.getElementById('infPerGen')?.value||1);
  const mats=db.carga.filter(x=>x.g===grado);
  const ests=db.ests.filter(x=>x.g===grado).sort((a,b)=>a.n.localeCompare(b.n));
  if(!ests.length){alert('Sin estudiantes.');return;}
  const doc=getPDF('l');
  doc.setFontSize(9);doc.setFont('helvetica','bold');doc.setTextColor(0,51,102);
  doc.text('CONSOLIDADO GENERAL — TODAS LAS ÁREAS',148,10,{align:'center'});
  doc.setFontSize(7.5);doc.setFont('helvetica','normal');doc.setTextColor(0);
  var _sh3=doc.splitTextToSize('Grado: '+grado+' | Periodo: '+per+' | Año: '+db.anio+' | Rector(a): '+db.rectora,270);doc.text(_sh3,148,16,{align:'center'});
  const head=[['#','ESTUDIANTE',...mats.map(m=>m.m.substring(0,7)),'PROM','ÁREAS PERD.','PUESTO']];
  const body=ests.map((e,i)=>{
    const notas=mats.map(m=>calcNotaDef(e.nts,m.id,per).toFixed(1));
    const prom=notas.length?(notas.reduce((a,b)=>a+parseFloat(b),0)/notas.length).toFixed(2):'0.00';
    const perd=mats.filter(m=>calcNotaDef(e.nts,m.id,per)<3).length;
    return[i+1,e.n,...notas,prom,perd,puestoEst(e.id,grado)+'°'];
  });
  doc.autoTable({head,body,startY:20,styles:{fontSize:6.5,cellPadding:1.5,halign:'center'},
    headStyles:{fillColor:[0,51,102],textColor:255,fontStyle:'bold'},
    columnStyles:{1:{halign:'left',cellWidth:50}},
    didParseCell:d=>{if(d.section==='body'&&d.column.index>1){const v=parseFloat(d.cell.raw);if(!isNaN(v)&&v<3) d.cell.styles.textColor=[192,57,43];}}
  });
  const fyC=doc.lastAutoTable.finalY+4;
  doc.setFontSize(6);doc.setFont('helvetica','normal');
  const docInfo=mats.map(m=>m.m+': '+m.dn).join(' | ');
  var _docI=doc.splitTextToSize('Docentes: '+docInfo,275);doc.text(_docI,14,fyC);
  doc.save('ConsolidadoGeneral_'+grado+'_P'+per+'_'+db.anio+'.pdf');
}

// ============================================================
// ESTADÍSTICAS POR GRADO (ADMIN)
// ============================================================
function verEstadisticasGrado(){
  const grado=document.getElementById('infGradoEst')?.value||'';
  const per=Number(document.getElementById('infPerEst')?.value||1);
  const mats=db.carga.filter(x=>x.g===grado);
  const ests=db.ests.filter(x=>x.g===grado);
  const wrap=document.getElementById('estadisticasWrap');
  if(!mats.length||!ests.length){if(wrap) wrap.innerHTML=`<div class="card"><p class="empty">Sin datos.</p></div>`;return;}
  const total=ests.length;
  
  // Per subject stats
  const matStats=mats.map(m=>{
    const ns=ests.map(e=>calcNotaDef(e.nts,m.id,per));
    const prom=ns.reduce((a,b)=>a+b,0)/ns.length||0;
    const aprobados=ns.filter(n=>n>=3).length;
    const sup=ns.filter(n=>n>=4.7).length;
    const alto=ns.filter(n=>n>=4&&n<4.7).length;
    const basico=ns.filter(n=>n>=3&&n<4).length;
    const bajo=ns.filter(n=>n<3).length;
    return{m:m.m,dn:m.dn,prom:prom.toFixed(2),aprobados,sup,alto,basico,bajo,total:ns.length};
  }).sort((a,b)=>parseFloat(a.prom)-parseFloat(b.prom));
  
  const rows=matStats.map(s=>{
    const pct=Math.round(s.aprobados/s.total*100);
    const barW=pct;
    const col=pct>=80?'#27ae60':pct>=60?'#e67e22':'#c0392b';
    return `<tr>
      <td style="text-align:left;font-weight:500">${s.m}</td>
      <td style="text-align:left;font-size:0.75rem">${s.dn}</td>
      <td style="font-weight:bold;color:${parseFloat(s.prom)<3?'#c0392b':'#1a7531'}">${s.prom}</td>
      <td><div style="background:#eee;border-radius:4px;width:100%;height:16px;position:relative"><div style="background:${col};width:${barW}%;height:100%;border-radius:4px;transition:width .3s"></div><span style="position:absolute;right:4px;top:0;font-size:0.7rem;font-weight:bold;line-height:16px;color:#333">${pct}%</span></div></td>
      <td style="color:#1a7531"><b>${s.aprobados}</b></td>
      <td style="color:#c0392b"><b>${s.bajo}</b></td>
      <td style="font-size:0.75rem">${s.sup}S|${s.alto}A|${s.basico}B|${s.bajo}I</td>
    </tr>`;
  }).join('');
  
  // Global stats
  const promsEst=ests.map(e=>{
    const ns=mats.map(m=>calcNotaDef(e.nts,m.id,per));
    return ns.length?ns.reduce((a,b)=>a+b,0)/ns.length:0;
  });
  const promGlobal=(promsEst.reduce((a,b)=>a+b,0)/promsEst.length||0).toFixed(2);
  const aprobadosGlobal=promsEst.filter(p=>p>=3).length;
  
  if(wrap) wrap.innerHTML=`<div class="card">
    <h4 class="card-title">Estadísticas — Grado ${grado} — Periodo ${per}</h4>
    <div class="flex-gap" style="margin-bottom:15px">
      <span class="stat-box" style="background:#003366">👥 Total Est.: <b>${total}</b></span>
      <span class="stat-box" style="background:#27ae60">✅ Aprobados: <b>${aprobadosGlobal}</b> (${Math.round(aprobadosGlobal/total*100)}%)</span>
      <span class="stat-box" style="background:#c0392b">❌ En riesgo: <b>${total-aprobadosGlobal}</b></span>
      <span class="stat-box" style="background:#16a085">📊 Prom. Global: <b>${promGlobal}</b></span>
    </div>
    <div class="over"><table>
      <thead><tr><th style="text-align:left">Asignatura</th><th style="text-align:left">Docente</th><th>Promedio</th><th style="min-width:120px">Aprobación</th><th>Aprobados</th><th>Bajo</th><th>Distribución</th></tr></thead>
      <tbody>${rows}</tbody></table></div>
    <div style="margin-top:10px;font-size:0.74rem;color:#666">S=Superior|A=Alto|B=Básico|I=Bajo</div>
  </div>`;
}

function pdfEstadisticasGrado(){
  const grado=document.getElementById('infGradoEst')?.value||'';
  const per=Number(document.getElementById('infPerEst')?.value||1);
  const mats=db.carga.filter(x=>x.g===grado);
  const ests=db.ests.filter(x=>x.g===grado);
  if(!ests.length){alert('Sin datos.');return;}
  const doc=getPDF('l');
  doc.setFontSize(9);doc.setFont('helvetica','bold');doc.setTextColor(0,51,102);
  doc.text('ESTADÍSTICAS ACADÉMICAS — TODAS LAS ÁREAS',148,10,{align:'center'});
  doc.setFontSize(7.5);doc.setFont('helvetica','normal');doc.setTextColor(0);
  var _sh4=doc.splitTextToSize('Grado: '+grado+' | Periodo: '+per+' | Año: '+db.anio,270);doc.text(_sh4,148,16,{align:'center'});
  const matStats=mats.map(m=>{
    const ns=ests.map(e=>calcNotaDef(e.nts,m.id,per));
    const prom=(ns.reduce((a,b)=>a+b,0)/ns.length||0).toFixed(2);
    const aprobados=ns.filter(n=>n>=3).length;
    const pct=Math.round(aprobados/ns.length*100);
    const sup=ns.filter(n=>n>=4.7).length,alto=ns.filter(n=>n>=4&&n<4.7).length;
    const basico=ns.filter(n=>n>=3&&n<4).length,bajo=ns.filter(n=>n<3).length;
    return[m.m,m.dn,prom,aprobados+' ('+pct+'%)',sup,alto,basico,bajo];
  }).sort((a,b)=>parseFloat(a[2])-parseFloat(b[2]));
  doc.autoTable({
    head:[['Asignatura','Docente','Promedio','Aprobados','Superior','Alto','Básico','Bajo']],
    body:matStats,startY:20,
    styles:{fontSize:7,cellPadding:2,halign:'center'},
    headStyles:{fillColor:[0,51,102],textColor:255,fontStyle:'bold'},
    columnStyles:{0:{halign:'left',cellWidth:45},1:{halign:'left',cellWidth:40}},
    didParseCell:d=>{if(d.section==='body'&&d.column.index===2){const v=parseFloat(d.cell.raw);if(!isNaN(v)&&v<3) d.cell.styles.textColor=[192,57,43];}}
  });
  doc.save('Estadisticas_'+grado+'_P'+per+'_'+db.anio+'.pdf');
}

