  const ests=db.ests.filter(x=>x.g===grado).sort((a,b)=>a.n.localeCompare(b.n));
  if(!ests.length){alert('Sin estudiantes.');return;}
  const doc=getPDF('l');
  doc.setFontSize(8);doc.setFont('helvetica','bold');
