// FUNCIÓN CENTRAL: generar boletines con descriptores y nombre de docente por asignatura
function _generarBoletinesPDF(grado,per,incluirResumenFinal){
  const mats=db.carga.filter(c=>c.g===grado);
  // Si hay override de estudiante individual, usarlo; si no, todos del grado
  const estsBase=window._boletinEstudiantesOverride||db.ests.filter(x=>x.g===grado);
  window._boletinEstudiantesOverride=null;
  const ests=estsBase.map(e=>{
    let s=0,n=0;mats.forEach(c=>{s+=calcNotaDef(e.nts,c.id,per);n++;});
    return{...e,promPer:n?s/n:0};
  }).sort((a,b)=>b.promPer-a.promPer);
  if(!ests.length){alert('No hay estudiantes.');return;}
  const infoG=db.grados.find(x=>x.n===grado)||{d:'SIN ASIGNAR',n:grado};
  // Tamaño OFICIO + plantilla seleccionada (clasico/compacto/moderno/formal)
  const doc=getPDF('p','oficio');
  const plantilla=window.boletinPlantilla||'clasico';
  // Banda de color superior según plantilla
  const _aplicaPlantillaPagina=()=>{
    if(plantilla==='moderno'){doc.setFillColor(0,51,102);doc.rect(0,0,216,8,'F');doc.setFillColor(241,196,15);doc.rect(0,8,216,2,'F');}
    else if(plantilla==='compacto'){doc.setDrawColor(0,51,102);doc.setLineWidth(1.2);doc.rect(6,6,204,318);}
    else if(plantilla==='formal'){doc.setDrawColor(0);doc.setLineWidth(0.4);doc.rect(8,8,200,314);}
  };
  _aplicaPlantillaPagina();
  // Hook para aplicar la plantilla en cada nueva página añadida
  const _origAddPage=doc.addPage.bind(doc);
  doc.addPage=function(){const r=_origAddPage();_aplicaPlantillaPagina();return r;};
  ests.forEach((e,idx)=>{
    if(idx>0) doc.addPage();
    // ──── ENCABEZADO BOLETÍN (centrado entre escudos, sin desborde) ────
    const _escInst=db.logo||'';
    const _escCol=db.escudoColombia||window._ESCUDO_COL_B64||null;
    const _hY=6;
    // Escudo izquierdo: Colombia (18×20mm — oficial precargado)
    if(_escCol){try{doc.addImage(_escCol,'JPEG',10,_hY,18,20);}catch(_ec1){try{doc.addImage(_escCol,'PNG',10,_hY,18,20);}catch(_ec2){}}}
    // Escudo derecho: institución (18×20mm)
    if(_escInst){try{doc.addImage(_escInst,'JPEG',188,_hY,18,20);}catch(_e1){try{doc.addImage(_escInst,'PNG',188,_hY,18,20);}catch(_e2){}}}
    // Zona de texto: entre los dos escudos → de x=30 a x=186 = 156mm, centro=108
    const _hL2=30,_hR2=186,_hCX2=(_hL2+_hR2)/2,_hMW2=_hR2-_hL2-4;
    doc.setTextColor(0,51,102);
    doc.setFontSize(8);doc.setFont('helvetica','bold');
    var _r1L=doc.splitTextToSize('REPÚBLICA DE COLOMBIA',_hMW2);
    doc.text(_r1L,_hCX2,_hY+4,{align:'center'});
    const _depLabel=db.depto?'DEPARTAMENTO DE '+(db.depto).toUpperCase():(getROT2()||'');
    if(_depLabel){doc.setFontSize(7.5);var _depL=doc.splitTextToSize(_depLabel,_hMW2);doc.text(_depL,_hCX2,_hY+8,{align:'center'});}
    doc.setFontSize(10);doc.setFont('helvetica','bold');
    const _brot3=doc.splitTextToSize(getROT3()||(db.nombre||'INSTITUCIÓN EDUCATIVA'),_hMW2);
    doc.text(_brot3,_hCX2,_hY+13,{align:'center'});
    let _hNext=_hY+13+(_brot3.length*5);
    doc.setFontSize(7);doc.setFont('helvetica','normal');doc.setTextColor(40);
    if(getROT4()){const _r4=doc.splitTextToSize(getROT4(),_hMW2);doc.text(_r4,_hCX2,_hNext,{align:'center'});_hNext+=_r4.length*3.5;}
    if(getROT5()){const _r5=doc.splitTextToSize(getROT5(),_hMW2);doc.text(_r5,_hCX2,_hNext,{align:'center'});_hNext+=_r5.length*3.5;}
    if(getROT6()){const _r6=doc.splitTextToSize(getROT6(),_hMW2);doc.text(_r6,_hCX2,_hNext,{align:'center'});_hNext+=_r6.length*3.5;}
    doc.setFontSize(7);var _daneL=doc.splitTextToSize('Dane: '+(db.dane||'')+'  Nit: '+(db.nit||''),_hMW2);doc.text(_daneL,_hCX2,_hNext+1.5,{align:'center'});
    _hNext+=5;
    doc.setTextColor(0);doc.setLineWidth(0.5);doc.line(10,_hNext,206,_hNext);
    const tituloDoc=incluirResumenFinal?'INFORME FINAL DEL AÑO — EVALUACIÓN Y DESEMPEÑO ACADÉMICO':'INFORME DE EVALUACIÓN Y DESEMPEÑO ACADÉMICO';
    const _titY=_hNext+6;
    doc.setFontSize(11);doc.setFont('helvetica','bold');doc.setTextColor(0,51,102);
    const _titLines=doc.splitTextToSize(tituloDoc,_hMW2);
    doc.text(_titLines,_hCX2,_titY,{align:'center'});
    doc.setTextColor(0);
    const _tableStart=Math.max(52,_titY+(_titLines.length*5)+2);
    const pu=puestoEst(e.id,grado);
    // Márgenes optimizados: aprovecha todo el ancho disponible de la hoja oficio
    const _lm=10,_rm=206,_tw=_rm-_lm;
    const _cx=(_lm+_rm)/2; // centro horizontal
    // ── Fila del estudiante ──
    doc.setFillColor(220,232,255);doc.rect(_lm,_tableStart-7,_tw,7,'F');
    doc.setFontSize(8.5);doc.setFont('helvetica','bold');doc.setTextColor(0,30,80);
    const _estLine=doc.splitTextToSize('ESTUDIANTE: '+e.n+'   AÑO: '+db.anio+'   GRADO: '+grado+'   PERIODO: '+per+'   PUESTO: '+pu+'°',_tw-4);
    var _estL=doc.splitTextToSize(_estLine,_tw-4);doc.text(_estL,_cx,_tableStart-1.5,{align:'center'});
    doc.setLineWidth(0.3);doc.rect(_lm,_tableStart-7,_tw,7);doc.setTextColor(0);
    // Solo columnas del periodo seleccionado
    const _esInicialBol=esGradoInicial(grado);
    const areas={};
    mats.forEach(m=>{const a=m.a||m.m;if(!areas[a]) areas[a]=[];areas[a].push(m);});
    // Cabecera: ÁREA | ASIGNATURA | INT.HOR. | DOCENTE | NOTA | NIVEL o DESEMPEÑO (transición)
    const tableHead=[['ÁREA','ASIGNATURA','I.H.','DOCENTE','NOTA P'+per,_esInicialBol?'DESEMPEÑO':'NIVEL']];
    const tableBody=[];
    Object.keys(areas).forEach(area=>{
      const asigs=areas[area];let promsArea=[];
      asigs.forEach((m,ii)=>{
        const notaPer=calcNotaDef(e.nts,m.id,per);
        const nivel=esc(notaPer);
        promsArea.push(notaPer);
        const ih=m.ih||m.horas||'';
        tableBody.push([ii===0?area:'', m.m, ih||'\u2014', m.dn, notaPer.toFixed(1), nivel]);
        // Descriptor para esta asignatura y nivel en este periodo
        if(String(per)!=='4'){
          const escN=escNorm(notaPer);
          const descs=db.descriptores.filter(d=>d.gra===grado&&String(d.per)===String(per)&&d.mat===m.m&&(d.niv||'')===(escN||''));
          descs.forEach(d=>{
            const _dt=(d.txt||'').replace(/[\u2018\u2019\uFFFD]/g,'').trim();tableBody.push(['~D~'+_dt,'','','','','']);
          });
        }
      });
    });
    doc.autoTable({
      head:tableHead,body:tableBody,startY:_tableStart,
      margin:{left:_lm,right:216-_rm},
      styles:{fontSize:7.5,cellPadding:0.5,overflow:'linebreak',minCellHeight:3.5},
      headStyles:{fillColor:[0,51,102],textColor:255,fontStyle:'bold',halign:'center',fontSize:7.5,cellPadding:0.6},
      columnStyles:{
        0:{fontStyle:'bold',cellWidth:33,halign:'left'},
        1:{cellWidth:54,halign:'left'},
        2:{halign:'center',cellWidth:8,fontSize:7},
        3:{cellWidth:40,halign:'left',fontSize:7},
        4:{halign:'center',cellWidth:15,fontStyle:'bold'},
        5:{halign:'center',cellWidth:46,fontStyle:'bold'}
      },
      didParseCell:data=>{
        if(data.section==='body'){
          const raw=data.row.raw;
          const nota=parseFloat(data.cell.raw);
          if(!isNaN(nota)&&nota<3&&nota>=0) data.cell.styles.textColor=[180,20,20];
          const isDesc=raw&&typeof raw[0]==='string'&&raw[0].startsWith('~D~');
          if(isDesc){
            data.cell.styles.fillColor=[255,253,220];
            data.cell.styles.textColor=[255,253,220];
            data.cell.text=[];
            if(data.column.index===0){
              const _dtxt=(raw[0]||'').replace('~D~','');
              try{
                const _dlines=data.doc.splitTextToSize('  >> '+_dtxt,_tw-4);
                data.cell.styles.minCellHeight=Math.max(4,_dlines.length*2.8+1.5);
              }catch(e){data.cell.styles.minCellHeight=8;}
            }
          }
          if(raw[1]&&typeof raw[1]==='string'&&raw[1].startsWith('\u2192')){
            data.cell.styles.fillColor=[230,240,255];data.cell.styles.fontStyle='bold';
          }
          // Para grados iniciales: fondo de color suave en columna DESEMPEÑO
          if(_esInicialBol&&data.column.index===5&&!isDesc){
            const notaN=parseFloat(raw[4]);
            if(!isNaN(notaN)){
              const bg=notaN>=4.7?[232,245,255]:notaN>=4.0?[232,255,240]:notaN>=3.0?[255,245,225]:[255,232,232];
              const txtClr=notaN>=4.7?[26,82,118]:notaN>=4.0?[39,100,60]:notaN>=3.0?[140,70,0]:[130,20,20];
              data.cell.styles.fillColor=bg;
              data.cell.styles.fontStyle='bold';
              data.cell.styles.textColor=txtClr;
              data.cell.styles.halign='left';
              data.cell.styles.minCellHeight=8;
              data.cell.styles.cellPadding={top:0.5,bottom:0.5,left:1.5,right:5.5};
            }
          }
        }
      },
      didDrawCell:data=>{
        if(data.section==='body'){
          const raw=data.row.raw;
          const isDesc=raw&&typeof raw[0]==='string'&&raw[0].startsWith('~D~');
          if(isDesc&&data.column.index===5){
            const txt=raw[0].replace('~D~','');
            doc.setFillColor(255,253,220);
            doc.rect(_lm,data.cell.y,_tw,data.cell.height,'F');
            doc.setDrawColor(210,200,140);doc.setLineWidth(0.15);
            doc.rect(_lm,data.cell.y,_tw,data.cell.height);
            doc.setFontSize(7.5);doc.setFont('helvetica','italic');doc.setTextColor(60,40,0);
            const lines=doc.splitTextToSize('  >> '+txt,_tw-4);
            doc.text(lines,_lm+2,data.cell.y+3.5);
            doc.setTextColor(0);doc.setFont('helvetica','normal');doc.setDrawColor(0);doc.setLineWidth(0.1);
          }
          // CARITA EMOJI para grados de transicion / preescolar (ajustada a la celda)
          if(_esInicialBol&&!isDesc&&data.column.index===5){
            const notaN=parseFloat(raw[4]);
            if(!isNaN(notaN)){
              // Radio máximo: cabe dentro de la celda sin desbordar
              const _maxR=Math.min(2.5,(data.cell.height/2)-0.8,2.5);
              const r=Math.max(1.2,_maxR);
              // Centro: anclado al borde derecho de la celda con margen
              const cx=data.cell.x+data.cell.width-r-1.5;
              const cy=data.cell.y+data.cell.height/2;
              // Verificar que el círculo no salga de la celda
              const _maxCx=data.cell.x+data.cell.width-r-0.5;
              const _minCx=data.cell.x+r+0.5;
              const _fx=Math.min(_maxCx,Math.max(_minCx,cx));
              const _fy=cy;
              const clr=notaN>=4.7?[26,82,118]:notaN>=4.0?[39,174,96]:notaN>=3.0?[230,126,34]:[192,57,43];
              doc.setFillColor(clr[0],clr[1],clr[2]);
              doc.circle(_fx,_fy,r,'F');
              doc.setFillColor(255,255,255);
              const _e=r*0.37;const _ey=_fy-r*0.28;
              doc.circle(_fx-r*0.37,_ey,_e*0.42,'F');
              doc.circle(_fx+r*0.37,_ey,_e*0.42,'F');
              doc.setDrawColor(255,255,255);doc.setLineWidth(r*0.18);
              const _my=_fy+r*0.18;const _mw=r*0.35;
              if(notaN>=4.0){
                doc.line(_fx-_mw,_my,_fx,_my+r*0.35);doc.line(_fx,_my+r*0.35,_fx+_mw,_my);
              }else if(notaN>=3.0){
                doc.line(_fx-_mw,_my+r*0.3,_fx+_mw,_my+r*0.3);
              }else{
                doc.line(_fx-_mw,_my+r*0.35,_fx,_my);doc.line(_fx,_my,_fx+_mw,_my+r*0.35);
              }
              doc.setDrawColor(0);doc.setLineWidth(0.1);doc.setFillColor(0);
            }
          }
        }
      }
    });
    let fy=doc.lastAutoTable.finalY+1;
    // ── Promedios por periodo del estudiante y promedio del curso ──
    const perProms=[1,2,3,4].map(p=>calcPromedioEstPer(e.id,grado,p));
    const promAnualEst=parseFloat((perProms.reduce((a,b)=>a+b,0)/4).toFixed(2));
    const promsGradoP=db.ests.filter(x=>x.g===grado).map(x=>calcPromedioEstPer(x.id,grado,per));
    const promCurso=promsGradoP.length?parseFloat((promsGradoP.reduce((a,b)=>a+b,0)/promsGradoP.length).toFixed(2)):0;
    doc.setFillColor(220,238,255);doc.rect(_lm,fy,_tw,6,'F');
    doc.setLineWidth(0.3);doc.rect(_lm,fy,_tw,6);
    doc.setFontSize(7.5);doc.setFont('helvetica','bold');doc.setTextColor(0,51,102);
    const pLabel=perProms.map((p,i)=>'P'+(i+1)+': '+p.toFixed(2)).join('   ');
    const _promTxt='PROMEDIOS:  '+pLabel+'   |   PROM. ANUAL: '+promAnualEst.toFixed(2)+'   PROM. CURSO P'+per+': '+promCurso.toFixed(2);
    const _promLines=doc.splitTextToSize(_promTxt,_tw-4);
    doc.text(_promLines,_cx,fy+4.2,{align:'center'});
    doc.setTextColor(0);fy+=8;
    // Usar áreas del periodo si es boletin por periodo, o anual si es informe final
    const areasPerd=incluirResumenFinal?getAreasPerdidas(e.id,grado):getAreasPerdidasPeriodo(e.id,grado,per);
    if(areasPerd.length>0){
      doc.setFontSize(9);doc.setFont('helvetica','bold');
      const lblAreas=incluirResumenFinal?'BAJO DESEMPEÑO ANUAL: ':'BAJO DESEMPEÑO P'+per+': ';
      const _areasTxt=lblAreas+areasPerd.join(', ');
      const _areasWrapW=_tw-16;
      const _areasLines=doc.splitTextToSize(_areasTxt,_areasWrapW);
      const _areasH=Math.max(14,_areasLines.length*5.5+8);
      // Verificar si cabe en la página actual, si no, añadir nueva página
      if(fy+_areasH>doc.internal.pageSize.height-35){doc.addPage();fy=16;}
      doc.setFillColor(255,230,230);doc.rect(_lm,fy,_tw,_areasH,'F');
      doc.setDrawColor(192,57,43);doc.setLineWidth(0.3);doc.rect(_lm,fy,_tw,_areasH);
      doc.setTextColor(192,57,43);
      doc.text(_areasLines,_lm+8,fy+6);
      doc.setTextColor(0);fy+=_areasH+2;
    }
    if(incluirResumenFinal){
      const promAnioGral=calcPromedioEst(e.id,grado);
      const estadoFinal=areasPerd.length===0?'APROBADO(A)':areasPerd.length<=2?'APROBADO(A) CON ÁREAS POR NIVELAR':'REPROBADO(A)';
      doc.setFillColor(240,246,255);doc.rect(_lm,fy,_tw,7,'F');doc.setLineWidth(0.3);doc.rect(_lm,fy,_tw,7);
      doc.setFontSize(8.5);doc.setFont('helvetica','bold');
      const _estFinTxt='PROMEDIO GENERAL: '+promAnioGral.toFixed(2)+'   ESTADO FINAL: '+estadoFinal+' (Áreas perd.: '+areasPerd.length+')';
      const _estFinLines=doc.splitTextToSize(_estFinTxt,_tw-4);
      doc.text(_estFinLines,_cx,fy+5,{align:'center'});
      fy+=9;
    }
    doc.setFontSize(7.5);doc.setFont('helvetica','normal');
    doc.setFillColor(248,248,248);doc.rect(_lm,fy,_tw,6,'F');
    doc.setLineWidth(0.2);doc.rect(_lm,fy,_tw,6);
    doc.text('BAJO (0.0–2.9)   |   BÁSICO (3.0–3.9)   |   ALTO (4.0–4.6)   |   SUPERIOR (4.7–5.0)',_cx,fy+4,{align:'center'});
    fy+=7;
    if(e.obsDirector){
      doc.setFontSize(8.5);doc.setFont('helvetica','bold');doc.text('OBSERVACIÓN DEL DIRECTOR DE GRUPO:',_lm,fy);fy+=5;
      doc.setFont('helvetica','normal');doc.setFontSize(8);
      const obsL=doc.splitTextToSize(e.obsDirector,_tw-4);doc.text(obsL,_lm,fy);fy+=obsL.length*4.5+2;
    }
    // ── Firmas: siempre al fondo sin conflicto ──
    const pageH=doc.internal.pageSize.height;
    // Si el contenido llega muy abajo, añadir nueva página para las firmas
    if(fy>pageH-32){doc.addPage();fy=16;}
    const firmaY=Math.max(fy+6,pageH-26);
    // Zona izquierda: Rector(a)  |  Zona derecha: Director(a) de Grupo
    const _fMid=_cx;
    const _fL1=_lm+6,_fL2=_fMid-12,_fLcx=(_fL1+_fL2)/2;
    const _fR1=_fMid+12,_fR2=_rm-6,_fRcx=(_fR1+_fR2)/2;
    // Firma digital del rector(a)
    if(db.firmaRectora){try{doc.addImage(db.firmaRectora,'PNG',_fLcx-18,firmaY-12,36,10);}catch(_fe){}}
    doc.setLineWidth(0.4);
    doc.line(_fL1,firmaY,_fL2,firmaY);
    doc.line(_fR1,firmaY,_fR2,firmaY);
    doc.setFontSize(8);doc.setFont('helvetica','bold');
    var _fLnm=doc.splitTextToSize((db.rectora||'RECTOR(A)').toUpperCase(),_fL2-_fL1-2);
    doc.text(_fLnm,_fLcx,firmaY+5,{align:'center'});
    var _fRnm=doc.splitTextToSize((infoG.d||'DIRECTOR DE GRUPO').toUpperCase(),_fR2-_fR1-2);
    doc.text(_fRnm,_fRcx,firmaY+5,{align:'center'});
    doc.setFont('helvetica','normal');doc.setFontSize(7.5);
    doc.text('RECTOR(A)',_fLcx,firmaY+10,{align:'center'});
    doc.text('DIRECTOR(A) DE GRUPO',_fRcx,firmaY+10,{align:'center'});
    addFooterPDF(doc);
  });
  doc.save(incluirResumenFinal?'InformeFinalAnio_'+grado+'_'+db.anio+'.pdf':'Boletines_'+grado+'_P'+per+'_'+db.anio+'.pdf');
}

function _getNivelEducativo(g){
  const gn=(g||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if(/transici|preescol|jardin|kinder/.test(gn)) return 'Preescolar';
  const m=gn.match(/\d+/);if(m){const n=parseInt(m[0]);if(n>=1&&n<=5)return 'Básica Primaria';if(n>=6&&n<=9)return 'Básica Secundaria';if(n>=10&&n<=11)return 'Media';}
  return 'Básica';
}
// Justificación manual de texto en jsPDF — más fiable que align:'justify' en v2.5.x
// Distribuye palabras de izquierda a derecha en cada línea (excepto la última).
function _justifyLines(doc,lines,x,y,w,lineH){
  // Usa posiciones absolutas calculadas desde x para evitar acumulación de error
  lines.forEach(function(line,i){
    const lineY=y+i*lineH;
    const isLast=(i===lines.length-1);
    if(isLast||line.trim()===''){doc.text(line,x,lineY);return;}
    const words=line.trim().split(/\s+/);
    if(words.length<=1){doc.text(line,x,lineY);return;}
    // Medir cada palabra individualmente (evita diferencias de kerning al concatenar)
    const widths=words.map(function(wd){return doc.getTextWidth(wd);});
    const totalTextW=widths.reduce(function(a,b){return a+b;},0);
    const safeW=w-1; // 1mm de margen de seguridad anti-overflow
    const gaps=words.length-1;
    const spaceW=(safeW-totalTextW)/gaps;
    // Si el espacio calculado es negativo o muy pequeño, fallback a left-align
    if(spaceW<0.5){doc.text(line,x,lineY);return;}
    // Posición absoluta de cada palabra (sin acumulación de error flotante)
    var usedW=0;
    words.forEach(function(word,j){
      var absX;
      if(j===0){absX=x;}
      else if(j===words.length-1){absX=x+safeW-widths[j];}
      else{absX=x+usedW+j*spaceW;}
      doc.text(word,absX,lineY);
      usedW+=widths[j];
    });
  });
}
function pdfCertificado(estId,tipo){
  const e=db.ests.find(x=>x.id===estId);if(!e) return;
  pdfCertificadoPersonalizado(e,tipo);
}
function pdfCertificadoPersonalizado(e,tipo){
  const hoy=new Date();
  const meses=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
  const dia=hoy.getDate();const mes=meses[hoy.getMonth()];const anioActual=hoy.getFullYear();
  const titulos={notas:'📋 Certificado de Calificaciones',estudios:'📄 Certificado de Estudios',matriculado:'📄 Certificado de Estudios Actuales (Matriculado)',cursado:'📄 Certificado de Estudios Año Cursado'};
  const esMatriculado=tipo==='matriculado';const esNotas=tipo==='notas';
  const dialogo=`<div id="certModalOverlay" style="position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.6);z-index:10000;display:flex;align-items:center;justify-content:center;">
  <div style="background:#fff;border-radius:10px;padding:22px;max-width:620px;width:96%;max-height:93vh;overflow-y:auto;box-shadow:0 8px 32px rgba(0,0,0,0.35)">
    <h3 style="color:#003366;margin-bottom:4px;font-size:1.05rem">${titulos[tipo]||'Certificado'}</h3>
    <p style="font-size:0.79rem;color:#666;margin-bottom:14px">Complete los datos — los campos pre-llenados provienen de la configuración institucional.</p>
    <div class="grid2" style="gap:10px;margin-bottom:10px">
      <div><label class="lbl">Nombre del estudiante</label><input id="cNombre" value="${e.n}" style="width:100%"></div>
      <div><label class="lbl">Tipo de Documento</label><select id="cTipoDoc" style="width:100%">
        <option value="T.I.">T.I. — Tarjeta de Identidad</option>
        <option value="C.C.">C.C. — Cédula de Ciudadanía</option>
        <option value="R.C.">R.C. — Registro Civil</option>
        <option value="C.E.">C.E. — Cédula de Extranjería</option>
        <option value="PEP">PEP — Permiso Especial de Permanencia</option>
      </select></div>
      <div><label class="lbl">Número de Documento</label><input id="cNumDoc" value="${e.ti||e.cc||''}" placeholder="No. de documento" style="width:100%"></div>
      <div><label class="lbl">Ciudad de expedición del doc.</label><input id="cCiudadExp" value="${db.municipio||''}" placeholder="Ciudad" style="width:100%"></div>
      <div><label class="lbl">Grado</label><input id="cGrado" value="${e.g}" style="width:100%"></div>
      <div><label class="lbl">Año lectivo</label><input id="cAnio" value="${db.anio}" style="width:100%"></div>
      <div><label class="lbl">Jornada</label><select id="cJornada" style="width:100%">
        ${['Única','Mañana','Tarde','Nocturna','Completa'].map(j=>`<option value="${j}"${(db.jornada||'Mañana')===j?' selected':''}>${j}</option>`).join('')}
      </select></div>
      <div><label class="lbl">Calendario</label><select id="cCalendario" style="width:100%">
        <option value="A">Calendario A</option><option value="B">Calendario B</option>
      </select></div>
      <div><label class="lbl">Carácter</label><select id="cCaracter" style="width:100%">
        <option value="Oficial">Oficial</option><option value="Privado">Privado</option>
      </select></div>
      ${esMatriculado?`
      <div><label class="lbl">No. de Matrícula</label><input id="cMatricula" value="${e.matricula||''}" placeholder="Número de matrícula" style="width:100%"></div>
      <div><label class="lbl">No. de Folio</label><input id="cFolio" value="${e.folio||''}" placeholder="Número de folio" style="width:100%"></div>`:''}
      <div><label class="lbl">Municipio (expedición del cert.)</label><input id="cCiudad" value="${db.municipio||''}" style="width:100%"></div>
      <div><label class="lbl">Destino / Motivo</label><input id="cMotivo" value="a solicitud del interesado" style="width:100%"></div>
      <div><label class="lbl">Día</label><input id="cDia" value="${dia}" style="width:100%"></div>
      <div><label class="lbl">Mes</label><input id="cMes" value="${mes}" style="width:100%"></div>
      <div><label class="lbl">Año de expedición</label><input id="cAnioExp" value="${anioActual}" style="width:100%"></div>
      <div><label class="lbl">Nombre Rector(a)</label><input id="cRectora" value="${db.rectora||''}" style="width:100%"></div>
      <div style="grid-column:1/-1">
        <label style="display:flex;align-items:center;gap:8px;cursor:pointer;margin-bottom:8px;background:#f0f4f8;border:1px solid #d0dcea;border-radius:6px;padding:8px 12px">
          <input type="checkbox" id="cIncluirSecretario" checked style="width:16px;height:16px;cursor:pointer;accent-color:#003366"
            onchange="document.getElementById('cSecretarioWrap').style.display=this.checked?'':'none'">
          <span style="font-size:0.85rem;font-weight:600;color:#003366">Incluir firma de Secretario(a) Académico(a)</span>
        </label>
        <div id="cSecretarioWrap">
          <label class="lbl">Nombre Secretario(a) Académico(a)</label>
          <input id="cSecretario" value="${db.secretario||''}" placeholder="Nombre completo" style="width:100%">
        </div>
      </div>
    </div>
    <div class="flex-gap" style="justify-content:flex-end;margin-top:14px;gap:10px">
      <button class="btn btn-gray" onclick="document.getElementById('certModalOverlay').remove()">✕ Cancelar</button>
      <button class="btn btn-green" onclick="generarPdfCertPersonalizado('${tipo}','${e.id}')">📄 Generar PDF</button>
    </div>
  </div></div>`;
  document.body.insertAdjacentHTML('beforeend',dialogo);
}
function generarPdfCertPersonalizado(tipo,estId){
  const e=db.ests.find(x=>x.id===estId)||{nts:{}};
  const nombre=document.getElementById('cNombre')?.value||'';
  const tipoDoc=document.getElementById('cTipoDoc')?.value||'T.I.';
  const numDoc=document.getElementById('cNumDoc')?.value||'';
  const ciudadExp=document.getElementById('cCiudadExp')?.value||'';
  const grado=document.getElementById('cGrado')?.value||'';
  const anio=document.getElementById('cAnio')?.value||db.anio;
  const jornada=document.getElementById('cJornada')?.value||'';
  const calendario=document.getElementById('cCalendario')?.value||'A';
  const caracter=document.getElementById('cCaracter')?.value||'Oficial';
  const matricula=document.getElementById('cMatricula')?.value||'';
  const folio=document.getElementById('cFolio')?.value||'';
  const ciudad=document.getElementById('cCiudad')?.value||'';
  const motivo=document.getElementById('cMotivo')?.value||'a solicitud del interesado';
  const dia=document.getElementById('cDia')?.value||'';
  const mes=document.getElementById('cMes')?.value||'';
  const anioExp=document.getElementById('cAnioExp')?.value||'';
  const rectora=document.getElementById('cRectora')?.value||db.rectora||'';
  const secretario=document.getElementById('cSecretario')?.value||'';
  const incluirSecretario=document.getElementById('cIncluirSecretario')?.checked!==false;
  document.getElementById('certModalOverlay')?.remove();
  if(incluirSecretario&&secretario) updDB(d=>{d.secretario=secretario;return d;});
  const nivel=_getNivelEducativo(grado);
  const instNombre=_cleanInstName((db.nombre||(db.corregimiento?'Institución Educativa de '+db.corregimiento:'Institución Educativa')).toUpperCase());
  const titPDF={notas:'CERTIFICADO DE CALIFICACIONES',estudios:'CERTIFICADO DE ESTUDIOS',matriculado:'CERTIFICADO DE ESTUDIOS ACTUALES',cursado:'CERTIFICADO DE ESTUDIOS AÑO CURSADO'};
  const doc=getPDF('p','oficio');
  const PW=doc.internal.pageSize.width;const PH=doc.internal.pageSize.height;
  // Márgenes: MX=margen lateral, MW=ancho útil de texto, FOOTER_SAFE=espacio reservado para pie de página y firmas
  // MW reducido 4 mm adicionales (safety buffer) para compensar tildes/ñ que jsPDF subestima
  const MX=18;const MW=PW-50;const FOOTER_SAFE=50;
  // Helper: verifica si cabe contenido de `altura` mm; si no, agrega página nueva
  function _ckPage(altura){if(y+altura>PH-FOOTER_SAFE){doc.addPage();y=20;}}
  const startY=addHeaderRot(doc,titPDF[tipo]||'CERTIFICADO','Ley 115 de 1994 — Decreto 1075 de 2015',8);
  let y=startY+6;
  // DANE / NIT / Resolución bajo el título
  doc.setFontSize(7.5);doc.setFont('helvetica','normal');doc.setTextColor(70);
  const daneNit=[db.dane?'DANE: '+db.dane:'',db.nit?'NIT: '+db.nit:''].filter(Boolean).join('   |   ');
  if(daneNit){_ckPage(6);var _daneCK=doc.splitTextToSize(daneNit,MW);doc.text(_daneCK,PW/2,y,{align:'center'});y+=5;}
  if(db.resolucion){
    const resTit=caracter==='Privado'?'Licencia de Funcionamiento y Aprobación Oficial':'Resolución de Aprobación';
    const rL=doc.splitTextToSize(resTit+': '+db.resolucion,MW);
    _ckPage(rL.length*4+4);doc.text(rL,PW/2,y,{align:'center'});y+=rL.length*4+2;
  }
  doc.setTextColor(0);doc.setLineWidth(0.3);_ckPage(12);doc.line(MX,y,PW-MX,y);y+=8;
  // Encabezado legal formal
  doc.setFontSize(9);doc.setFont('helvetica','bold');
  const encabTxt=incluirSecretario
    ?'EL SUSCRITO RECTOR(A) Y SECRETARIO(A) DE LA INSTITUCIÓN EDUCATIVA '+instNombre
    :'EL SUSCRITO RECTOR(A) DE LA INSTITUCIÓN EDUCATIVA '+instNombre;
  const encL=doc.splitTextToSize(encabTxt,MW);
  _ckPage(encL.length*5.5+16);doc.text(encL,PW/2,y,{align:'center'});y+=encL.length*5.5+5;
  doc.text(incluirSecretario?'CERTIFICAN:':'CERTIFICA:',PW/2,y,{align:'center'});y+=10;
  doc.setFont('helvetica','normal');doc.setFontSize(9);
  const docExp=ciudadExp?' expedido(a) en '+ciudadExp:'';
  if(tipo==='notas'){
    // Certificado de Calificaciones
    const txt=`Que el(la) estudiante ${nombre}, identificado(a) con ${tipoDoc} No. ${numDoc}${docExp}, cursó en este establecimiento educativo los estudios correspondientes al GRADO ${grado} de Educación ${nivel} durante el año lectivo ${anio}, obteniendo las siguientes calificaciones definitivas en las áreas y asignaturas del plan de estudios vigente:`;
    const tL=doc.splitTextToSize(txt,MW);_ckPage(tL.length*4.2+8);_justifyLines(doc,tL,MX,y,MW,4.2);y+=tL.length*4.2+6;
    // Tabla de notas con columna Desempeño Nacional
    const mats=db.carga.filter(c=>c.g===grado);
    const _np=_getNumPer();
    const _pHd=Array.from({length:_np},(_,i)=>'P'+(i+1));
    const head=[['ÁREA / ASIGNATURA','I.H.',..._pHd,'PROM','DESEMPEÑO']];
    const body=mats.map(m=>{
      const ns=Array.from({length:_np},(_,i)=>calcNotaDef(e.nts,m.id,i+1));
      const prom=_np>0?ns.reduce((a,b)=>a+b,0)/_np:0;
      const dq=notaACualitativo(prom);
      const dLabel={'S':'Superior','A':'Alto','B':'Básico','D':'Bajo'}[dq.letra]||'—';
      return[m.m,m.ih||'—',...ns.map(n=>n>0?n.toFixed(1):'—'),prom>0?prom.toFixed(2):'—',dLabel];
    });
    doc.autoTable({
      head,body,startY:y,
      styles:{fontSize:7.5,halign:'center',cellPadding:1.5,overflow:'linebreak'},
      headStyles:{fillColor:[0,51,102],textColor:255,fontStyle:'bold'},
      columnStyles:{0:{halign:'left',cellWidth:52},1:{cellWidth:9}},
      theme:'grid',
      margin:{left:MX,right:MX}
    });
    y=doc.lastAutoTable.finalY+8;
    // Resultado definitivo
    const cfg=db.config||{};const eb=cfg.escalaB||3.0;
    const promsAll=mats.map(m=>{const ns=Array.from({length:_np},(_,i)=>calcNotaDef(e.nts,m.id,i+1));return _np>0?ns.reduce((a,b)=>a+b,0)/_np:0;});
    const promGen=promsAll.length?promsAll.reduce((a,b)=>a+b,0)/promsAll.length:0;
    const aprobado=promGen>=eb;
    _ckPage(52);
    doc.setFont('helvetica','bold');doc.setFontSize(8);
    const resT=`RESULTADO DEFINITIVO: El(La) estudiante ${nombre} ${aprobado?'APROBÓ':'REPROBÓ'} el grado ${grado} de conformidad con los criterios de evaluación y promoción institucional establecidos en el Sistema Institucional de Evaluación de Estudiantes (SIEE), bajo los lineamientos del Decreto 1075 de 2015.`;
    const resL=doc.splitTextToSize(resT,MW-8);_justifyLines(doc,resL,MX,y,MW-8,4.2);y+=resL.length*4.2+6;
    // Escala valorativa nacional (dinámica desde db.config)
    const es=cfg.escalaS||4.7;const ea=cfg.escalaA||4.0;
    _ckPage(32);
    doc.setFont('helvetica','bold');doc.setFontSize(8);
    const escTitL=doc.splitTextToSize('ESCALA VALORATIVA NACIONAL (Decreto 1290 de 2009):',MW);
    var _escT=doc.splitTextToSize(escTitL,MW);doc.text(_escT,MX,y);y+=_escT.length*4.5+2;
    doc.setFont('helvetica','normal');doc.setFontSize(8);
    var _ds=doc.splitTextToSize(`• Desempeño Superior: ${es} a 5.0`,MW-4);doc.text(_ds,MX+4,y);y+=5;
    var _da=doc.splitTextToSize(`• Desempeño Alto: ${ea} a ${(es-0.1).toFixed(1)}`,MW-4);doc.text(_da,MX+4,y);y+=5;
    var _db=doc.splitTextToSize(`• Desempeño Básico: ${eb} a ${(ea-0.1).toFixed(1)}  (mínimo para aprobar)`,MW-4);doc.text(_db,MX+4,y);y+=5;
    var _dbr=doc.splitTextToSize(`• Desempeño Bajo: 1.0 a ${(eb-0.1).toFixed(1)}`,MW-4);doc.text(_dbr,MX+4,y);y+=10;
  } else {
    // Certificado de Estudios (estudios / matriculado / cursado)
    let txt='';
    if(tipo==='matriculado'){
      txt=`Que el(la) estudiante ${nombre}, identificado(a) con ${tipoDoc} No. ${numDoc}${docExp}, se encuentra oficialmente matriculado(a) en este establecimiento educativo en el grado ${grado} de la Educación ${nivel} durante el año lectivo ${anio}${matricula?', bajo el número de matrícula '+matricula:''}${folio?', del folio '+folio:''}.`;
    } else if(tipo==='cursado'){
      txt=`Que el(la) estudiante ${nombre}, identificado(a) con ${tipoDoc} No. ${numDoc}${docExp}, cursó y aprobó el grado ${grado} de la Educación ${nivel} en este establecimiento educativo durante el año lectivo ${anio}.`;
    } else {
      txt=`Que el(la) estudiante ${nombre}, identificado(a) con ${tipoDoc} No. ${numDoc}${docExp}, cursó estudios en este establecimiento educativo en el grado ${grado} de la Educación ${nivel} durante el año lectivo ${anio}.`;
    }
    const tL=doc.splitTextToSize(txt,MW);_ckPage(tL.length*4.2+8);_justifyLines(doc,tL,MX,y,MW,4.2);y+=tL.length*4.2+6;
    const jorT=`De igual manera, se hace constar que la institución opera bajo la Jornada ${jornada}, Calendario ${calendario} y Carácter ${caracter}.`;
    const jL=doc.splitTextToSize(jorT,MW);_ckPage(jL.length*4.2+8);_justifyLines(doc,jL,MX,y,MW,4.2);y+=jL.length*4.2+6;
  }
  // Texto de constancia y lugar/fecha — siempre cabe en la misma página
  _ckPage(FOOTER_SAFE);
  doc.setFont('helvetica','normal');doc.setFontSize(8.5);
  const motT=`Para constancia se firma en ${ciudad}, a los ${dia} días del mes de ${mes} de ${anioExp}, con destino ${motivo}.`;
  const motL=doc.splitTextToSize(motT,MW);_justifyLines(doc,motL,MX,y,MW,4.2);y+=motL.length*4.2+14;
  // Líneas de firmas — se calculan a partir de y pero nunca salen del margen inferior
  const FIRMA_H=22; // altura total del bloque de firma (línea + nombre + cargo)
  const firmaY=Math.min(y,PH-FOOTER_SAFE+10);
  const fw=72;
  doc.setLineWidth(0.5);
  if(incluirSecretario){
    // Dos columnas: Rector | Secretario
    const c1=MX+6;const c2=PW/2+6;
    if(db.firmaRectora){try{doc.addImage(db.firmaRectora,'PNG',c1,firmaY-13,58,11);}catch(err){}}
    doc.line(c1,firmaY,c1+fw,firmaY);doc.line(c2,firmaY,c2+fw,firmaY);
    doc.setFontSize(7.5);doc.setFont('helvetica','bold');
    // Nombre rector — dividir si es muy largo
    const rNL=doc.splitTextToSize(rectora||'______________________',fw);
    doc.text(rNL,c1+fw/2,firmaY+5,{align:'center'});
    const sNL=doc.splitTextToSize(secretario||'______________________',fw);
    doc.text(sNL,c2+fw/2,firmaY+5,{align:'center'});
    doc.setFont('helvetica','normal');doc.setFontSize(7.5);
    doc.text('Rector(a)',c1+fw/2,firmaY+5+rNL.length*4+1,{align:'center'});
    doc.text('Secretario(a) Académico(a)',c2+fw/2,firmaY+5+sNL.length*4+1,{align:'center'});
  } else {
    // Una sola columna centrada: Rector
    const cx=PW/2;
    if(db.firmaRectora){try{doc.addImage(db.firmaRectora,'PNG',cx-30,firmaY-13,58,11);}catch(err){}}
    doc.line(cx-fw/2,firmaY,cx+fw/2,firmaY);
    doc.setFontSize(7.5);doc.setFont('helvetica','bold');
    const rNL=doc.splitTextToSize(rectora||'______________________',fw);
    doc.text(rNL,cx,firmaY+5,{align:'center'});
    doc.setFont('helvetica','normal');doc.setFontSize(7.5);
    doc.text('Rector(a)',cx,firmaY+5+rNL.length*4+1,{align:'center'});
  }
  addFooterPDF(doc);
  doc.save(`Certificado_${tipo}_${nombre.replace(/ /g,'_')}_${anio}.pdf`);
}

// ============================================================
// ACTAS / DOCUMENTOS — Con pestañas: Actas, Planes de Área, Material Estudiantes
// ============================================================
let actaTab='actas';
function htmlActas(){
  if(!db.actas) db.actas=[];if(!db.actasPdf) db.actasPdf=[];
  if(!db.planesArea) db.planesArea=[];if(!db.planeaciones) db.planeaciones=[];
  if(!db.materialEstudiantes) db.materialEstudiantes=[];
  return `<h3 class="sec-title">Módulo de Documentos y Actas</h3>
  <div class="tab-btns">
    <button class="tab-btn ${actaTab==='actas'?'active':''}" onclick="actaTab='actas';renderActaTab()">📋 Actas y Documentos</button>
    <button class="tab-btn ${actaTab==='planes'?'active':''}" onclick="actaTab='planes';renderActaTab()">📚 Planes de Área / Planeaciones</button>
    <button class="tab-btn ${actaTab==='material'?'active':''}" onclick="actaTab='material';renderActaTab()">🎒 Material para Estudiantes</button>
  </div>
  <div id="actaTabContenido"></div>`;
}

function renderActaTab(){
  // Re-render with correct tab
  const wrap=document.getElementById('actaTabContenido')||document.getElementById('contenido');
  // Refresh the tab buttons
  document.querySelectorAll('.tab-btn').forEach((b,i)=>{
    const tabs=['actas','planes','material'];
    b.classList.toggle('active',tabs[i]===actaTab);
  });
  let html='';
  if(actaTab==='actas') html=htmlActasPanel();
  else if(actaTab==='planes') html=htmlPlanesPanel();
  else if(actaTab==='material') html=htmlMaterialPanel();
  if(wrap) wrap.innerHTML=html;
}

// --- PANEL ACTAS ---
function htmlActasPanel(){
  const tiposActa=['Acta de Compromiso y Evaluación','Acta de Reunión con Padres de Familia','Acta de Inasistencias','Acta de Recuperación por Área','Acta de Nivelación por Área','Acta de Nivelación con Estudiantes','Citación a Padres / Cuidador(a)','Formato Personalizado'];
  const editActa=actaEditId!==null?db.actas[actaEditId]||null:null;
  const tiposOpts=tiposActa.map(t=>`<option${editActa&&editActa.tipo===t?' selected':''}>${t}</option>`).join('');
  const gradOpts=db.grados.map(g=>`<option value="${g.n}"${editActa&&editActa.grado===g.n?' selected':''}>${g.n}</option>`).join('');
  const actasRows=(db.actas||[]).map((a,i)=>`<tr>
    <td style="text-align:left">${a.tipo}</td><td>${a.fecha}</td><td>${a.grado||'General'}</td>
    <td><button class="btn-sm" style="background:#e67e22" onclick="editarActa(${i})">✎</button>
    <button class="btn-sm" style="background:#003366" onclick="pdfActa(${i})">📥</button>
    <button class="btn-sm" style="background:#c0392b" onclick="eliminarActa(${i})">🗑</button></td></tr>`).join('');
  const actasPdfRows=(db.actasPdf||[]).map((a,i)=>`<tr>
    <td style="text-align:left">${a.nombre}</td><td>${a.fecha}</td>
    <td><button class="btn-sm" style="background:#003366" onclick="descargarActaPdf(${i})">📥</button>
    <button class="btn-sm" style="background:#c0392b" onclick="eliminarActaPdf(${i})">🗑</button></td></tr>`).join('');
  return `<div class="card">
    <h4 class="card-title">${editActa?'✎ Editar Acta':'+ Crear Acta / Documento'}</h4>
    <div class="grid3" style="margin-bottom:10px">
      <div><label class="lbl">Tipo</label><select id="actaTipo">${tiposOpts}</select></div>
      <div><label class="lbl">Fecha</label><input type="date" id="actaFecha" value="${editActa?editActa.fecha:new Date().toISOString().split('T')[0]}"></div>
      <div><label class="lbl">Grado</label><select id="actaGrado"><option value="">General</option>${gradOpts}</select></div>
      <div><label class="lbl">Área</label><input id="actaArea" placeholder="Área" value="${editActa?editActa.area||'':''}"></div>
      <div><label class="lbl">Docente</label><input id="actaDocente" placeholder="Docente" value="${editActa?editActa.docente||'':sesion.n}"></div>
      <div><label class="lbl">Año</label><input id="actaAnio" value="${db.anio}" readonly></div>
    </div>
    <div style="margin-bottom:10px"><label class="lbl">Título</label><input id="actaTitulo" placeholder="Título del acta" value="${editActa?editActa.titulo||'':''}"></div>
    <div style="margin-bottom:10px"><label class="lbl">Contenido</label>
      <textarea id="actaContenido" style="height:120px;resize:vertical">${editActa?editActa.contenido||'':''}</textarea></div>
    <div style="margin-bottom:10px"><label class="lbl">Estudiantes Participantes (uno por línea)</label>
      <textarea id="actaEstudiantes" style="height:80px;resize:vertical">${editActa?editActa.estudiantes||'':''}</textarea></div>
    <div style="margin-bottom:10px"><label class="lbl">Compromisos / Temas</label>
      <textarea id="actaCompromisos" style="height:80px;resize:vertical">${editActa?editActa.compromisos||'':''}</textarea></div>
    <div style="margin-bottom:10px;border-top:1px solid #dde;padding-top:12px">
      <label class="lbl" style="color:#003366;font-weight:bold">👨‍👩‍👧 Acudientes / Padres de Familia</label>
      <p style="color:#666;font-size:0.8rem;margin:4px 0 8px">Ingrese un acudiente por línea con el formato: <b>NOMBRE COMPLETO | CC: DOCUMENTO | PARENTESCO</b></p>
      <textarea id="actaAcudientes" style="height:90px;resize:vertical;font-size:0.85rem" placeholder="Ejemplo:&#10;MARÍA LÓPEZ DE PÉREZ | CC: 12345678 | Madre&#10;CARLOS PÉREZ GARCÍA | CC: 87654321 | Padre">${editActa?editActa.acudientes||'':''}</textarea>
    </div>
    <div style="margin-bottom:10px">
      <label class="lbl" style="color:#003366;font-weight:bold">✍️ Firmas de Acudientes en el PDF</label>
      <p style="color:#666;font-size:0.8rem;margin:4px 0 8px">Ingrese los nombres que aparecerán con línea de firma en el PDF (uno por línea).</p>
      <textarea id="actaFirmasAcudientes" style="height:70px;resize:vertical;font-size:0.85rem" placeholder="Ejemplo:&#10;MARÍA LÓPEZ DE PÉREZ&#10;CARLOS PÉREZ GARCÍA">${editActa?editActa.firmasAcudientes||'':''}</textarea>
    </div>
    <div class="flex-gap">
      <button class="btn btn-green" onclick="guardarActa()">💾 Guardar</button>
      <button class="btn btn-blue" onclick="guardarActaYPdf()">📥 Guardar y PDF</button>
      ${editActa?`<button class="btn btn-gray" onclick="actaEditId=null;renderActaTab()">✕ Cancelar</button>`:''}
    </div>
  </div>
  ${actasRows?`<div class="card"><h4 class="card-title">Actas Creadas</h4>
    <div class="over"><table><thead><tr><th>Tipo</th><th>Fecha</th><th>Grado</th><th>Acc.</th></tr></thead><tbody>${actasRows}</tbody></table></div></div>`:''}
  <div class="card">
    <h4 class="card-title">📂 Cargar PDFs Externos (Actas diligenciadas)</h4>
    <div class="flex-gap" style="margin-bottom:10px;align-items:center">
      <input id="actaPdfNombre" placeholder="Nombre del documento" style="flex:1;max-width:300px">
      <button class="btn btn-gray" onclick="document.getElementById('fileActaPdf').click()">📁 Seleccionar PDF</button>
      <input type="file" id="fileActaPdf" accept=".pdf" style="display:none" onchange="cargarActaPdfArchivo(this)">
    </div>
    ${actasPdfRows?`<div class="over"><table><thead><tr><th>Documento</th><th>Fecha</th><th>Acc.</th></tr></thead><tbody>${actasPdfRows}</tbody></table></div>`:`<p class="empty">No hay PDFs cargados.</p>`}
  </div>`;
}

