function htmlEleccionesAdmin(){
  if(!db.elecciones) db.elecciones={};
  const anioE=db.anio;
  if(!db.elecciones[anioE]) db.elecciones[anioE]={personeros:[],contralores:[],votantes:[],votos:{personero:{},contralor:{},blancosP:0,blancosC:0}};
  const el=db.elecciones[anioE];
  const personeroRows=(el.personeros||[]).map((p,i)=>`<tr>
    <td>${p.foto?`<img src="${p.foto}" style="width:36px;height:44px;object-fit:cover;border-radius:3px">`:'—'}</td>
    <td style="text-align:left">${p.nombre}</td><td>${p.grado}</td>
    <td><button class="btn-sm" style="background:#c0392b" onclick="eliminarCandidato('personero',${i})">🗑</button></td></tr>`).join('');
  const contralorRows=(el.contralores||[]).map((p,i)=>`<tr>
    <td>${p.foto?`<img src="${p.foto}" style="width:36px;height:44px;object-fit:cover;border-radius:3px">`:'—'}</td>
    <td style="text-align:left">${p.nombre}</td><td>${p.grado}</td>
    <td><button class="btn-sm" style="background:#c0392b" onclick="eliminarCandidato('contralor',${i})">🗑</button></td></tr>`).join('');
  const totalVotos=Object.values(el.votos.personero||{}).reduce((a,b)=>a+b,0)+(el.votos.blancosP||0);
  return `<h3 class="sec-title">Módulo de Elecciones — Año ${anioE}</h3>
  <div class="tab-btns">
    <button class="tab-btn active" onclick="mostrarTabElecAdmin('config',this)">⚙️ Configurar</button>
    <button class="tab-btn" onclick="mostrarTabElecAdmin('resultados',this)">📊 Resultados</button>
    <button class="tab-btn" onclick="mostrarTabElecAdmin('votantes',this)">👥 Votantes</button>
  </div>
  <div style="margin-bottom:12px">
    <button class="btn btn-red" onclick="reiniciarElecciones()">🔄 Reiniciar Todo el Módulo de Elecciones</button>
  </div>
  <div id="elecAdminContenido">
    ${(()=>{const modoActual=(el.modoVotacion||'presencial');return `<div class="card" style="border-left:4px solid #e67e22;margin-bottom:16px">
      <h4 class="card-title" style="color:#e67e22">⚙️ Modo de Votación — Elecciones ${anioE}</h4>
      <p style="font-size:0.83rem;color:#555;margin-bottom:14px">Elija cómo se realizarán las elecciones. El cambio aplica de inmediato.</p>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
        <div onclick="establecerModoVotacion('online')" style="cursor:pointer;padding:14px;border-radius:12px;border:2.5px solid ${modoActual==='online'?'#27ae60':'#dde3f0'};background:${modoActual==='online'?'#eafaf1':'#f8f9fa'};transition:all .2s">
          <div style="font-size:1.7rem;margin-bottom:5px">💻</div>
          <div style="font-weight:800;font-size:0.88rem;color:${modoActual==='online'?'#1e8449':'#333'};margin-bottom:4px">Opción 1: 100% Online</div>
          <div style="font-size:0.75rem;color:#666;line-height:1.4">Cada estudiante vota desde su portal. La votación aparece automáticamente en su rol de Estudiante.</div>
          ${modoActual==='online'?'<div style="margin-top:8px;background:#d5f5e3;color:#1e8449;font-weight:bold;font-size:0.75rem;padding:3px 10px;border-radius:20px;display:inline-block">✅ ACTIVO</div>':''}
        </div>
        <div onclick="establecerModoVotacion('presencial')" style="cursor:pointer;padding:14px;border-radius:12px;border:2.5px solid ${modoActual==='presencial'?'#2980b9':'#dde3f0'};background:${modoActual==='presencial'?'#eaf4fb':'#f8f9fa'};transition:all .2s">
          <div style="font-size:1.7rem;margin-bottom:5px">🏫</div>
          <div style="font-weight:800;font-size:0.88rem;color:${modoActual==='presencial'?'#1a5276':'#333'};margin-bottom:4px">Opción 2: Presencial + Online</div>
          <div style="font-size:0.75rem;color:#666;line-height:1.4">Votación presencial con el módulo Elecciones. Los estudiantes <b>ausentes</b> pueden votar desde su portal.</div>
          ${modoActual==='presencial'?'<div style="margin-top:8px;background:#d6eaf8;color:#1a5276;font-weight:bold;font-size:0.75rem;padding:3px 10px;border-radius:20px;display:inline-block">✅ ACTIVO</div>':''}
        </div>
      </div>
    </div>`;})()}
    <div class="grid2" style="gap:15px">
      <div class="card">
        <h4 class="card-title">Candidatos a Personero</h4>
        <div class="grid2" style="margin-bottom:8px"><input id="pNombre" placeholder="Nombre"><input id="pGrado" placeholder="Grado"></div>
        <div class="flex-gap" style="margin-bottom:8px;align-items:center">
          <button class="btn btn-gray" onclick="document.getElementById('fileCandP').click()">📷 Foto</button>
          <input type="file" id="fileCandP" accept="image/*" style="display:none" onchange="fileToB64(this.files[0],b64=>window._fotoP=b64)">
        </div>
        <button class="btn btn-green" onclick="agregarCandidato('personero')">+ Agregar</button>
        ${el.personeros.length?`<div class="over" style="margin-top:10px"><table><thead><tr><th>Foto</th><th>Nombre</th><th>Grado</th><th>Del</th></tr></thead><tbody>${personeroRows}</tbody></table></div>`:'<p class="empty" style="padding:10px">Sin candidatos</p>'}
      </div>
      <div class="card">
        <h4 class="card-title">Candidatos a Contralor</h4>
        <div class="grid2" style="margin-bottom:8px"><input id="cNombre" placeholder="Nombre"><input id="cGrado" placeholder="Grado"></div>
        <div class="flex-gap" style="margin-bottom:8px;align-items:center">
          <button class="btn btn-gray" onclick="document.getElementById('fileCandC').click()">📷 Foto</button>
          <input type="file" id="fileCandC" accept="image/*" style="display:none" onchange="fileToB64(this.files[0],b64=>window._fotoC=b64)">
        </div>
        <button class="btn btn-green" onclick="agregarCandidato('contralor')">+ Agregar</button>
        ${el.contralores.length?`<div class="over" style="margin-top:10px"><table><thead><tr><th>Foto</th><th>Nombre</th><th>Grado</th><th>Del</th></tr></thead><tbody>${contralorRows}</tbody></table></div>`:'<p class="empty" style="padding:10px">Sin candidatos</p>'}
      </div>
    </div>
    <div class="card">
      <h4 class="card-title">Votantes</h4>
      <button class="btn btn-blue" onclick="sincronizarVotantes()">🔄 Sincronizar Estudiantes</button>
      <span style="margin-left:12px;color:#666">Registrados: <b>${(el.votantes||[]).length}</b> | Votos: <b>${totalVotos}</b></span>
    </div>
    <div class="card" style="border-left:4px solid #7d3c98">
      <h4 class="card-title" style="color:#7d3c98">🔑 Acceso al Módulo de Elecciones</h4>
      ${(()=>{
        const eu=db.users&&db.users.find(x=>x.r==='elecciones');
        const passActual=eu?eu.p:'inetis2026';
        return `<div style="background:#f9f3ff;border:1px solid #d2b4f0;border-radius:8px;padding:12px;margin-bottom:12px">
          <p style="margin:0 0 4px;font-size:0.9rem"><b>Usuario:</b> <code style="background:#e8d5f7;padding:2px 8px;border-radius:4px">elecciones</code></p>
          <p style="margin:0;font-size:0.9rem"><b>Contraseña actual:</b> <code style="background:#e8d5f7;padding:2px 8px;border-radius:4px">${passActual}</code></p>
        </div>
        <div style="display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap">
          <div style="flex:1;min-width:160px"><label class="lbl">Nueva contraseña</label><input id="elecNuevaPass" placeholder="Mínimo 4 caracteres" style="margin-bottom:0"></div>
          <button class="btn" style="background:#7d3c98;color:#fff;white-space:nowrap" onclick="cambiarPassElecciones()">🔒 Cambiar contraseña</button>
        </div>`;
      })()}
    </div>
  </div>`;
}
function cambiarPassElecciones(){
  const nueva=(document.getElementById('elecNuevaPass')?.value||'').trim();
  if(nueva.length<4){alert('La contraseña debe tener al menos 4 caracteres.');return;}
  updDB(d=>{
    if(!Array.isArray(d.users)) d.users=[];
    const idx=d.users.findIndex(x=>x.r==='elecciones');
    if(idx>=0) d.users[idx].p=nueva;
    else d.users.push({u:'elecciones',p:nueva,r:'elecciones',n:'MÓDULO ELECCIONES'});
    return d;
  });
  alert('✅ Contraseña del módulo de Elecciones actualizada a: '+nueva);
  renderApp();
}
function reiniciarElecciones(){
  if(!confirm('¿REINICIAR TODO el módulo de elecciones? Se borrarán candidatos, votantes y votos. Esta acción NO se puede deshacer.')) return;
  if(!confirm(`Confirme nuevamente: ¿Reiniciar elecciones del año ${db.anio}?`)) return;
  updDB(d=>{d.elecciones[d.anio]={personeros:[],contralores:[],votantes:[],votos:{personero:{},contralor:{},blancosP:0,blancosC:0}};return d;});
  alert('Módulo de elecciones reiniciado.');renderApp();
}
function mostrarTabElecAdmin(tab,btn){
  document.querySelectorAll('.tab-btn').forEach(b=>b.classList.remove('active'));if(btn) btn.classList.add('active');
  const wrap=document.getElementById('elecAdminContenido');if(!wrap) return;
  const anioE=db.anio;const el=(db.elecciones||{})[anioE]||{personeros:[],contralores:[],votantes:[],votos:{personero:{},contralor:{},blancosP:0,blancosC:0}};
  if(tab==='resultados'){
    const totalP=Object.values(el.votos.personero||{}).reduce((a,b)=>a+b,0)+(el.votos.blancosP||0);
    const totalC=Object.values(el.votos.contralor||{}).reduce((a,b)=>a+b,0)+(el.votos.blancosC||0);
    const pRows=(el.personeros||[]).map(p=>`<tr><td>${p.nombre}</td><td>${el.votos.personero[p.nombre]||0}</td><td>${totalP>0?((el.votos.personero[p.nombre]||0)*100/totalP).toFixed(1)+'%':'-'}</td></tr>`).join('');
    const cRows=(el.contralores||[]).map(p=>`<tr><td>${p.nombre}</td><td>${el.votos.contralor[p.nombre]||0}</td><td>${totalC>0?((el.votos.contralor[p.nombre]||0)*100/totalC).toFixed(1)+'%':'-'}</td></tr>`).join('');
    wrap.innerHTML=`<div class="grid2" style="gap:15px">
      <div class="card"><h4 class="card-title">Personero — Total: ${totalP}</h4>
        <table><thead><tr><th>Candidato</th><th>Votos</th><th>%</th></tr></thead><tbody>${pRows}<tr><td>BLANCO</td><td>${el.votos.blancosP||0}</td><td>${totalP>0?(((el.votos.blancosP||0)*100/totalP).toFixed(1)+'%'):'-'}</td></tr></tbody></table></div>
      <div class="card"><h4 class="card-title">Contralor — Total: ${totalC}</h4>
        <table><thead><tr><th>Candidato</th><th>Votos</th><th>%</th></tr></thead><tbody>${cRows}<tr><td>BLANCO</td><td>${el.votos.blancosC||0}</td><td>${totalC>0?(((el.votos.blancosC||0)*100/totalC).toFixed(1)+'%'):'-'}</td></tr></tbody></table></div>
    </div>`;
  } else if(tab==='votantes'){
    const vRows=(el.votantes||[]).map((v,i)=>`<tr><td>${v.nombre}</td><td>${v.grado}</td><td>${v.votoP?'✅':'⬜'} ${v.votoC?'✅':'⬜'}</td><td>${v.votoOnline?'<span style="background:#d5f5e3;color:#1e8449;border-radius:10px;padding:1px 7px;font-size:0.72rem;font-weight:bold">🌐 Online</span>':'—'}</td>
      <td><button class="btn-sm" style="background:#c0392b" onclick="eliminarVotante(${i})">🗑</button></td></tr>`).join('');
    wrap.innerHTML=`<div class="card"><h4 class="card-title">Votantes (${(el.votantes||[]).length})</h4>
      <div class="flex-gap" style="margin-bottom:12px">
        <input id="votanteBuscar" placeholder="Buscar..." style="flex:1" oninput="filtrarVotantesAdmin()">
        <button class="btn btn-green" onclick="agregarVotanteManual()">+ Agregar</button>
      </div>
      <div class="over"><table><thead><tr><th>Nombre</th><th>Grado</th><th>Votó</th><th>Canal</th><th>Del</th></tr></thead><tbody id="bodyVotantes">${vRows}</tbody></table></div></div>`;
  }
}
function agregarCandidato(tipo){
  const nom=document.getElementById(tipo==='personero'?'pNombre':'cNombre').value.trim();
  const gra=document.getElementById(tipo==='personero'?'pGrado':'cGrado').value.trim();
  const foto=tipo==='personero'?(window._fotoP||''):(window._fotoC||'');
  if(!nom){alert('Ingrese el nombre');return;}
  updDB(d=>{const anioE=d.anio;if(!d.elecciones) d.elecciones={};if(!d.elecciones[anioE]) d.elecciones[anioE]={personeros:[],contralores:[],votantes:[],votos:{personero:{},contralor:{},blancosP:0,blancosC:0}};
    if(tipo==='personero') d.elecciones[anioE].personeros.push({nombre:nom.toUpperCase(),grado:gra,foto});
    else d.elecciones[anioE].contralores.push({nombre:nom.toUpperCase(),grado:gra,foto});return d;});
  window._fotoP='';window._fotoC='';renderApp();
}
function eliminarCandidato(tipo,idx){if(!confirm('¿Eliminar?')) return;updDB(d=>{if(tipo==='personero') d.elecciones[d.anio].personeros.splice(idx,1);else d.elecciones[d.anio].contralores.splice(idx,1);return d;});renderApp();}
function sincronizarVotantes(){
  updDB(d=>{const anioE=d.anio;if(!d.elecciones) d.elecciones={};if(!d.elecciones[anioE]) d.elecciones[anioE]={personeros:[],contralores:[],votantes:[],votos:{personero:{},contralor:{},blancosP:0,blancosC:0}};
    const yaReg=(d.elecciones[anioE].votantes||[]).map(v=>v.nombre);
    d.ests.forEach(e=>{if(!yaReg.includes(e.n)) d.elecciones[anioE].votantes.push({nombre:e.n,grado:e.g,votoP:false,votoC:false});});return d;});
  alert('Sincronizado.');renderApp();
}
function eliminarVotante(idx){if(!confirm('¿Eliminar?')) return;updDB(d=>{d.elecciones[d.anio].votantes.splice(idx,1);return d;});mostrarTabElecAdmin('votantes',null);}
function agregarVotanteManual(){
  const nom=prompt('Nombre:');if(!nom) return;const gra=prompt('Grado:');if(gra===null) return;
  updDB(d=>{d.elecciones[d.anio].votantes.push({nombre:nom.toUpperCase(),grado:gra,votoP:false,votoC:false});return d;});mostrarTabElecAdmin('votantes',null);
}
function filtrarVotantesAdmin(){
  const q=document.getElementById('votanteBuscar')?.value.toLowerCase()||'';
  const anioE=db.anio;const el=(db.elecciones||{})[anioE]||{votantes:[]};
  const filtrados=q.length>1?(el.votantes||[]).filter(v=>v.nombre.toLowerCase().includes(q)):(el.votantes||[]);
  const body=document.getElementById('bodyVotantes');
  if(body) body.innerHTML=filtrados.map((v,i)=>`<tr><td>${v.nombre}</td><td>${v.grado}</td><td>${v.votoP?'✅':'⬜'} ${v.votoC?'✅':'⬜'}</td><td>${v.votoOnline?'<span style="background:#d5f5e3;color:#1e8449;border-radius:10px;padding:1px 7px;font-size:0.72rem;font-weight:bold">🌐 Online</span>':'—'}</td>
    <td><button class="btn-sm" style="background:#c0392b" onclick="eliminarVotante(${(el.votantes||[]).indexOf(v)})">🗑</button></td></tr>`).join('');
}

// ============================================================
// MÓDULO VOTACIÓN
// ============================================================
let elecStep='inicio';let elecVotante=null;let elecSelP=null;let elecSelC=null;
let _estElecStep=null;let _estElecSelP=null;let _estElecSelC=null;
// ── S10 · MÓDULOS DE GESTIÓN ESTUDIANTIL ─────────────────────
// Traslados, elecciones, evaluación docente, actividades,
// quizzes, menciones de honor, permisos y credenciales.
// ─────────────────────────────────────────────────────────────
function renderElecciones(){
  const anioE=db.anio;if(!db.elecciones) db.elecciones={};
  if(!db.elecciones[anioE]) db.elecciones[anioE]={personeros:[],contralores:[],votantes:[],votos:{personero:{},contralor:{},blancosP:0,blancosC:0}};
  document.getElementById('app').innerHTML=`
  <div class="header">
    ${db.logo?`<img src="${db.logo}" style="max-height:70px;border-radius:6px">`:""}
    <h1>🗳️ MÓDULO DE ELECCIONES — ${anioE}</h1><p>${db.nombre||db.corregimiento||'Institución Educativa'}</p>
  </div>
  <div style="max-width:900px;margin:30px auto;padding:0 16px">
    <div class="flex-gap" style="margin-bottom:20px;justify-content:center">
      <button class="btn btn-navy" onclick="elecStep='votacion';renderElecContenido()">🗳️ VOTACIÓN</button>
      <button class="btn btn-blue" onclick="elecStep='resultados';renderElecContenido()">📊 RESULTADOS</button>
      <button class="btn btn-red" onclick="cerrarSesion()">🚪 SALIR</button>
    </div>
    <div id="elecContenido"></div>
  </div>`;
  renderElecContenido();
}
function renderElecContenido(){
  const wrap=document.getElementById('elecContenido');if(!wrap) return;
  const anioE=db.anio;const el=(db.elecciones||{})[anioE]||{personeros:[],contralores:[],votantes:[],votos:{personero:{},contralor:{},blancosP:0,blancosC:0}};
  if(elecStep==='votacion'){
    wrap.innerHTML=`<div class="card" style="text-align:center"><h3 style="color:#003366;margin-bottom:16px">Registro de Votante</h3>
      <div style="max-width:400px;margin:0 auto">
        <label class="lbl" style="text-align:left">Buscar Estudiante</label>
        <input type="text" id="buscarVotante" placeholder="Escriba el nombre..." oninput="buscarEstVotante()" style="margin-bottom:8px">
        <div id="resultBusqueda" style="max-height:200px;overflow-y:auto;border:1px solid #eee;border-radius:5px"></div>
      </div></div>`;
  } else if(elecStep==='votar-personero'){
    const cards=(el.personeros||[]).map((p,i)=>`<div class="cand-card${elecSelP===i?' selected':''}" onclick="elecSelP=${i};renderElecContenido()" style="width:130px">
      <img src="${p.foto||'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mN8/5+hHgAHggJ/PchI6QAAAABJRU5ErkJggg=='}" alt="${p.nombre}">
      <div style="font-size:0.78rem;font-weight:bold">${p.nombre}</div><div style="font-size:0.72rem;color:#666">Grado ${p.grado}</div></div>`).join('');
    wrap.innerHTML=`<div class="card" style="text-align:center">
      <div class="warn-box">Votando: <b>${elecVotante?.nombre}</b></div>
      <h3 style="color:#003366;margin-bottom:16px">Candidato a PERSONERO</h3>
      <div style="display:flex;gap:12px;flex-wrap:wrap;justify-content:center;margin-bottom:16px">
        ${cards}<div class="cand-card${elecSelP==='blanco'?' selected':''}" onclick="elecSelP='blanco';renderElecContenido()" style="width:130px">
          <div style="width:70px;height:80px;background:#eee;border-radius:6px;margin:0 auto;line-height:80px;font-size:2rem">⬜</div>
          <div style="font-size:0.78rem;font-weight:bold">VOTO EN BLANCO</div></div>
      </div>
      <button class="btn btn-green" onclick="confirmarVotoPersonero()" ${elecSelP===null?'disabled':''}>✅ Confirmar</button>
      <button class="btn btn-gray" style="margin-left:8px" onclick="elecStep='votacion';elecVotante=null;elecSelP=null;elecSelC=null;renderElecContenido()">← Cancelar</button>
    </div>`;
  } else if(elecStep==='votar-contralor'){
    const cards=(el.contralores||[]).map((p,i)=>`<div class="cand-card${elecSelC===i?' selected':''}" onclick="elecSelC=${i};renderElecContenido()" style="width:130px">
      <img src="${p.foto||'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mN8/5+hHgAHggJ/PchI6QAAAABJRU5ErkJggg=='}" alt="${p.nombre}">
      <div style="font-size:0.78rem;font-weight:bold">${p.nombre}</div><div style="font-size:0.72rem;color:#666">Grado ${p.grado}</div></div>`).join('');
    wrap.innerHTML=`<div class="card" style="text-align:center">
      <div class="warn-box">Votando: <b>${elecVotante?.nombre}</b> | ✅ Personero ok</div>
      <h3 style="color:#003366;margin-bottom:16px">Candidato a CONTRALOR</h3>
      <div style="display:flex;gap:12px;flex-wrap:wrap;justify-content:center;margin-bottom:16px">
        ${cards}<div class="cand-card${elecSelC==='blanco'?' selected':''}" onclick="elecSelC='blanco';renderElecContenido()" style="width:130px">
          <div style="width:70px;height:80px;background:#eee;border-radius:6px;margin:0 auto;line-height:80px;font-size:2rem">⬜</div>
          <div style="font-size:0.78rem;font-weight:bold">VOTO EN BLANCO</div></div>
      </div>
      <button class="btn btn-green" onclick="confirmarVotoContralor()" ${elecSelC===null?'disabled':''}>✅ Confirmar</button>
      <button class="btn btn-gray" style="margin-left:8px" onclick="elecStep='votacion';elecVotante=null;elecSelP=null;elecSelC=null;renderElecContenido()">← Cancelar</button>
    </div>`;
  } else if(elecStep==='voto-ok'){
    wrap.innerHTML=`<div class="card" style="text-align:center;padding:40px">
      <div style="font-size:4rem;margin-bottom:16px">✅</div>
      <h2 style="color:#27ae60;margin-bottom:8px">¡Voto Registrado!</h2>
      <p style="color:#666;margin-bottom:20px">Gracias por participar.</p>
      <button class="btn btn-navy" onclick="elecStep='votacion';elecVotante=null;elecSelP=null;elecSelC=null;renderElecContenido()">🗳️ Siguiente Votante</button>
    </div>`;
  } else if(elecStep==='resultados'){
    const totalP=Object.values(el.votos.personero||{}).reduce((a,b)=>a+b,0)+(el.votos.blancosP||0);
    const totalC=Object.values(el.votos.contralor||{}).reduce((a,b)=>a+b,0)+(el.votos.blancosC||0);
    const pRows=(el.personeros||[]).map(p=>`<tr><td>${p.nombre}</td><td>${el.votos.personero[p.nombre]||0}</td><td>${totalP>0?((el.votos.personero[p.nombre]||0)*100/totalP).toFixed(1)+'%':'-'}</td></tr>`).join('');
    const cRows=(el.contralores||[]).map(p=>`<tr><td>${p.nombre}</td><td>${el.votos.contralor[p.nombre]||0}</td><td>${totalC>0?((el.votos.contralor[p.nombre]||0)*100/totalC).toFixed(1)+'%':'-'}</td></tr>`).join('');
    wrap.innerHTML=`<div class="grid2" style="gap:15px">
      <div class="card"><h4 class="card-title">Personero — Total: ${totalP}</h4>
        <table><thead><tr><th>Candidato</th><th>Votos</th><th>%</th></tr></thead><tbody>${pRows}<tr><td>BLANCO</td><td>${el.votos.blancosP||0}</td><td>${totalP>0?(((el.votos.blancosP||0)*100/totalP).toFixed(1)+'%'):'-'}</td></tr></tbody></table></div>
      <div class="card"><h4 class="card-title">Contralor — Total: ${totalC}</h4>
        <table><thead><tr><th>Candidato</th><th>Votos</th><th>%</th></tr></thead><tbody>${cRows}<tr><td>BLANCO</td><td>${el.votos.blancosC||0}</td><td>${totalC>0?(((el.votos.blancosC||0)*100/totalC).toFixed(1)+'%'):'-'}</td></tr></tbody></table></div>
    </div>`;
  }
}
function buscarEstVotante(){
  const q=document.getElementById('buscarVotante')?.value.toLowerCase()||'';
  const anioE=db.anio;const el=(db.elecciones||{})[anioE]||{votantes:[]};
  const res=(el.votantes||[]).filter(v=>v.nombre.toLowerCase().includes(q)&&q.length>1);
  const wrap=document.getElementById('resultBusqueda');if(!wrap) return;
  if(!res.length){wrap.innerHTML=`<div style="padding:10px;text-align:center"><p style="color:#999">No encontrado.</p><button class="btn btn-orange" onclick="agregarVotanteModal()">+ Agregar y Votar</button></div>`;return;}
  wrap.innerHTML=res.map(v=>`<div style="padding:8px 12px;border-bottom:1px solid #eee;cursor:pointer;display:flex;justify-content:space-between" onclick="seleccionarVotante('${v.nombre}')">
    <span><b>${v.nombre}</b> — ${v.grado}</span>${v.votoP?'<span style="color:#27ae60;font-size:0.8rem">Ya votó ✅</span>':'<span style="color:#003366;font-size:0.8rem">→ Votar</span>'}</div>`).join('');
}
function seleccionarVotante(nombre){
  const anioE=db.anio;const el=(db.elecciones||{})[anioE]||{votantes:[]};
  const v=(el.votantes||[]).find(x=>x.nombre===nombre);if(!v){alert('No encontrado.');return;}
  if(v.votoP&&v.votoC){alert('Ya ejerció su voto.');return;}
  elecVotante=v;elecStep='votar-personero';elecSelP=null;elecSelC=null;renderElecContenido();
}
function agregarVotanteModal(){
  const nom=prompt('Nombre:');if(!nom) return;const gra=prompt('Grado:');if(gra===null) return;
  updDB(d=>{d.elecciones[d.anio].votantes.push({nombre:nom.toUpperCase(),grado:gra,votoP:false,votoC:false});return d;});
  seleccionarVotante(nom.toUpperCase());
}
function confirmarVotoPersonero(){if(elecSelP===null){alert('Seleccione candidato');return;}elecStep='votar-contralor';renderElecContenido();}
function confirmarVotoContralor(){
  if(elecSelC===null){alert('Seleccione candidato');return;}
  const anioE=db.anio;
  updDB(d=>{const el=d.elecciones[anioE];
    if(!el.votos.personero) el.votos.personero={};if(!el.votos.contralor) el.votos.contralor={};
    if(elecSelP==='blanco') el.votos.blancosP=(el.votos.blancosP||0)+1;
    else{const np=el.personeros[elecSelP]?.nombre;if(np) el.votos.personero[np]=(el.votos.personero[np]||0)+1;}
    if(elecSelC==='blanco') el.votos.blancosC=(el.votos.blancosC||0)+1;
    else{const nc=el.contralores[elecSelC]?.nombre;if(nc) el.votos.contralor[nc]=(el.votos.contralor[nc]||0)+1;}
    const vi=el.votantes.findIndex(v=>v.nombre===elecVotante.nombre);
    if(vi!==-1){el.votantes[vi].votoP=true;el.votantes[vi].votoC=true;}
    return d;
  });
  elecStep='voto-ok';renderElecContenido();
}

// ──────────────────────────────────────────────
// MODO DE VOTACIÓN (admin toggle)
// ──────────────────────────────────────────────
function establecerModoVotacion(modo){
  const label=modo==='online'?'100% Online (estudiantes votan desde su portal)':'Presencial + Online para ausentes';
  if(!confirm('¿Activar modo "'+label+'"? Los votos ya registrados no se borran.')) return;
  updDB(d=>{
    if(!d.elecciones) d.elecciones={};
    if(!d.elecciones[d.anio]) d.elecciones[d.anio]={personeros:[],contralores:[],votantes:[],votos:{personero:{},contralor:{},blancosP:0,blancosC:0}};
    d.elecciones[d.anio].modoVotacion=modo;
    return d;
  });
  renderApp();
}

// ──────────────────────────────────────────────
// VOTACIÓN ONLINE DESDE ROL ESTUDIANTE
// ──────────────────────────────────────────────
function htmlEleccionEstudiante(est){
  if(!moduloActivo('elecciones-admin')) return '';
  const anioE=db.anio;
  const el=(db.elecciones||{})[anioE]||{};
  const modo=el.modoVotacion||'presencial';
  const personeros=el.personeros||[];
  const contralores=el.contralores||[];
  if(!personeros.length&&!contralores.length) return '';
  const votante=(el.votantes||[]).find(v=>v.estId===est.id||v.nombre===est.n);
  const yaVoto=votante&&(votante.votoOnline||(votante.votoP&&votante.votoC));
  if(yaVoto){
    const selP=votante.votoNomP||'registrado';
    return `<div class="card" style="border-left:4px solid #27ae60;background:linear-gradient(135deg,#eafaf1,#fff)">
      <h4 class="card-title" style="color:#1e8449">🗳️ Democracia Escolar ${anioE}</h4>
      <div style="text-align:center;padding:18px 0">
        <div style="font-size:3rem;margin-bottom:8px">✅</div>
        <h3 style="color:#27ae60;margin-bottom:6px">¡Tu voto fue registrado!</h3>
        <p style="color:#555;font-size:0.88rem">Participaste en las elecciones escolares ${anioE}.</p>
        <div style="margin-top:10px;background:#d5f5e3;border-radius:8px;padding:8px 16px;display:inline-block;font-size:0.8rem;color:#1e8449">🏅 ¡Gracias por ejercer tu derecho a la democracia escolar!</div>
      </div>
    </div>`;
  }
  if(modo==='presencial'&&votante&&votante.votoP&&!votante.votoOnline) return '';
  if(!window._estElecStep) window._estElecStep='intro';
  return `<div class="card" style="border-left:4px solid #7d3c98;background:linear-gradient(135deg,#f9f3ff,#fff)" id="estElecCard">
    <h4 class="card-title" style="color:#7d3c98">🗳️ ${modo==='online'?'Votación Online':'Voto desde Casa'} — Democracia Escolar ${anioE}</h4>
    ${modo==='presencial'?'<div style="background:#fff3cd;border:1px solid #ffc107;border-radius:8px;padding:9px 14px;font-size:0.8rem;color:#856404;margin-bottom:12px">📌 <b>Si no puedes asistir presencialmente</b>, puedes ejercer tu voto aquí de forma segura.</div>':''}
    <div id="estElecPasos">${_estElecRenderPaso(est,el)}</div>
  </div>`;
}
function _estElecRenderPaso(est,el){
  const step=window._estElecStep||'intro';
  const personeros=el.personeros||[];
  const contralores=el.contralores||[];
  const _blankPH='data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iNjAiIGhlaWdodD0iNzAiIHhtbG5zPSJodHRwOi8vd3d3LnczLm9yZy8yMDAwL3N2ZyI+PHJlY3Qgd2lkdGg9IjYwIiBoZWlnaHQ9IjcwIiBmaWxsPSIjZTBlMGUwIiByeD0iNiIvPjx0ZXh0IHg9IjMwIiB5PSI0MCIgZm9udC1zaXplPSIyOCIgdGV4dC1hbmNob3I9Im1pZGRsZSIgZmlsbD0iIzk5OSI+8J+RpDwvdGV4dD48L3N2Zz4=';
  if(step==='intro'){
    return `<div style="text-align:center">
      <p style="color:#555;font-size:0.86rem;margin-bottom:14px;line-height:1.5">Vas a ejercer tu voto secreto en dos pasos:<br><b style="color:#7d3c98">Personero(a)</b> y <b style="color:#1a5276">Contralor(a)</b>.</p>
      <div style="display:flex;gap:10px;justify-content:center;margin-bottom:16px">
        <div style="background:#f0e6fa;border-radius:8px;padding:10px 16px;text-align:center"><div style="font-size:1.4rem">👑</div><div style="font-size:0.72rem;font-weight:bold;color:#7d3c98">${personeros.length} candidato(s)<br>Personero</div></div>
        <div style="background:#e8f4fb;border-radius:8px;padding:10px 16px;text-align:center"><div style="font-size:1.4rem">📋</div><div style="font-size:0.72rem;font-weight:bold;color:#1a5276">${contralores.length} candidato(s)<br>Contralor</div></div>
      </div>
      <button onclick="_estElecIr('personero')" style="background:#7d3c98;color:#fff;border:none;border-radius:10px;padding:12px 28px;font-size:0.93rem;font-weight:700;cursor:pointer">🗳️ Comenzar Votación</button>
    </div>`;
  }
  if(step==='personero'){
    const cards=personeros.map((p,i)=>`<div onclick="_estElecSelPFn(${i})" style="cursor:pointer;padding:10px 8px;border:2.5px solid ${_estElecSelP===i?'#7d3c98':'#dde3f0'};border-radius:10px;text-align:center;background:${_estElecSelP===i?'#f0e6fa':'#f8f9fa'};transition:all .18s;min-width:90px;max-width:120px">
      <img src="${p.foto||_blankPH}" style="width:56px;height:66px;object-fit:cover;border-radius:6px;margin-bottom:4px">
      <div style="font-size:0.72rem;font-weight:bold;color:#7d3c98;line-height:1.2">${p.nombre}</div>
      <div style="font-size:0.66rem;color:#888">Grado ${p.grado}</div>
      ${_estElecSelP===i?'<div style="color:#7d3c98;font-size:0.72rem;font-weight:bold;margin-top:2px">✓</div>':''}
    </div>`).join('');
    return `<div>
      <div style="text-align:center;font-size:0.78rem;color:#7d3c98;font-weight:700;margin-bottom:12px;background:#f0e6fa;border-radius:6px;padding:6px">👑 PASO 1 DE 2 — Candidatos a PERSONERO(A)</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-bottom:14px">
        ${cards}
        <div onclick="_estElecSelPFn('blanco')" style="cursor:pointer;padding:10px 8px;border:2.5px solid ${_estElecSelP==='blanco'?'#7d3c98':'#dde3f0'};border-radius:10px;text-align:center;background:${_estElecSelP==='blanco'?'#f0e6fa':'#f8f9fa'};min-width:90px">
          <div style="width:56px;height:66px;background:#eee;border-radius:6px;margin:0 auto 4px;display:flex;align-items:center;justify-content:center;font-size:1.8rem">⬜</div>
          <div style="font-size:0.72rem;font-weight:bold;color:#555">VOTO EN BLANCO</div>
          ${_estElecSelP==='blanco'?'<div style="color:#7d3c98;font-size:0.72rem;font-weight:bold;margin-top:2px">✓</div>':''}
        </div>
      </div>
      <div style="text-align:center"><button onclick="_estElecConfPFn()" style="background:${_estElecSelP!==null?'#7d3c98':'#bbb'};color:#fff;border:none;border-radius:10px;padding:11px 22px;font-size:0.88rem;font-weight:700;cursor:pointer" ${_estElecSelP===null?'disabled':''}>Siguiente → Contralor</button></div>
    </div>`;
  }
  if(step==='contralor'){
    const cards=contralores.map((p,i)=>`<div onclick="_estElecSelCFn(${i})" style="cursor:pointer;padding:10px 8px;border:2.5px solid ${_estElecSelC===i?'#1a5276':'#dde3f0'};border-radius:10px;text-align:center;background:${_estElecSelC===i?'#eaf4fb':'#f8f9fa'};transition:all .18s;min-width:90px;max-width:120px">
      <img src="${p.foto||_blankPH}" style="width:56px;height:66px;object-fit:cover;border-radius:6px;margin-bottom:4px">
      <div style="font-size:0.72rem;font-weight:bold;color:#1a5276;line-height:1.2">${p.nombre}</div>
      <div style="font-size:0.66rem;color:#888">Grado ${p.grado}</div>
      ${_estElecSelC===i?'<div style="color:#1a5276;font-size:0.72rem;font-weight:bold;margin-top:2px">✓</div>':''}
    </div>`).join('');
    return `<div>
      <div style="background:#d5f5e3;border-radius:6px;padding:6px 12px;font-size:0.78rem;color:#1e8449;margin-bottom:10px;text-align:center">✅ Personero(a) seleccionado(a) — Ahora elige Contralor(a)</div>
      <div style="text-align:center;font-size:0.78rem;color:#1a5276;font-weight:700;margin-bottom:12px;background:#eaf4fb;border-radius:6px;padding:6px">📋 PASO 2 DE 2 — Candidatos a CONTRALOR(A)</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-bottom:14px">
        ${cards}
        <div onclick="_estElecSelCFn('blanco')" style="cursor:pointer;padding:10px 8px;border:2.5px solid ${_estElecSelC==='blanco'?'#1a5276':'#dde3f0'};border-radius:10px;text-align:center;background:${_estElecSelC==='blanco'?'#eaf4fb':'#f8f9fa'};min-width:90px">
          <div style="width:56px;height:66px;background:#eee;border-radius:6px;margin:0 auto 4px;display:flex;align-items:center;justify-content:center;font-size:1.8rem">⬜</div>
          <div style="font-size:0.72rem;font-weight:bold;color:#555">VOTO EN BLANCO</div>
          ${_estElecSelC==='blanco'?'<div style="color:#1a5276;font-size:0.72rem;font-weight:bold;margin-top:2px">✓</div>':''}
        </div>
      </div>
      <div style="text-align:center;display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
        <button onclick="_estElecIr('personero')" style="background:#95a5a6;color:#fff;border:none;border-radius:8px;padding:10px 18px;font-size:0.82rem;cursor:pointer">← Atrás</button>
        <button onclick="_estElecConfCFn('${est.id}')" style="background:${_estElecSelC!==null?'#1a5276':'#bbb'};color:#fff;border:none;border-radius:10px;padding:11px 22px;font-size:0.88rem;font-weight:700;cursor:pointer" ${_estElecSelC===null?'disabled':''}>✅ Enviar mi Voto</button>
      </div>
    </div>`;
  }
  return '';
}
function _estElecIr(paso){window._estElecStep=paso;const w=document.getElementById('estElecPasos');if(w){const est=db.ests.find(e=>e.id===sesion.estId)||{};const el=(db.elecciones||{})[db.anio]||{};w.innerHTML=_estElecRenderPaso(est,el);}}
function _estElecSelPFn(idx){_estElecSelP=idx;_estElecIr('personero');}
function _estElecSelCFn(idx){_estElecSelC=idx;_estElecIr('contralor');}
function _estElecConfPFn(){if(_estElecSelP===null){alert('Selecciona un candidato o voto en blanco.');return;}_estElecIr('contralor');}
function _estElecConfCFn(estId){
  if(_estElecSelC===null){alert('Selecciona un candidato o voto en blanco.');return;}
  if(!confirm('¿Confirmas tu voto? Esta acción es definitiva y no se puede modificar.')) return;
  const anioE=db.anio;
  updDB(d=>{
    if(!d.elecciones) d.elecciones={};
    if(!d.elecciones[anioE]) d.elecciones[anioE]={personeros:[],contralores:[],votantes:[],votos:{personero:{},contralor:{},blancosP:0,blancosC:0}};
    const el=d.elecciones[anioE];
    if(!el.votos.personero) el.votos.personero={};
    if(!el.votos.contralor) el.votos.contralor={};
    if(_estElecSelP==='blanco') el.votos.blancosP=(el.votos.blancosP||0)+1;
    else{const np=el.personeros[_estElecSelP]?.nombre;if(np) el.votos.personero[np]=(el.votos.personero[np]||0)+1;}
    if(_estElecSelC==='blanco') el.votos.blancosC=(el.votos.blancosC||0)+1;
    else{const nc=el.contralores[_estElecSelC]?.nombre;if(nc) el.votos.contralor[nc]=(el.votos.contralor[nc]||0)+1;}
    const est2=d.ests.find(e=>String(e.id)===String(estId))||{n:sesion.n,g:''};
    const vi=(el.votantes||[]).findIndex(v=>String(v.estId)===String(estId)||v.nombre===est2.n);
    if(vi!==-1){el.votantes[vi].votoP=true;el.votantes[vi].votoC=true;el.votantes[vi].votoOnline=true;}
    else{if(!el.votantes) el.votantes=[];el.votantes.push({nombre:est2.n,grado:est2.g||'',estId:String(estId),votoP:true,votoC:true,votoOnline:true});}
    return d;
  });
  _estElecStep=null;_estElecSelP=null;_estElecSelC=null;
  renderEstudiante();
}

