function _iaCopiarMsg(idx){
  const m=_iaMsgs[idx];
  if(!m||!m.content) return;
  const txt=m.content;
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(txt).then(()=>_showToast('✅ Texto copiado al portapapeles')).catch(()=>{
      const ta=document.createElement('textarea');ta.value=txt;ta.style.cssText='position:fixed;opacity:0;top:0;left:0';
      document.body.appendChild(ta);ta.select();try{document.execCommand('copy');_showToast('✅ Texto copiado');}catch(e){_showToast('❌ No se pudo copiar');}document.body.removeChild(ta);
    });
  } else {
    const ta=document.createElement('textarea');ta.value=txt;ta.style.cssText='position:fixed;opacity:0;top:0;left:0';
    document.body.appendChild(ta);ta.select();try{document.execCommand('copy');_showToast('✅ Texto copiado');}catch(e){_showToast('❌ No se pudo copiar');}document.body.removeChild(ta);
  }
}
function iaRenderMsgs(){
  const c=document.getElementById('iaMsgs');
  if(!c) return;
  const ctx=_iaGetCtx();
  const lastMsg=_iaMsgs[_iaMsgs.length-1];
  const isPlaneacionResp=window._iaEsPlaneacion&&lastMsg&&lastMsg.role==='assistant'&&!lastMsg.loading&&lastMsg.content&&lastMsg.content.length>200;
  const _cr=sesion?_iaGetCreditos():{used:0,limit:30};const _crLeft=Math.max(0,_cr.limit-_cr.used);const _crColor=_crLeft<=5?'#e74c3c':_crLeft<=10?'#e67e22':'#27ae60';
  c.innerHTML=`<div class="ia-ctx">🎓 Gestor Académico YC &nbsp;|&nbsp; 📂 ${ctx.modulo} &nbsp;|&nbsp; 👤 ${ctx.usuario} &nbsp;|&nbsp; <span style="color:${_crColor};font-weight:700" title="Créditos IA restantes hoy">⚡ ${_crLeft}/${_cr.limit}</span></div>`
    +_iaMsgs.map((m,i)=>{
      const isLast=(i===_iaMsgs.length-1);
      const showBtns=isLast&&isPlaneacionResp&&m.role==='assistant';
      const showActionBtns=m.role==='assistant'&&!m.loading&&m.content&&m.content.length>80;
      const btnsHtml=showBtns?`<div style="display:flex;flex-wrap:wrap;gap:7px;margin-top:10px;padding-top:8px;border-top:1px solid rgba(255,255,255,0.15)">
        <button onclick="_guardarPlaneacionIA()" style="background:linear-gradient(135deg,#27ae60,#1e8449);color:#fff;border:none;border-radius:7px;padding:7px 13px;font-size:0.8rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:5px">💾 Guardar planeación</button>
        <button onclick="_descargarPlaneIAPDF(${i})" style="background:linear-gradient(135deg,#c0392b,#922b21);color:#fff;border:none;border-radius:7px;padding:7px 13px;font-size:0.8rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:5px">📄 Descargar PDF</button>
        <button onclick="_descargarPlaneIAWord(${i})" style="background:linear-gradient(135deg,#1a5276,#2980b9);color:#fff;border:none;border-radius:7px;padding:7px 13px;font-size:0.8rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:5px">📝 Descargar Word</button>
      </div>`:'';
      const actionBtns=showActionBtns?`<div style="display:flex;gap:5px;margin-top:7px;flex-wrap:wrap">
        <button onclick="_iaCopiarMsg(${i})" title="Copiar texto" style="background:rgba(0,51,102,0.07);border:1px solid rgba(0,51,102,0.15);border-radius:6px;padding:3px 9px;font-size:0.72rem;color:#1a3a5c;cursor:pointer;display:inline-flex;align-items:center;gap:3px" onmouseover="this.style.background='rgba(0,51,102,0.14)'" onmouseout="this.style.background='rgba(0,51,102,0.07)'">📋 Copiar</button>
        <button onclick="_descargarPlaneIAPDF(${i})" title="Descargar PDF" style="background:rgba(192,57,43,0.07);border:1px solid rgba(192,57,43,0.18);border-radius:6px;padding:3px 9px;font-size:0.72rem;color:#922b21;cursor:pointer;display:inline-flex;align-items:center;gap:3px" onmouseover="this.style.background='rgba(192,57,43,0.14)'" onmouseout="this.style.background='rgba(192,57,43,0.07)'">📄 PDF</button>
        <button onclick="_descargarPlaneIAWord(${i})" title="Descargar Word" style="background:rgba(41,128,185,0.07);border:1px solid rgba(41,128,185,0.18);border-radius:6px;padding:3px 9px;font-size:0.72rem;color:#1a5276;cursor:pointer;display:inline-flex;align-items:center;gap:3px" onmouseover="this.style.background='rgba(41,128,185,0.14)'" onmouseout="this.style.background='rgba(41,128,185,0.07)'">📝 Word</button>
      </div>`:'';
      return `<div class="ia-msg ${m.role}${m.loading?' loading':''}" id="iamsg${i}">${m.content.replace(/\*\*(.*?)\*\*/g,'<b>$1</b>').replace(/\*(.*?)\*/g,'<i>$1</i>').replace(/\n/g,'<br>')}${btnsHtml}${actionBtns}</div>`;
    }).join('');
  c.scrollTop=c.scrollHeight;
}

let _iaArchivoCtx=null;// {nombre,tipo,contenido}

async function _iaLeerArchivo(file){
  return new Promise((resolve,reject)=>{
    const ext=(file.name||'').split('.').pop().toLowerCase();
    const tipo=file.type||'';
    // Imágenes → base64 real para visión Gemini
    if(tipo.startsWith('image/')||['jpg','jpeg','png','gif','webp','bmp','svg'].includes(ext)){
      const fr=new FileReader();
      fr.onload=e=>{
        const dataUrl=e.target.result||'';
        const b64=dataUrl.indexOf(',')>-1?dataUrl.split(',')[1]:'';
        const mime=tipo||('image/'+(ext==='jpg'?'jpeg':ext));
        resolve({nombre:file.name,tipo:'imagen',contenido:'[Imagen adjunta para análisis visual: '+file.name+']',mimeType:mime,imageBase64:b64});
      };
      fr.onerror=e=>reject(new Error('FileReader error: '+(e.target?.error?.message||'desconocido')));
      fr.readAsDataURL(file);return;
    }
    // Texto plano, txt, csv, html, xml, json, md
    if(tipo.startsWith('text/')||['txt','csv','json','md','html','xml','log'].includes(ext)){
      const fr=new FileReader();
      fr.onload=e=>resolve({nombre:file.name,tipo:'texto',contenido:e.target.result.slice(0,12000)});
      fr.onerror=e=>reject(new Error('FileReader error: '+(e.target?.error?.message||'desconocido')));fr.readAsText(file,'UTF-8');return;
    }
    // PDF → leer como texto si es posible (texto embebido)
    if(ext==='pdf'||tipo==='application/pdf'){
      const fr=new FileReader();
      fr.onload=e=>{
        try{
          const arr=new Uint8Array(e.target.result);
          // Extraer texto crudo del PDF buscando streams de texto
          let raw='';
          for(let i=0;i<arr.length-1;i++){
            const c=arr[i];
            if(c>=32&&c<127) raw+=String.fromCharCode(c);
            else if(c===10||c===13) raw+='\n';
          }
          // Filtrar líneas con contenido real
          const lines=raw.split('\n').map(l=>l.trim()).filter(l=>l.length>3&&!/^[<>\/\[\]\\{}%0-9.+\-]+$/.test(l));
          const txt=lines.join('\n').replace(/\s{3,}/g,' ').slice(0,10000);
          resolve({nombre:file.name,tipo:'pdf',contenido:txt||'(PDF sin texto extraíble — puede ser escaneado)'});
        }catch(e2){resolve({nombre:file.name,tipo:'pdf',contenido:'(No fue posible extraer texto del PDF)'});}
      };
      fr.onerror=e=>reject(new Error('FileReader error: '+(e.target?.error?.message||'desconocido')));fr.readAsArrayBuffer(file);return;
    }
    // Word/Excel → intentar leer con SheetJS si está disponible, sino como binario
    if(['xlsx','xls','ods'].includes(ext)||tipo.includes('spreadsheet')||tipo.includes('excel')){
      const fr=new FileReader();
      fr.onload=e=>{
        try{
          if(window.XLSX){
            const wb=window.XLSX.read(e.target.result,{type:'array'});
            let txt='';
            wb.SheetNames.forEach(sn=>{
              const ws=wb.Sheets[sn];
              txt+=`\n[Hoja: ${sn}]\n${window.XLSX.utils.sheet_to_csv(ws).slice(0,4000)}`;
            });
            resolve({nombre:file.name,tipo:'excel',contenido:txt.slice(0,12000)});
          } else {
            resolve({nombre:file.name,tipo:'excel',contenido:'(Archivo Excel adjunto — SheetJS no disponible en este contexto)'});
          }
        }catch(e2){resolve({nombre:file.name,tipo:'excel',contenido:'(No fue posible leer el archivo Excel)'});}
      };
      fr.onerror=e=>reject(new Error('FileReader error: '+(e.target?.error?.message||'desconocido')));fr.readAsArrayBuffer(file);return;
    }
    // Docx/Word → extraer texto XML interno
    if(['docx','doc'].includes(ext)||tipo.includes('word')){
      const fr=new FileReader();
      fr.onload=e=>{
        try{
          // docx es un ZIP; intentar extraer word/document.xml como texto
          const arr=new Uint8Array(e.target.result);
          let raw='';for(let i=0;i<arr.length;i++)raw+=String.fromCharCode(arr[i]);
          // Buscar texto entre tags <w:t>
          const matches=raw.match(/<w:t[^>]*>([^<]+)<\/w:t>/g)||[];
          const txt=matches.map(m=>m.replace(/<[^>]+>/g,'')).join(' ').slice(0,10000);
          resolve({nombre:file.name,tipo:'word',contenido:txt||'(Word sin texto extraíble)'});
        }catch(e2){resolve({nombre:file.name,tipo:'word',contenido:'(No fue posible leer el archivo Word)'});}
      };
      fr.onerror=e=>reject(new Error('FileReader error: '+(e.target?.error?.message||'desconocido')));fr.readAsArrayBuffer(file);return;
    }
    // Fallback
    const fr=new FileReader();
    fr.onload=e=>resolve({nombre:file.name,tipo:'archivo',contenido:(typeof e.target.result==='string'?e.target.result:'(binario)').slice(0,8000)});
    fr.onerror=e=>reject(new Error('FileReader error: '+(e.target?.error?.message||'desconocido')));
    try{fr.readAsText(file,'UTF-8');}catch(e2){resolve({nombre:file.name,tipo:'archivo',contenido:'(No se pudo leer el archivo)'});}
  });
}

function iaAdjuntarArchivo(){
  const inp=document.getElementById('iaFileInput');if(!inp) return;
  inp.click();
}

async function iaOnFileChange(inp){
  if(!inp.files||!inp.files[0]) return;
  const file=inp.files[0];
  const badgeEl=document.getElementById('iaFileBadge');
  const labelEl=document.getElementById('iaFileBadgeLabel');
  if(badgeEl){badgeEl.style.display='flex';}
  if(labelEl){labelEl.textContent='⏳ Leyendo '+file.name.slice(0,20)+'...';}
  try{
    _iaArchivoCtx=await _iaLeerArchivo(file);
    if(labelEl){labelEl.textContent='📎 '+file.name.slice(0,24)+(file.name.length>24?'…':'');}
    if(badgeEl){badgeEl.style.display='flex';}
  }catch(e){
    _iaArchivoCtx=null;
    if(labelEl){labelEl.textContent='❌ Error al leer el archivo';}
    setTimeout(()=>{if(badgeEl)badgeEl.style.display='none';},3000);
  }
  inp.value='';
}

function iaQuitarArchivo(){
  _iaArchivoCtx=null;
  const badgeEl=document.getElementById('iaFileBadge');
  if(badgeEl)badgeEl.style.display='none';
}

function _iaGetCreditos(){
  if(!sesion) return {used:0,limit:30,fecha:new Date().toISOString().slice(0,10)};
  const hoy=new Date().toISOString().slice(0,10);
  const u=sesion.u||'_';
  const platSK=window._currentPlatSK||'';
  // Prioridad: límite por institución → límite global → 30
  const instLimits=(typeof gestorDB!=='undefined'&&gestorDB.iaLimitePorInst)||{};
  const defLimit=(platSK&&instLimits[platSK])||((typeof gestorDB!=='undefined'&&gestorDB.iaLimiteDefault)||30);
  if(!db.iaCreditos) db.iaCreditos={};
  const rec=db.iaCreditos[u];
  if(!rec||rec.fecha!==hoy){
    const lim=rec?(rec.limit||defLimit):defLimit;
    db.iaCreditos[u]={used:0,limit:lim,fecha:hoy};
  }
  return db.iaCreditos[u];
}
function _iaUsarCredito(){
  if(!sesion) return;
  const u=sesion.u||'_';
  const hoy=new Date().toISOString().slice(0,10);
  updDB(d=>{
    if(!d.iaCreditos) d.iaCreditos={};
    const platSK=window._currentPlatSK||'';
    const instLimits=(typeof gestorDB!=='undefined'&&gestorDB.iaLimitePorInst)||{};
    const defLimit=(platSK&&instLimits[platSK])||((typeof gestorDB!=='undefined'&&gestorDB.iaLimiteDefault)||30);
    const rec=d.iaCreditos[u]||{used:0,limit:defLimit,fecha:hoy};
    if(rec.fecha!==hoy){rec.used=0;rec.fecha=hoy;}
    rec.used=(rec.used||0)+1;
    d.iaCreditos[u]=rec;
    return d;
  });
}
function _iaSetLimiteUsuario(userId,nuevoLimite){
  const hoy=new Date().toISOString().slice(0,10);
  updDB(d=>{
    if(!d.iaCreditos) d.iaCreditos={};
    const rec=d.iaCreditos[userId]||{used:0,fecha:hoy};
    rec.limit=Math.max(1,nuevoLimite);
    if(rec.fecha!==hoy) rec.used=0;
    d.iaCreditos[userId]=rec;
    return d;
  });
  _showToast('✅ Límite actualizado a '+Math.max(1,nuevoLimite)+' créditos');
  renderApp();
}
async function iaEnviar(){
  if(_iaStreaming) return;
  const ta=document.getElementById('iaInput');
  const txt=(ta?ta.value.trim():'');
  if(!txt&&!_iaArchivoCtx) return;
  // ── Verificar créditos IA ──
  const _cred=_iaGetCreditos();
  if(_cred.used>=_cred.limit){
    _iaMsgs.push({role:'assistant',content:`⏸️ Has alcanzado el límite de **${_cred.limit} consultas pedagógicas** por el día de hoy.\n\n🌙 Tus créditos se reiniciarán automáticamente **mañana a las 12:00 de la noche**.\n\nSi necesitas más créditos hoy, contacta al administrador del sistema.`});
    iaRenderMsgs();
    return;
  }
  _iaUsarCredito();
  ta.value='';
  ta.style.height='40px';
  // Construir mensaje del usuario incluyendo contenido de archivo si existe
  let userContent=txt||'';
  if(_iaArchivoCtx){
    userContent+=(userContent?'\n\n':'')+`📎 **Archivo adjunto: ${_iaArchivoCtx.nombre}** (${_iaArchivoCtx.tipo})\n\`\`\`\n${_iaArchivoCtx.contenido}\n\`\`\``;
    _iaArchivoCtx=null;
    const badgeEl=document.getElementById('iaFileBadge');
    if(badgeEl)badgeEl.style.display='none';
  }
  _iaMsgs.push({role:'user',content:userContent});
  _iaMsgs.push({role:'assistant',content:'',loading:true});
  iaRenderMsgs();
  _iaStreaming=true;
  _setAvatarHablando(true);
  const sendBtn=document.getElementById('iaSend');
  if(sendBtn) sendBtn.disabled=true;
  const ctx=_iaGetCtx();
  const msgsSend=_iaMsgs.slice(0,-1).filter(m=>!m.loading);
  // Preparar imagen para visión si fue adjuntada
  const _imgSent=_iaArchivoCtx&&_iaArchivoCtx.tipo==='imagen'&&_iaArchivoCtx.imageBase64?{mimeType:_iaArchivoCtx.mimeType||'image/jpeg',data:_iaArchivoCtx.imageBase64}:null;
  try{
    const r=await fetch(API_BASE+'/api/inetis/ai/chat',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({messages:msgsSend,context:ctx,mode:window._iaEsPlaneacion?'planear':undefined,...(_imgSent?{imagePart:_imgSent}:{})})
    });
    if(!r.ok) throw new Error('HTTP '+r.status);
    let resp='';
    _iaMsgs[_iaMsgs.length-1]={role:'assistant',content:'',loading:false};
    if(r.body){
      const reader=r.body.getReader();const dec=new TextDecoder();
      let buf='';
      while(true){
        const {done,value}=await reader.read();
        if(done) break;
        buf+=dec.decode(value,{stream:true});
        const parts=buf.split('\n\n');
        buf=parts.pop()||'';
        for(const part of parts){
          if(!part.startsWith('data:')) continue;
          try{
            const d=JSON.parse(part.slice(5).trim());
            if(d.done) break;
            if(d.error){resp='❌ '+d.error;break;}
            if(d.content){resp+=d.content;_iaMsgs[_iaMsgs.length-1].content=resp;iaRenderMsgs();}
          }catch(e){}
        }
      }
    } else {
      const raw=await r.text();
      for(const line of raw.split('\n')){
        if(!line.startsWith('data:')) continue;
        try{const d=JSON.parse(line.slice(5).trim());if(d.content) resp+=d.content;}catch(e){}
      }
    }
    _iaMsgs[_iaMsgs.length-1]={role:'assistant',content:resp||'(sin respuesta)',loading:false};
    _iaSpeakText(resp||'');
    // Auto-guardar planeación cuando se genera completamente
    if(window._iaEsPlaneacion && resp && resp.length>300){
      setTimeout(()=>_guardarPlaneacionIA(true),500);
    }
  }catch(e){
    // Error de red o servidor — intentar respuesta inteligente local
    const _lastQ=((_iaMsgs.slice(0,-1).filter(m=>m.role==='user').pop()||{}).content||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    const _errMsg=String(e&&e.message||e||'');
    let _fbResp='';
    // Verificar si el error es falta de API key
    const _noKey=_errMsg.includes('503')||_errMsg.includes('GEMINI')||_errMsg.includes('configurada');
    if(_noKey){
      _fbResp='⚠️ **Servicio IA temporalmente no disponible.**\n\nPara activar el Asistente Adán con plenas capacidades (responde cualquier pregunta de cualquier tema), el administrador del sistema debe configurar la clave GEMINI_API_KEY en los Secretos del servidor.\n\n📌 Mientras tanto, aquí información del sistema:\n\n';
    }
    // Respuestas de apoyo local para preguntas del sistema
    if(/nota|calificac|planilla/.test(_lastQ)) _fbResp+='📊 **Planilla de Calificaciones**: Módulo "Planilla" → seleccione grado y período → toque la celda del estudiante → ingrese la nota de 0.0 a 5.0. Las notas van con borde amarillo (pendientes) y se aplican permanentemente al pulsar **"GUARDAR CAMBIOS"**. Descargue en Excel (con notas o en blanco) o genere PDF desde los botones de la sección "Gestión de Planilla Excel".';
    else if(/asistencia/.test(_lastQ)) _fbResp+='📋 **Asistencia**: Módulo "Asistencia" → seleccione grado y asignatura → marque **P** (Presente), **A** (Ausente) o **J** (Justificado). Descargue planillas en PDF desde la pestaña "Planillas".';
    else if(/boletin|informe|reporte/.test(_lastQ)) _fbResp+='📄 **Boletines**: Módulo "Informes" → "Boletines" → seleccione grado y período → "Generar PDF". Para estudiante individual, use la columna de acciones en el listado.';
    else if(/observador|disciplina|conducta/.test(_lastQ)) _fbResp+='📝 **Observador**: Módulo "Observador" → seleccione grado y estudiante → escriba la anotación y elija el tipo. Se registra con fecha automática.';
    else if(/horario/.test(_lastQ)) _fbResp+='🕐 **Horarios**: Módulo "Horarios" → seleccione el grado → asigne asignaturas a los bloques de la semana (lunes a viernes).';
    else if(/estudiante|alumno|matric/.test(_lastQ)) _fbResp+='👤 **Estudiantes**: "Configuración" → "Estudiantes" → "+ Nuevo". Puede cargar masivamente con el archivo Excel/CSV plantilla.';
    else if(/docente|profesor/.test(_lastQ)) _fbResp+='👩‍🏫 **Docentes**: "Configuración" → "Usuarios" → crear usuario con rol "Docente" y asignarle sus materias en Carga Académica.';
    else if(/contrasena|clave|password|acceso/.test(_lastQ)) _fbResp+='🔑 **Contraseñas**: Rector o admin puede restablecerlas en "Configuración" → "Usuarios". Estudiantes usan su número de documento como usuario y contraseña por defecto.';
    else if(/descriptor|logro|competencia/.test(_lastQ)) _fbResp+='📚 **Descriptores**: Módulo "Descriptores" → registre descripciones de desempeño por nivel (Superior/Alto/Básico/Bajo) para cada asignatura, grado y período. Se usan automáticamente en los boletines.';
    else if(/decreto|1290|evaluacion|escala|normativa/.test(_lastQ)) _fbResp+='📋 **Decreto 1290/2009**: Regula evaluación y promoción escolar en Colombia. Cada IE define su escala con mínimo 4 niveles. Esta institución usa escala numérica 0-5. La nivelación aplica a estudiantes con 1-2 áreas perdidas al final del año.';
    else if(/año|anio|lectivo|historico/.test(_lastQ)) _fbResp+='📅 **Años Lectivos**: Use el selector de año en la barra superior para cambiar entre años lectivos. "Iniciar Nuevo Año" archiva el actual y crea uno nuevo, copiando institución, grados y usuarios. Use "Importar desde Año Anterior" para traer carga académica, estudiantes (con promoción automática de grado) y descriptores.';
    else if(/excel|descargar|exportar/.test(_lastQ)) _fbResp+='📊 **Descargas**: En módulo "Planilla" → sección "Gestión de Planilla Excel" → "Descargar Excel (con notas)" o "Descargar Excel (en blanco)". También puede generar PDF. Para estudiantes: "Configuración" → "Estudiantes" → "Exportar Excel".';
    else if(/hola|buenos|buenas|saludos/.test(_lastQ)) _fbResp+='¡Hola! Soy **Adán**, tu asistente de inteligencia artificial. Cuando el servicio de IA esté completamente activo podré responder sobre cualquier tema. Por ahora puedo orientarte sobre todos los módulos del sistema. ¿En qué te ayudo?';
    else _fbResp+=((_noKey?'':'⚠️ Sin conexión al servicio IA. \n\n')+'Soy **Adán**, asistente académico del Gestor YC. Puedo orientarte sobre: Planilla de notas, Asistencia, Boletines, Observador, Horarios, Estudiantes, Descriptores, Años Lectivos, Descarga de Excel/PDF, y todos los módulos del sistema. ¿Cuál es tu consulta?');
    _iaMsgs[_iaMsgs.length-1]={role:'assistant',content:_fbResp,loading:false};
  }
  iaRenderMsgs();
  _iaStreaming=false;
  if(!_iaSoundEnabled) _setAvatarHablando(false);
  if(sendBtn) sendBtn.disabled=false;
  const ta2=document.getElementById('iaInput');if(ta2)ta2.focus();
}

function iaLimpiar(){
  _iaMsgs=[];
  _iaOpen=true;
  iaToggle();
  _iaOpen=false;
  setTimeout(()=>{_iaOpen=true;iaToggle();},50);
}

function iaIniciarVoz(){
  if(_iaVozActiva){iaDetenerVoz();return;}
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){alert('Su navegador no soporta reconocimiento de voz.\nUse Chrome o Edge.');return;}
  _iaRecognition=new SR();
  _iaRecognition.lang='es-CO';
  _iaRecognition.continuous=false;
  _iaRecognition.interimResults=true;
  _iaRecognition.maxAlternatives=1;
  const mic=document.getElementById('iaMic');
  const pill=document.getElementById('iaVozPill');
  _iaVozActiva=true;
  if(mic) mic.classList.add('active');
  if(pill) pill.classList.add('show');
  let _iaFinalTranscript='';
  _iaRecognition.onresult=ev=>{
    let final='';let interim='';
    for(let i=0;i<ev.results.length;i++){
      if(ev.results[i].isFinal) final+=ev.results[i][0].transcript;
      else interim+=ev.results[i][0].transcript;
    }
    _iaFinalTranscript=final||interim;
    const ta=document.getElementById('iaInput');
    if(ta){ta.value=_iaFinalTranscript.trim();ta.style.height='auto';ta.style.height=Math.min(ta.scrollHeight,100)+'px';}
    // Auto-enviar cuando hay resultado final
    if(final.trim()){setTimeout(()=>{iaDetenerVoz();setTimeout(()=>iaEnviar(),80);},150);}
  };
  _iaRecognition.onerror=ev=>{
    if(ev.error!=='no-speech') iaDetenerVoz();
  };
  _iaRecognition.onend=()=>{
    _iaVozActiva=false;
    if(mic) mic.classList.remove('active');
    if(pill) pill.classList.remove('show');
    _iaRecognition=null;
  };
  try{_iaRecognition.start();}catch(e){iaDetenerVoz();}
}

function iaDetenerVoz(){
  _iaVozActiva=false;
  if(_iaRecognition){try{_iaRecognition.stop();}catch(e){} _iaRecognition=null;}
  const mic=document.getElementById('iaMic');const pill=document.getElementById('iaVozPill');
  if(mic) mic.classList.remove('active');
  if(pill) pill.classList.remove('show');
}

function iaInputKeydown(e){
  if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();iaEnviar();}
  const ta=e.target;ta.style.height='auto';ta.style.height=Math.min(ta.scrollHeight,100)+'px';
}

