// NAVEGACIÓN POR VOZ — COMANDOS DE MÓDULOS
// ============================================================
let _navVozActiva=false;
let _navVozRecognition=null;

const MODULOS_VOZ={
  'planilla':['planilla','calificaciones','notas','grades'],
  'horarios':['horarios','schedule','horario'],
  'descriptores':['descriptores','descriptor','descriptive'],
  'asistencia':['asistencia','attendance','asisten'],
  'observador':['observador','observer','observa'],
  'actas':['documentos','actas','documents','docs','archivo'],
  'centros-interes':['centros','interes','interest','centro'],
  'adm-base':['configuracion','config','base','setting'],
  'adm-carga':['carga','docentes','maestros','teachers'],
  'adm-est':['estudiantes','students','matricula','enrollment'],
  'adm-rep':['informes','reports','consolidado','consolidation'],
  'contacto':['contacto','contact','notificaciones','notifications']
};

function iniciarNavVoz(){
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){alert('Su navegador no soporta reconocimiento de voz.\nUse Chrome o Edge.');return;}
  _navVozRecognition=new SR();
  _navVozRecognition.lang='es-CO';
  _navVozRecognition.continuous=true;
  _navVozRecognition.interimResults=true;
  _navVozActiva=true;
  const btn=document.getElementById('navVozBtn');
  if(btn){btn.textContent='🔴 Escuchando...';btn.style.background='#c0392b';btn.style.animation='pulse 1s infinite';}
  if(!document.getElementById('_navVozStyle')){const s=document.createElement('style');s.id='_navVozStyle';s.textContent='@keyframes pulse{0%{opacity:1}50%{opacity:0.6}100%{opacity:1}}';document.head.appendChild(s);}
  _navVozRecognition.onresult=ev=>{
    let final='';
    for(let i=ev.resultIndex;i<ev.results.length;i++){
      if(ev.results[i].isFinal) final+=ev.results[i][0].transcript;
    }
    if(final){procesarComandoVoz(final.toLowerCase());}
  };
  _navVozRecognition.onerror=ev=>{
    if(ev.error!=='no-speech') detenerNavVoz();
  };
  _navVozRecognition.onend=()=>{
    if(_navVozActiva){try{_navVozRecognition.start();}catch(e){detenerNavVoz();}}
  };
  try{_navVozRecognition.start();}catch(e){detenerNavVoz();}
}

function detenerNavVoz(){
  _navVozActiva=false;
  if(_navVozRecognition){try{_navVozRecognition.stop();}catch(e){} _navVozRecognition=null;}
  const btn=document.getElementById('navVozBtn');
  if(btn){btn.textContent='🗣️ Voz';btn.style.background='#3498db';btn.style.animation='';}
}

function toggleNavVoz(){
  if(_navVozActiva){detenerNavVoz();}else{iniciarNavVoz();}
}

function procesarComandoVoz(texto){
  for(const [modulo,palabras] of Object.entries(MODULOS_VOZ)){
    for(const palabra of palabras){
      if(texto.includes(palabra)){
        // Detener reconocimiento antes de navegar
        detenerNavVoz();
        const btn=document.querySelector('[onclick="navTo(\''+modulo+'\')"]');
        const nombreMod=btn?btn.textContent.trim():modulo;
        if(btn){btn.click();}else{navTo(modulo);}
        // Notificación visual sin alert bloqueante
        const toast=document.createElement('div');
        toast.style.cssText='position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:#27ae60;color:#fff;padding:10px 22px;border-radius:24px;font-size:0.9rem;font-weight:bold;z-index:20000;box-shadow:0 4px 16px rgba(0,0,0,.3);pointer-events:none';
        toast.textContent='🎯 Navegando a: '+nombreMod;
        document.body.appendChild(toast);
        setTimeout(()=>{try{toast.remove();}catch(e){}},2500);
        return;
      }
    }
  }
  // Módulo no reconocido — también detenemos y mostramos aviso
  detenerNavVoz();
  const toast=document.createElement('div');
  toast.style.cssText='position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:#e67e22;color:#fff;padding:10px 22px;border-radius:24px;font-size:0.88rem;font-weight:bold;z-index:20000;box-shadow:0 4px 16px rgba(0,0,0,.3);pointer-events:none';
  toast.textContent='❓ No reconocido. Diga: Planilla, Asistencia, Horarios, etc.';
  document.body.appendChild(toast);
  setTimeout(()=>{try{toast.remove();}catch(e){}},3000);
}

