function _prefillPreMatricula(){
  if(!sesion||!sesion.estId) return;
  const est=db.ests.find(e=>e.id===sesion.estId);
  if(!est) return;
  const s=(id,v)=>{const el=document.getElementById(id);if(el&&v)el.value=v;};
  s('pm_apellidos',est.apellidos||(est.n||'').split(' ').slice(0,2).join(' '));
  s('pm_nombres',est.nombres||(est.n||'').split(' ').slice(2).join(' ')||est.n);
  s('pm_numDoc',est.numDoc);
  s('pm_tipoDoc',est.tipoDoc||'T.I.');
  s('pm_fechaNac',est.fechaNac);
  s('pm_gradoActual',est.g);
  s('pm_acudiente',est.acudiente);
  s('pm_numDocAcud',est.numDocAcud);
  s('pm_tipoDocAcud',est.tipoDocAcud||'C.C.');
  s('pm_telAcud',est.tel);
  s('pm_emailAcud',est.email);
  // Pre-seleccionar tipo según situación
  const tipoEl=document.getElementById('pm_tipo');
  if(tipoEl) tipoEl.value='antiguo';
  _pmTipoChange();
}

